// The conformance suite: what Carrel's health check runs against a live site. Each check names what
// it proves. Every write it sends by default must be refused, so a conforming site is never changed
// by it. The one exception is opt-in (probeMediaUpload): it uploads a file of its own, then deletes
// that file and no other.

import {
  BacklinkList,
  ContentDoc,
  HookRunList,
  MEDIA_LENSES,
  MediaBulkResult,
  ContentList,
  ErrorBody,
  PreviewLink,
  PreviewLinkList,
  RenameResult,
  RevisionList,
  RevisionSource,
  MediaDeleteResult,
  MediaDetail,
  MediaItem,
  MediaList,
  MentionList,
  Meta,
  NotFoundReport,
  PREFIX,
  WriteResult,
  schemaHash,
  type Meta as MetaType,
} from "./contract.js";
import { splitSource } from "@drdustinedwards/site-helpers/frontmatter";
import {
  postFieldsOf,
  searchFieldsOf,
  setPostFields,
  setSearchFields,
  type PostValues,
  type SearchValues,
} from "./frontmatter.js";

export interface ConformanceConfig {
  baseUrl: string;
  key: string;
  fetch?: typeof fetch;
  /** Sends the stale-version write and the refused media writes. On by default; a conforming site refuses them and changes nothing. */
  probeWrites?: boolean;
  /**
   * Uploads a 1x1 PNG of its own, reads it back and deletes it (v0.2.0). Off by default: it is a
   * real write to the site's storage, though it deletes only the file it uploaded.
   */
  probeMediaUpload?: boolean;
  /**
   * v0.22.0 (M1): makes a probe post of its own under a unique id, takes it through its life, and deletes it, even when a
   * step fails. Beside `probeWrites`, and off by default, since the post is published for a moment: its hooks run, and a
   * feed or a search engine may see it (its `noindex` is set where the site renders one). A site that cannot delete
   * content skips it, since the probe could not clean up after itself.
   */
  probePosts?: boolean;
  /** How long the hooks probe waits for every hook to record its run, in milliseconds. 5000 by default. */
  hookWaitMs?: number;
}

export interface ConformanceCheck {
  name: string;
  ok: boolean;
  detail: string;
}

/** One probe the run made or passed over (v0.22.0, M2): every check is one, and `skipped` ones say why in `detail`. */
export interface ConformanceProbe {
  name: string;
  ok: boolean;
  skipped?: boolean;
  detail?: string;
}

export interface ConformanceReport {
  ok: boolean;
  checks: ConformanceCheck[];
  /** v0.22.0: every probe in the order it ran, and every one passed over, with why. */
  probes: ConformanceProbe[];
}

/** An id no site should hold, so the refused write names nothing real. */
const PROBE_ID = "carrel-conformance-probe";
/** A media id no site should hold: the refused delete names nothing real. */
const MEDIA_PROBE_ID = "carrel-conformance-probe/no-such-file.png";
/** A type no site accepts, for the refused upload. */
const PROBE_TYPE = "application/x-carrel-conformance-probe";
/** The smallest valid PNG: one transparent pixel. */
const PROBE_PNG = Uint8Array.from(
  atob(
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==",
  ),
  (c) => c.charCodeAt(0),
);
const STALE_VERSION = "carrel-conformance-stale-version";
/** A mention id no site should hold: the refused mention writes name nothing real. */
const MENTION_PROBE_ID = "carrel-conformance-probe";

export async function runConformance(config: ConformanceConfig): Promise<ConformanceReport> {
  const doFetch = config.fetch ?? fetch;
  const origin = config.baseUrl.replace(/\/+$/, "");
  const auth = { authorization: `Bearer ${config.key}` };
  const checks: ConformanceCheck[] = [];
  const probes: ConformanceProbe[] = [];
  const skip = (name: string, why: string) =>
    void probes.push({ name, ok: true, skipped: true, detail: why });
  // v0.17.0: a fresh change id for every probe write, since a site with `replay` keeps a refused write's answer under its
  // change id and would refuse the same id on another probe as a different request.
  const run = crypto.randomUUID().slice(0, 8);
  let sent = 0;
  const probe = () => `conformance-probe-${run}-${++sent}`;

  async function check(name: string, run: () => Promise<string>): Promise<boolean> {
    let result: ConformanceCheck;
    try {
      result = { name, ok: true, detail: await run() };
    } catch (error) {
      result = { name, ok: false, detail: error instanceof Error ? error.message : String(error) };
    }
    checks.push(result);
    probes.push({ ...result });
    return result.ok;
  }

  async function errorCode(response: Response): Promise<string | null> {
    try {
      const parsed = ErrorBody.safeParse(await response.json());
      return parsed.success ? parsed.data.error : null;
    } catch {
      return null;
    }
  }

  function expectStatus(response: Response, status: number, what: string) {
    if (response.status !== status)
      throw new Error(`${what}: expected ${status}, got ${response.status}`);
  }

  let meta: MetaType | null = null;

  await check("meta: answers with this contract's schema hash", async () => {
    const response = await doFetch(`${origin}${PREFIX}/meta`, { headers: auth });
    expectStatus(response, 200, "meta");
    meta = Meta.parse(await response.json());
    const ours = await schemaHash();
    if (meta.schemaHash !== ours) {
      throw new Error(
        `schema hash ${meta.schemaHash.slice(0, 12)} is not ${ours.slice(0, 12)} (site on package ${meta.packageVersion})`,
      );
    }
    return `package ${meta.packageVersion}, hash ${ours.slice(0, 12)}`;
  });

  await check("no key: refused", async () => {
    const response = await doFetch(`${origin}${PREFIX}/meta`);
    expectStatus(response, 401, "no key");
    return "401";
  });

  await check("wrong key: refused", async () => {
    const response = await doFetch(`${origin}${PREFIX}/meta`, {
      headers: { authorization: `Bearer ${config.key}x` },
    });
    expectStatus(response, 401, "wrong key");
    return "401";
  });

  await check("key off-prefix: not served", async () => {
    const paths = ["/api/carrel/v2/meta", `${PREFIX}x/meta`, "/api/carrel/meta"];
    for (const path of paths) {
      const response = await doFetch(`${origin}${path}`, { headers: auth });
      if (response.ok) throw new Error(`${path} answered ${response.status} to the Carrel key`);
    }
    return paths.join(", ");
  });

  await check("unknown route: refused", async () => {
    const response = await doFetch(`${origin}${PREFIX}/no-such-route`, { headers: auth });
    expectStatus(response, 404, "unknown route");
    const code = await errorCode(response);
    if (code !== "not-found")
      throw new Error(`error code ${code ?? "missing"}, expected not-found`);
    return "404 not-found";
  });

  await check("content list: answers in the contract's shape", async () => {
    const response = await doFetch(`${origin}${PREFIX}/content?limit=1`, { headers: auth });
    expectStatus(response, 200, "content list");
    const list = ContentList.parse(await response.json());
    return `${list.items.length} item(s) on the first page`;
  });

  if (config.probeWrites !== false) {
    await check("stale expectedVersion: refused", async () => {
      const response = await doFetch(`${origin}${PREFIX}/content/${PROBE_ID}/draft`, {
        method: "PUT",
        headers: { ...auth, "content-type": "application/json" },
        body: JSON.stringify({
          source: "# Conformance probe\n\nA conforming site refuses this write.\n",
          expectedVersion: STALE_VERSION,
          changeId: probe(),
        }),
      });
      expectStatus(response, 409, "stale write");
      const code = await errorCode(response);
      if (code !== "version-conflict")
        throw new Error(`error code ${code ?? "missing"}, expected version-conflict`);
      return "409 version-conflict";
    });
  }

  // ---------- v0.3.0: the source at a revision, and the optional content delete

  await check("revision source of an unknown id: not found", async () => {
    const response = await doFetch(
      `${origin}${PREFIX}/content/${PROBE_ID}/revisions/${STALE_VERSION}`,
      { headers: auth },
    );
    expectStatus(response, 404, "unknown revision");
    const code = await errorCode(response);
    if (code !== "not-found")
      throw new Error(`error code ${code ?? "missing"}, expected not-found`);
    return "404 not-found";
  });

  await check("revision source: the newest revision of the first item opens", async () => {
    const list = ContentList.parse(
      await (await doFetch(`${origin}${PREFIX}/content?limit=1`, { headers: auth })).json(),
    );
    const first = list.items[0];
    if (!first) return "no items to read a revision of";
    const revisions = RevisionList.parse(
      await (
        await doFetch(`${origin}${PREFIX}/content/${encodeURIComponent(first.id)}/revisions`, {
          headers: auth,
        })
      ).json(),
    );
    const newest = revisions.items[0];
    if (!newest) return `${first.id} has no revisions`;
    const response = await doFetch(
      `${origin}${PREFIX}/content/${encodeURIComponent(first.id)}/revisions/${encodeURIComponent(newest.version)}`,
      { headers: auth },
    );
    expectStatus(response, 200, "revision source");
    const opened = RevisionSource.parse(await response.json());
    if (opened.version !== newest.version)
      throw new Error(`asked for ${newest.version}, got ${opened.version}`);
    return `${first.id} at ${newest.version}`;
  });

  if (config.probeWrites !== false) {
    // Only ever the probe id: a site that wrongly accepts one of these deletes nothing real.
    const deleteUrl = `${origin}${PREFIX}/content/${PROBE_ID}?expectedVersion=${STALE_VERSION}&changeId=${probe()}`;
    await check("content delete without a key: refused", async () => {
      expectStatus(await doFetch(deleteUrl, { method: "DELETE" }), 401, "delete without a key");
      expectStatus(
        await doFetch(deleteUrl, {
          method: "DELETE",
          headers: { authorization: `Bearer ${config.key}x` },
        }),
        401,
        "delete with a wrong key",
      );
      return "401";
    });
    await check(
      "content delete of an unknown id: refused, or not implemented where the site has no delete",
      async () => {
        const response = await doFetch(deleteUrl, { method: "DELETE", headers: auth });
        const offered = (meta as MetaType | null)?.capabilities.contentDelete === true;
        expectStatus(
          response,
          offered ? 404 : 501,
          offered ? "unknown content delete" : "content delete on a site without it",
        );
        const code = await errorCode(response);
        const expected = offered ? "not-found" : "not-implemented";
        if (code !== expected)
          throw new Error(`error code ${code ?? "missing"}, expected ${expected}`);
        return offered ? "404 not-found" : "501 not-implemented";
      },
    );
    await check(
      "content tags of an unknown id: refused, or not implemented where the site keeps no tags",
      async () => {
        const response = await doFetch(`${origin}${PREFIX}/content/${PROBE_ID}/tags`, {
          method: "PUT",
          headers: { ...auth, "content-type": "application/json" },
          body: JSON.stringify({
            tags: ["conformance-probe"],
            expectedVersion: STALE_VERSION,
            changeId: probe(),
          }),
        });
        const offered = (meta as MetaType | null)?.capabilities.contentTags === true;
        expectStatus(
          response,
          offered ? 404 : 501,
          offered ? "unknown content tags" : "content tags on a site without them",
        );
        const code = await errorCode(response);
        const expected = offered ? "not-found" : "not-implemented";
        if (code !== expected)
          throw new Error(`error code ${code ?? "missing"}, expected ${expected}`);
        return offered ? "404 not-found" : "501 not-implemented";
      },
    );
    await check(
      "schedule read and cancel of an unknown id: refused, or not implemented where the site has no scheduled updates",
      async () => {
        const path = `${origin}${PREFIX}/content/${PROBE_ID}/schedule`;
        const offered = (meta as MetaType | null)?.capabilities.scheduledUpdates === true;
        const expected = offered ? "not-found" : "not-implemented";
        for (const response of [
          await doFetch(path, { headers: auth }),
          await doFetch(`${path}?expectedVersion=${STALE_VERSION}&changeId=${probe()}`, {
            method: "DELETE",
            headers: auth,
          }),
        ]) {
          expectStatus(
            response,
            offered ? 404 : 501,
            offered ? "unknown schedule" : "schedule on a site without scheduled updates",
          );
          const code = await errorCode(response);
          if (code !== expected)
            throw new Error(`error code ${code ?? "missing"}, expected ${expected}`);
        }
        return offered ? "404 not-found" : "501 not-implemented";
      },
    );
  }

  // ---------- media (v0.2.0), only for a site that offers it

  const capabilities = (meta as MetaType | null)?.capabilities;
  if (capabilities?.media) {
    await check("media: upload limits declared", async () => {
      const limits = capabilities.mediaUpload;
      if (!limits) throw new Error("capabilities.media is true but mediaUpload is missing");
      return `${limits.maxBytes} bytes, ${limits.types.join(", ")}`;
    });

    await check("media list: answers in the contract's shape", async () => {
      const response = await doFetch(`${origin}${PREFIX}/media?limit=1`, { headers: auth });
      expectStatus(response, 200, "media list");
      const list = MediaList.parse(await response.json());
      return `${list.items.length} file(s) on the first page`;
    });

    // v0.6.0 lenses: every one the site names answers in shape; one it does not name answers 501.
    await check(
      "media lenses: each one the site names answers, and one it does not is not implemented",
      async () => {
        const named = capabilities.mediaLenses ?? [];
        for (const lens of MEDIA_LENSES) {
          const response = await doFetch(`${origin}${PREFIX}/media?lens=${lens}&limit=1`, {
            headers: auth,
          });
          if (named.includes(lens)) {
            expectStatus(response, 200, `media lens ${lens}`);
            MediaList.parse(await response.json());
          } else {
            expectStatus(response, 501, `media lens ${lens} on a site that does not name it`);
          }
        }
        return named.length > 0 ? `answers ${named.join(", ")}` : "501 for every lens";
      },
    );

    if (config.probeWrites !== false) {
      await check("media delete of an unknown id: refused", async () => {
        const response = await doFetch(
          `${origin}${PREFIX}/media/${encodeURIComponent(MEDIA_PROBE_ID)}?changeId=${probe()}`,
          { method: "DELETE", headers: auth },
        );
        expectStatus(response, 404, "unknown media delete");
        const code = await errorCode(response);
        if (code !== "not-found")
          throw new Error(`error code ${code ?? "missing"}, expected not-found`);
        return "404 not-found";
      });

      await check("media upload of a type the site does not accept: refused", async () => {
        const response = await doFetch(
          `${origin}${PREFIX}/media?filename=carrel-conformance-probe.bin&alt=Conformance%20probe&changeId=${probe()}`,
          {
            method: "POST",
            headers: { ...auth, "content-type": PROBE_TYPE },
            body: "A conforming site refuses this upload.",
          },
        );
        expectStatus(response, 400, "disallowed upload");
        const code = await errorCode(response);
        if (code !== "invalid")
          throw new Error(`error code ${code ?? "missing"}, expected invalid`);
        return "400 invalid";
      });

      // v0.4.0 writes. Each is optional: where the site declares the capability, the probe is refused as
      // a real error; where it does not, the same request must answer 501. Nothing here can change a file.
      const probeId = encodeURIComponent(MEDIA_PROBE_ID);
      const send = (method: string, path: string, body: unknown) =>
        doFetch(`${origin}${PREFIX}${path}`, {
          method,
          headers: { ...auth, "content-type": "application/json" },
          body: JSON.stringify(body),
        });
      const stale = { expectedVersion: STALE_VERSION, changeId: probe() };

      async function refusedOrAbsent(
        offered: boolean,
        response: Response,
        status: number,
        code: string,
        what: string,
      ) {
        if (!offered) {
          expectStatus(response, 501, `${what} without the capability`);
          const got = await errorCode(response);
          if (got !== "not-implemented")
            throw new Error(`error code ${got ?? "missing"}, expected not-implemented`);
          return "501 not-implemented";
        }
        expectStatus(response, status, what);
        const got = await errorCode(response);
        if (got !== code) throw new Error(`error code ${got ?? "missing"}, expected ${code}`);
        return `${status} ${code}`;
      }

      const writes: Array<[string, boolean | undefined, string, string, unknown]> = [
        ["alt", capabilities.mediaAlt, "PUT", "alt", { alt: "probe", ...stale }],
        ["tags", capabilities.mediaTags, "PUT", "tags", { tags: ["probe"], ...stale }],
        ["trash", capabilities.mediaTrash, "POST", "trash", stale],
        ["restore", capabilities.mediaTrash, "POST", "restore", stale],
        ["focus", capabilities.mediaFocus, "PUT", "focus", { focus: "0.5x0.5", ...stale }],
        ["caption", capabilities.mediaCaption, "PUT", "caption", { caption: "probe", ...stale }],
        // v0.13.0
        [
          "credit",
          capabilities.mediaCredit,
          "PUT",
          "credit",
          { credit: "probe", license: "", sourceUrl: null, licenseExpires: null, ...stale },
        ],
        ["transform", capabilities.mediaTransform, "POST", "transform", { op: "flip-h", ...stale }],
        ["revert", capabilities.mediaHistory, "POST", "revert", { to: "probe", ...stale }],
      ];
      for (const [name, offered, method, route, body] of writes) {
        await check(
          `media ${name} of an unknown id: refused, or not implemented where the site lacks it`,
          async () =>
            refusedOrAbsent(
              Boolean(offered),
              await send(method, `/media/${probeId}/${route}`, body),
              404,
              "not-found",
              `media ${name}`,
            ),
        );
      }

      // v0.13.0 reads of the probe id: a site answers 404 before it would ask its model anything.
      const reads: Array<[string, boolean | undefined, string]> = [
        ["history", capabilities.mediaHistory, "history"],
        ["suggestions", capabilities.mediaSuggestions, "suggestions"],
      ];
      for (const [name, offered, route] of reads) {
        await check(
          `media ${name} of an unknown id: refused, or not implemented where the site lacks it`,
          async () =>
            refusedOrAbsent(
              Boolean(offered),
              await doFetch(`${origin}${PREFIX}/media/${probeId}/${route}`, { headers: auth }),
              404,
              "not-found",
              `media ${name}`,
            ),
        );
      }

      // An import of an http address is refused before anything is fetched.
      await check(
        "media import of an http address: refused, or not implemented where the site lacks it",
        async () =>
          refusedOrAbsent(
            Boolean(capabilities.mediaImport),
            await send("POST", "/media/import", {
              url: "http://example.com/a.png",
              changeId: probe(),
            }),
            400,
            "invalid",
            "media import over http",
          ),
      );

      await check(
        "media alt with a body outside the contract: refused, or not implemented where the site lacks it",
        async () =>
          refusedOrAbsent(
            Boolean(capabilities.mediaAlt),
            await send("PUT", `/media/${probeId}/alt`, { alt: 7 }),
            400,
            "invalid",
            "malformed alt",
          ),
      );

      await check(
        "media focus outside 0 to 1: refused, or not implemented where the site lacks it",
        async () =>
          refusedOrAbsent(
            Boolean(capabilities.mediaFocus),
            await send("PUT", `/media/${probeId}/focus`, { focus: "2x2", ...stale }),
            400,
            "invalid",
            "focus outside the picture",
          ),
      );

      // v0.10.0: a replace of the probe id, in a type the site accepts, is a 404 before any byte is read.
      await check(
        "media replace of an unknown id: refused, or not implemented where the site lacks it",
        async () => {
          const type = capabilities.mediaUpload?.types[0] ?? "image/png";
          const response = await doFetch(
            `${origin}${PREFIX}/media/${probeId}/file?filename=probe&expectedVersion=${STALE_VERSION}&changeId=${probe()}`,
            {
              method: "PUT",
              headers: { ...auth, "content-type": type },
              body: new Uint8Array([0]),
            },
          );
          return refusedOrAbsent(
            Boolean(capabilities.mediaReplace),
            response,
            404,
            "not-found",
            "media replace",
          );
        },
      );

      await check(
        "media bulk: an unknown id is that file's own not-found, and the request answers 200",
        async () => {
          const response = await send("POST", "/media/bulk", {
            op: "trash",
            items: [{ id: MEDIA_PROBE_ID, ...stale }],
          });
          if (!capabilities.mediaTrash)
            return refusedOrAbsent(false, response, 200, "", "media bulk trash");
          expectStatus(response, 200, "media bulk");
          const result = MediaBulkResult.parse(await response.json());
          const only = result.results[0];
          if (result.results.length !== 1 || !only || only.ok || only.error !== "not-found") {
            throw new Error(
              `expected one failed not-found outcome, got ${JSON.stringify(result.results)}`,
            );
          }
          return "200, not-found for the file";
        },
      );

      await check(
        "media bulk tag op with no tags: refused, or not implemented where the site lacks tags",
        async () =>
          refusedOrAbsent(
            Boolean(capabilities.mediaTags),
            await send("POST", "/media/bulk", {
              op: "add-tags",
              items: [{ id: MEDIA_PROBE_ID, ...stale }],
            }),
            400,
            "invalid",
            "bulk add-tags without tags",
          ),
      );

      // Empty-trash deletes real files, so only its refusal of a malformed body is probed.
      await check(
        "media empty trash with a body outside the contract: refused, or not implemented where the site has no trash",
        async () =>
          refusedOrAbsent(
            Boolean(capabilities.mediaTrash),
            await send("POST", "/media/trash/empty", {}),
            400,
            "invalid",
            "malformed empty trash",
          ),
      );
    }

    if (config.probeMediaUpload && capabilities.mediaUpload?.types.includes("image/png")) {
      await check("media round trip: upload, read, delete its own file", async () => {
        const up = await doFetch(
          `${origin}${PREFIX}/media?filename=carrel-conformance-probe.png&alt=Conformance%20probe&changeId=${probe()}`,
          {
            method: "POST",
            headers: { ...auth, "content-type": "image/png" },
            body: new Blob([PROBE_PNG]),
          },
        );
        expectStatus(up, 201, "upload");
        const item = MediaItem.parse(await up.json());
        const path = `${origin}${PREFIX}/media/${encodeURIComponent(item.id)}`;
        const read = await doFetch(path, { headers: auth });
        expectStatus(read, 200, "read back");
        const detail = MediaDetail.parse(await read.json());
        if (detail.usedBy.length > 0)
          throw new Error(`its own new file is reported in use: ${JSON.stringify(detail.usedBy)}`);
        // Only the id the site just gave this upload: never any other file.
        const del = await doFetch(`${path}?changeId=${probe()}`, {
          method: "DELETE",
          headers: auth,
        });
        expectStatus(del, 200, "delete");
        MediaDeleteResult.parse(await del.json());
        expectStatus(await doFetch(path, { headers: auth }), 404, "after delete");
        return `uploaded and deleted ${item.id}`;
      });
    }
  }

  // ---------- mentions (v0.5.0): checked on every site, since a site without the group must say 501

  const hasMentions = capabilities?.mentions === true;
  const mentionPath = `${origin}${PREFIX}/mentions`;
  const post = (url: string, payload: unknown, headers: Record<string, string> = auth) =>
    doFetch(url, {
      method: "POST",
      headers: { ...headers, "content-type": "application/json" },
      body: JSON.stringify(payload),
    });

  await check("mentions: advertised in capabilities, or answered 501", async () => {
    const response = await doFetch(`${mentionPath}?limit=1`, { headers: auth });
    if (hasMentions) {
      expectStatus(response, 200, "mentions list");
      const list = MentionList.parse(await response.json());
      return `${list.items.length} mention(s) on the first page`;
    }
    expectStatus(response, 501, "mentions list on a site without the group");
    const code = await errorCode(response);
    if (code !== "not-implemented")
      throw new Error(`error code ${code ?? "missing"}, expected not-implemented`);
    return "501 not-implemented";
  });

  if (config.probeWrites !== false) {
    // The writes below are all refused before any change: no key, an unknown id, a stale version, a body with no change id.
    await check("mentions writes without a key or with a wrong key: refused", async () => {
      const wrong = { authorization: `Bearer ${config.key}x` };
      const body = { decision: "approve", expectedVersion: STALE_VERSION, changeId: probe() };
      for (const headers of [{}, wrong]) {
        expectStatus(
          await post(`${mentionPath}/${MENTION_PROBE_ID}/decide`, body, headers),
          401,
          "decide without the key",
        );
        expectStatus(
          await doFetch(
            `${mentionPath}/${MENTION_PROBE_ID}?expectedVersion=${STALE_VERSION}&changeId=${probe()}`,
            { method: "DELETE", headers },
          ),
          401,
          "delete without the key",
        );
        expectStatus(
          await post(`${mentionPath}/sweep`, { changeId: probe() }, headers),
          401,
          "sweep without the key",
        );
      }
      return "401";
    });

    await check(
      "mention decide of an unknown id: refused, or not implemented where the site has no mentions",
      async () => {
        const response = await post(`${mentionPath}/${MENTION_PROBE_ID}/decide`, {
          decision: "approve",
          expectedVersion: STALE_VERSION,
          changeId: probe(),
        });
        expectStatus(
          response,
          hasMentions ? 404 : 501,
          hasMentions ? "unknown mention decide" : "mention decide on a site without mentions",
        );
        const expected = hasMentions ? "not-found" : "not-implemented";
        const code = await errorCode(response);
        if (code !== expected)
          throw new Error(`error code ${code ?? "missing"}, expected ${expected}`);
        return hasMentions ? "404 not-found" : "501 not-implemented";
      },
    );

    await check(
      "mention delete of an unknown id: refused, or not implemented where the site has no mentions",
      async () => {
        const response = await doFetch(
          `${mentionPath}/${MENTION_PROBE_ID}?expectedVersion=${STALE_VERSION}&changeId=${probe()}`,
          { method: "DELETE", headers: auth },
        );
        expectStatus(
          response,
          hasMentions ? 404 : 501,
          hasMentions ? "unknown mention delete" : "mention delete on a site without mentions",
        );
        const expected = hasMentions ? "not-found" : "not-implemented";
        const code = await errorCode(response);
        if (code !== expected)
          throw new Error(`error code ${code ?? "missing"}, expected ${expected}`);
        return hasMentions ? "404 not-found" : "501 not-implemented";
      },
    );

    await check(
      "mention reset of an unknown id: refused, or not implemented where the site has no reset",
      async () => {
        const offered = hasMentions && capabilities?.mentionReset === true;
        const response = await post(`${mentionPath}/${MENTION_PROBE_ID}/decide`, {
          decision: "reset",
          expectedVersion: STALE_VERSION,
          changeId: probe(),
        });
        expectStatus(
          response,
          offered ? 404 : 501,
          offered ? "unknown mention reset" : "mention reset on a site without it",
        );
        const expected = offered ? "not-found" : "not-implemented";
        const code = await errorCode(response);
        if (code !== expected)
          throw new Error(`error code ${code ?? "missing"}, expected ${expected}`);
        return offered ? "404 not-found" : "501 not-implemented";
      },
    );

    if (hasMentions) {
      await check(
        "mention decide on a stale version: refused, whatever mention is first",
        async () => {
          const list = MentionList.parse(
            await (await doFetch(`${mentionPath}?limit=1`, { headers: auth })).json(),
          );
          const first = list.items[0];
          if (!first) return "no mentions to write against";
          const response = await post(`${mentionPath}/${encodeURIComponent(first.id)}/decide`, {
            decision: "reject",
            expectedVersion: STALE_VERSION,
            changeId: probe(),
          });
          expectStatus(response, 409, "stale mention decision");
          const code = await errorCode(response);
          if (code !== "version-conflict")
            throw new Error(`error code ${code ?? "missing"}, expected version-conflict`);
          // A 409 is only a refusal if nothing changed: read the mention again.
          const after = MentionList.parse(
            await (await doFetch(`${mentionPath}?limit=1`, { headers: auth })).json(),
          ).items.find((m) => m.id === first.id);
          if (!after || after.version !== first.version || after.status !== first.status) {
            throw new Error(
              `mention ${first.id} changed under a refused decision (version ${first.version} to ${after?.version ?? "gone"})`,
            );
          }
          return `409 version-conflict on mention ${first.id}, unchanged`;
        },
      );

      await check(
        "mention sweep with no change id: refused before anything is removed",
        async () => {
          const response = await post(`${mentionPath}/sweep`, {});
          expectStatus(response, 400, "sweep without a change id");
          return "400 invalid";
        },
      );

      await check("mentions list with an unknown status: refused", async () => {
        const response = await doFetch(`${mentionPath}?status=carrel-conformance-probe`, {
          headers: auth,
        });
        expectStatus(response, 400, "unknown status");
        return "400 invalid";
      });
    }
  }

  // ---------- insight (v0.16.0): the 404 report, read only, so checked whatever probeWrites says

  const hasNotFound = capabilities?.insightNotFound === true;
  const notFoundPath = `${origin}${PREFIX}/insight/not-found`;

  await check("not-found report: advertised in capabilities, or answered 501", async () => {
    const response = await doFetch(`${notFoundPath}?days=7&limit=5`, { headers: auth });
    if (hasNotFound) {
      expectStatus(response, 200, "not-found report");
      const { rows } = NotFoundReport.parse(await response.json());
      if (rows.length > 5) throw new Error(`${rows.length} rows for a limit of 5`);
      return `${rows.length} missing path(s) in 7 days`;
    }
    expectStatus(response, 501, "not-found report on a site without it");
    const code = await errorCode(response);
    if (code !== "not-implemented")
      throw new Error(`error code ${code ?? "missing"}, expected not-implemented`);
    return "501 not-implemented";
  });

  if (hasNotFound) {
    await check("not-found report past 90 days: refused", async () => {
      expectStatus(await doFetch(`${notFoundPath}?days=91`, { headers: auth }), 400, "days=91");
      return "400 invalid";
    });
  }

  // ---------- v0.17.0: each new route answers on the probe id, or 501 where the site lacks it

  await check("errors: problem details with type, title and status", async () => {
    const response = await doFetch(`${origin}${PREFIX}/no-such-route`, { headers: auth });
    const type = response.headers.get("content-type") ?? "";
    if (!type.startsWith("application/problem+json"))
      throw new Error(`content-type ${type || "missing"}, expected application/problem+json`);
    const body = ErrorBody.parse(await response.json());
    if (!body.type || !body.title || body.status !== response.status)
      throw new Error(`type, title or status missing or wrong: ${JSON.stringify(body)}`);
    return `${response.status} ${body.title}`;
  });

  await check("preview: a tiny source answers HTML that is never indexed", async () => {
    const response = await doFetch(`${origin}${PREFIX}/preview`, {
      method: "POST",
      headers: { ...auth, "content-type": "application/json" },
      body: JSON.stringify({ source: "# Conformance probe\n" }),
    });
    expectStatus(response, 200, "preview");
    const type = response.headers.get("content-type") ?? "";
    if (!type.startsWith("text/html"))
      throw new Error(`content-type ${type || "missing"}, expected text/html`);
    const html = await response.text();
    if (
      !/noindex/i.test(response.headers.get("x-robots-tag") ?? "") &&
      !/<meta[^>]+noindex/i.test(html)
    )
      throw new Error("neither x-robots-tag nor a robots meta says noindex");
    return "200 text/html, noindex";
  });

  if (config.probeWrites !== false) {
    const caps = capabilities ?? ({} as Partial<MetaType["capabilities"]>);
    const send = (method: string, path: string, body: unknown) =>
      doFetch(`${origin}${PREFIX}${path}`, {
        method,
        headers: { ...auth, "content-type": "application/json" },
        body: JSON.stringify(body),
      });

    async function expectCode(
      response: Response,
      allowed: Array<[number, string]>,
      what: string,
    ): Promise<string> {
      const code = await errorCode(response);
      if (!allowed.some(([status, c]) => response.status === status && code === c)) {
        throw new Error(
          `${what}: ${response.status} ${code ?? "no error code"}, expected ${allowed.map((a) => a.join(" ")).join(" or ")}`,
        );
      }
      return `${response.status} ${code}`;
    }
    const absent: [number, string] = [501, "not-implemented"];
    const unknown: [number, string] = [404, "not-found"];

    await check("publish of an unknown id: refused", async () =>
      expectCode(
        await send("POST", `/content/${PROBE_ID}/publish`, {
          expectedVersion: STALE_VERSION,
          changeId: probe(),
        }),
        [unknown, [409, "version-conflict"]],
        "publish",
      ),
    );

    await check(
      "publish with a future publishedAt: refused, or not implemented where the site cannot set the date",
      async () =>
        expectCode(
          await send("POST", `/content/${PROBE_ID}/publish`, {
            expectedVersion: STALE_VERSION,
            changeId: probe(),
            publishedAt: "2999-01-01T00:00:00Z",
          }),
          [caps.contentPublishedAt ? [400, "invalid"] : absent],
          "future publishedAt",
        ),
    );

    const writes: Array<[string, boolean | undefined, unknown]> = [
      [
        "rename",
        caps.contentRename,
        { newId: `${PROBE_ID}-renamed`, expectedVersion: STALE_VERSION },
      ],
      ["trash", caps.contentTrash, { expectedVersion: STALE_VERSION }],
      ["restore", caps.contentTrash, { expectedVersion: STALE_VERSION }],
    ];
    for (const [route, offered, body] of writes) {
      await check(
        `content ${route} of an unknown id: refused, or not implemented where the site lacks it`,
        async () =>
          expectCode(
            await send("POST", `/content/${PROBE_ID}/${route}`, {
              ...(body as object),
              changeId: probe(),
            }),
            [offered ? unknown : absent],
            `content ${route}`,
          ),
      );
    }

    await check(
      "preview link for an unknown id: refused, or not implemented where the site has none",
      async () =>
        expectCode(
          await send("POST", "/preview-links", { id: PROBE_ID, changeId: probe() }),
          [caps.previewLinks ? unknown : absent],
          "preview link",
        ),
    );

    if (caps.replay) {
      await check(
        "replay: a stale write sent twice under one change id answers the same 409 twice",
        async () => {
          const body = {
            source: "# Conformance probe\n",
            expectedVersion: STALE_VERSION,
            changeId: probe(),
          };
          const [first, second] = [
            await send("PUT", `/content/${PROBE_ID}/draft`, body),
            await send("PUT", `/content/${PROBE_ID}/draft`, body),
          ];
          expectStatus(first, 409, "first");
          expectStatus(second, 409, "retry");
          const [a, b] = [await first.text(), await second.text()];
          if (a !== b) throw new Error("the retry answered a different body");
          if (second.headers.get("idempotent-replayed") !== "true")
            throw new Error("the retry does not say Idempotent-Replayed: true");
          return "409 twice, the second replayed";
        },
      );
    }
  }

  await check("content list filters: each one the site does not offer answers 501", async () => {
    const offered = capabilities?.contentFilters ?? [];
    const probes: Record<string, string> = {
      kind: "kind=carrel-conformance-probe",
      tag: "tag=carrel-conformance-probe",
      author: "author=Carrel%20Conformance",
      published: "publishedAfter=2000-01-01T00:00:00Z",
      trashed: "trashed=true",
    };
    const missing = Object.keys(probes).filter((f) => !(offered as string[]).includes(f));
    for (const filter of missing)
      expectStatus(
        await doFetch(`${origin}${PREFIX}/content?${probes[filter]}&limit=1`, { headers: auth }),
        501,
        `filter ${filter}`,
      );
    return missing.length > 0 ? `501 for ${missing.join(", ")}` : "the site offers every filter";
  });

  // ---------- v0.22.0: unknown fields refused, backlinks, and the probe post

  async function expectUnknownField(response: Response, field: string): Promise<string> {
    expectStatus(response, 400, "unknown field");
    const body = ErrorBody.parse(await response.json());
    if (body.error !== "unknown-field")
      throw new Error(`error code ${body.error}, expected unknown-field`);
    if (body.field !== field)
      throw new Error(`field ${body.field ?? "missing"}, expected ${field}`);
    return `400 unknown-field ${field}`;
  }

  await check("unknown query key: refused with unknown-field", async () =>
    expectUnknownField(
      await doFetch(`${origin}${PREFIX}/content?carrelConformanceProbe=1&limit=1`, {
        headers: auth,
      }),
      "carrelConformanceProbe",
    ),
  );

  if (config.probeWrites !== false) {
    await check(
      "unknown body field: refused with unknown-field before anything is written",
      async () => {
        const response = await doFetch(`${origin}${PREFIX}/content/${PROBE_ID}/draft`, {
          method: "PUT",
          headers: { ...auth, "content-type": "application/json" },
          body: JSON.stringify({
            source: "# Conformance probe\n",
            expectedVersion: STALE_VERSION,
            changeId: probe(),
            carrelConformanceProbe: true,
          }),
        });
        return expectUnknownField(response, "carrelConformanceProbe");
      },
    );
  } else
    skip(
      "unknown body field: refused with unknown-field before anything is written",
      "probeWrites is off",
    );

  await check(
    "backlinks of an unknown id: refused, or not implemented where the site has none",
    async () => {
      const response = await doFetch(`${origin}${PREFIX}/content/${PROBE_ID}/backlinks`, {
        headers: auth,
      });
      const offered = capabilities?.backlinks === true;
      expectStatus(response, offered ? 404 : 501, "backlinks");
      const code = await errorCode(response);
      if (code !== (offered ? "not-found" : "not-implemented"))
        throw new Error(`error code ${code ?? "missing"}`);
      return offered ? "404 not-found" : "501 not-implemented";
    },
  );

  await probePost();

  return { ok: checks.every((c) => c.ok), checks, probes };

  // The probe post (M1): one post of the run's own, each step a probe, and the post deleted at the end whatever failed.
  async function probePost(): Promise<void> {
    const names = [
      "probe post: created as a draft",
      "probe post: every declared post and search field reads back as written",
      "probe post: q matches body text",
      "probe post: a preview link works, honors a short expiry, and answers 404 once revoked",
      "probe post: published, and its public page answers",
      "probe post: each declared hook recorded a run for the publish",
      "probe post: backlinks answer in shape",
      "probe post: a draft saved over the live post reads hasDraft and lists as published and as a draft",
      "probe post: a rename answers 301 from the old path",
      "probe post: trash and restore",
      "probe post: a delete answers 410 on the old path",
      "probe post: cleaned up",
    ] as const;
    const why = !config.probePosts
      ? "probePosts is off"
      : config.probeWrites === false
        ? "probeWrites is off"
        : !capabilities
          ? "meta did not answer"
          : capabilities.contentDelete !== true
            ? "the site cannot delete content (a page site), so a probe post could not be cleaned up"
            : null;
    if (why) {
      for (const name of names) skip(name, why);
      return;
    }
    const caps = capabilities!;
    const json = (method: string, path: string, body?: unknown) =>
      doFetch(`${origin}${PREFIX}${path}`, {
        method,
        headers: { ...auth, ...(body === undefined ? {} : { "content-type": "application/json" }) },
        ...(body === undefined ? {} : { body: JSON.stringify(body) }),
      });
    async function ok<T>(
      response: Response,
      schema: { parse(v: unknown): T },
      what: string,
    ): Promise<T> {
      if (!response.ok)
        throw new Error(`${what}: ${response.status} ${(await errorCode(response)) ?? ""}`.trim());
      return schema.parse(await response.json());
    }
    // The site's own public route, through baseUrl, never following a redirect.
    const publicPage = async (path: string) => {
      const answer = await doFetch(`${origin}${path}`, { redirect: "manual" });
      await answer.body?.cancel().catch(() => {});
      return answer;
    };
    const step = async (name: string, passedOver: string | null, run: () => Promise<string>) =>
      passedOver ? (skip(name, passedOver), false) : check(name, run);

    let id = `carrel-conformance-${run}`;
    let version = "";
    let path = "";
    const word = `probeword${run.replace(/[^a-z0-9]/gi, "")}`;
    const postValues: Partial<PostValues> = {
      excerpt: "Conformance excerpt.",
      authors: ["Conformance Probe"],
      series: "Conformance series",
      seriesPart: 1,
      featureImage: "/conformance-probe.png",
      featureImageAlt: "Conformance probe picture.",
    };
    const searchValues: Partial<SearchValues> = {
      searchTitle: "Conformance search title",
      description: "Conformance description.",
      image: "/conformance-probe.png",
      imageAlt: "Conformance probe picture.",
      canonical: `${new URL(origin).origin}/conformance-probe`,
      // Kept out of search wherever the site renders noindex.
      noindex: true,
    };
    const postFields = caps.postFields ?? [];
    const searchFields = caps.searchFields ?? [];
    let front = `title: "Conformance probe ${run}"`;
    front = setPostFields(front, Object.fromEntries(postFields.map((f) => [f, postValues[f]])));
    front = setSearchFields(
      front,
      Object.fromEntries(searchFields.map((f) => [f, searchValues[f]])),
    );
    const source = `---\n${front}\n---\n\nA conformance probe, deleted when the check ends. ${word}\n`;
    const read = async () =>
      ok(await json("GET", `/content/${encodeURIComponent(id)}`), ContentDoc, "read");

    try {
      const made = await check(names[0], async () => {
        version = (
          await ok(
            await json("PUT", `/content/${id}/draft`, {
              source,
              expectedVersion: null,
              changeId: probe(),
            }),
            WriteResult,
            "create",
          )
        ).version;
        return `${id} at ${version}`;
      });
      if (!made) {
        for (const name of names.slice(1, -1)) skip(name, "the probe post could not be created");
        return;
      }

      await step(
        names[1],
        postFields.length + searchFields.length === 0
          ? "the site declares no post or search fields"
          : null,
        async () => {
          const back = splitSource((await read()).source).front;
          const [post, search] = [postFieldsOf(back), searchFieldsOf(back)];
          const changed = [
            ...postFields.filter((f) => JSON.stringify(post[f]) !== JSON.stringify(postValues[f])),
            ...searchFields.filter(
              (f) => JSON.stringify(search[f]) !== JSON.stringify(searchValues[f]),
            ),
          ];
          if (changed.length) throw new Error(`read back changed: ${changed.join(", ")}`);
          return [...postFields, ...searchFields].join(", ");
        },
      );

      await check(names[2], async () => {
        const list = await ok(
          await json("GET", `/content?q=${word}&limit=50`),
          ContentList,
          "search",
        );
        if (!list.items.some((i) => i.id === id))
          throw new Error(`q=${word}, a word only in the body, did not list ${id}`);
        return `q=${word} lists it`;
      });

      await step(
        names[3],
        caps.previewLinks ? null : "the site makes no preview links",
        async () => {
          const hours = caps.previewLinkHours ? { expiresInHours: 1 } : { hours: 1 };
          const link = await ok(
            await json("POST", "/preview-links", { id, changeId: probe(), ...hours }),
            PreviewLink,
            "preview link",
          );
          const left = Date.parse(link.expiresAt) - Date.now();
          if (left > 65 * 60_000 || left < 50 * 60_000)
            throw new Error(`asked for 1 hour, it expires at ${link.expiresAt}`);
          // On the site's own route, through baseUrl: the link's origin may be the site's public one.
          const at = `${origin}${new URL(link.url).pathname}`;
          const open = await doFetch(at);
          await open.body?.cancel().catch(() => {});
          expectStatus(open, 200, "preview link");
          if (!/noindex/i.test(open.headers.get("x-robots-tag") ?? ""))
            throw new Error("the preview link's page does not say noindex");
          const listed = (
            await ok(
              await json("GET", `/preview-links?id=${encodeURIComponent(id)}`),
              PreviewLinkList,
              "preview links",
            )
          ).items[0];
          if (!listed) throw new Error("the new link is not listed");
          await ok(
            await json("DELETE", `/preview-links/${listed.id}?changeId=${probe()}`),
            { parse: (v) => v },
            "revoke",
          );
          const revoked = await doFetch(at);
          await revoked.body?.cancel().catch(() => {});
          expectStatus(revoked, 404, "revoked preview link");
          return "200 noindex, expires in an hour, 404 once revoked";
        },
      );

      const published = probe();
      const live = await check(names[4], async () => {
        version = (
          await ok(
            await json("POST", `/content/${id}/publish`, {
              expectedVersion: version,
              changeId: published,
            }),
            WriteResult,
            "publish",
          )
        ).version;
        const doc = await read();
        if (doc.status !== "published" || !doc.path)
          throw new Error(`after publish: ${doc.status}, path ${doc.path ?? "none"}`);
        path = doc.path;
        expectStatus(await publicPage(path), 200, `public page ${path}`);
        return `${path} answers 200`;
      });

      await step(
        names[5],
        !live
          ? "the probe post did not publish"
          : caps.hooks?.length
            ? null
            : "the site declares no hooks it keeps runs of",
        async () => {
          const wanted = caps.hooks!;
          const until = Date.now() + (config.hookWaitMs ?? 5000);
          for (;;) {
            const runs = (
              await ok(
                await json("GET", `/hooks/recent?changeId=${published}`),
                HookRunList,
                "hook runs",
              )
            ).items;
            const missing = wanted.filter((h) => !runs.some((r) => r.hook === h));
            if (missing.length === 0) {
              const failed = wanted.filter((h) => !runs.some((r) => r.hook === h && r.ok));
              if (failed.length) throw new Error(`failed: ${failed.join(", ")}`);
              return wanted.join(", ");
            }
            if (Date.now() >= until) throw new Error(`no run recorded for ${missing.join(", ")}`);
            await new Promise((done) => setTimeout(done, 500));
          }
        },
      );

      await step(names[6], caps.backlinks ? null : "the site does not list backlinks", async () => {
        const list = await ok(
          await json("GET", `/content/${encodeURIComponent(id)}/backlinks`),
          BacklinkList,
          "backlinks",
        );
        return `${list.items.length} backlink(s)`;
      });

      await step(
        names[7],
        !live
          ? "the probe post did not publish"
          : caps.contentHasDraft
            ? null
            : "the site does not mark a live item's pending draft",
        async () => {
          version = (
            await ok(
              await json("PUT", `/content/${id}/draft`, {
                source: `${source}\nA pending edit.\n`,
                expectedVersion: version,
                changeId: probe(),
              }),
              WriteResult,
              "draft over live",
            )
          ).version;
          const doc = await read();
          if (doc.status !== "published" || doc.hasDraft !== true)
            throw new Error(
              `after a draft over the live post: ${doc.status}, hasDraft ${String(doc.hasDraft)}`,
            );
          for (const status of ["published", "draft"] as const) {
            const list = await ok(
              await json("GET", `/content?status=${status}&limit=200`),
              ContentList,
              `status=${status}`,
            );
            const row = list.items.find((i) => i.id === id);
            if (!row) throw new Error(`status=${status} does not list it`);
            if (row.status !== "published" || row.hasDraft !== true)
              throw new Error(
                `status=${status} lists it as ${row.status}, hasDraft ${String(row.hasDraft)}`,
              );
          }
          return "hasDraft true, listed under published and draft";
        },
      );

      await step(
        names[8],
        !live
          ? "the probe post did not publish"
          : caps.contentRename
            ? null
            : "the site does not rename content",
        async () => {
          const newId = `${id}-renamed`;
          const written = await ok(
            await json("POST", `/content/${id}/rename`, {
              newId,
              expectedVersion: version,
              changeId: probe(),
            }),
            RenameResult,
            "rename",
          );
          [id, version] = [newId, written.version];
          const old = path;
          path = (await read()).path ?? "";
          const answer = await publicPage(old);
          expectStatus(answer, 301, `old path ${old}`);
          const to = new URL(answer.headers.get("location") ?? "", origin).pathname;
          if (to !== path) throw new Error(`301 to ${to}, expected ${path}`);
          return `${old} 301 to ${path}`;
        },
      );

      await step(names[9], caps.contentTrash ? null : "the site has no content trash", async () => {
        const trashed = await ok(
          await json("POST", `/content/${id}/trash`, {
            expectedVersion: version,
            changeId: probe(),
          }),
          WriteResult,
          "trash",
        );
        const binned = await ok(
          await json("GET", "/content?trashed=true&limit=200"),
          ContentList,
          "trash list",
        );
        if (!binned.items.some((i) => i.id === id)) throw new Error("not listed in the trash");
        version = (
          await ok(
            await json("POST", `/content/${id}/restore`, {
              expectedVersion: trashed.version,
              changeId: probe(),
            }),
            WriteResult,
            "restore",
          )
        ).version;
        const doc = await read();
        if (doc.status !== "draft" || doc.trashedAt)
          throw new Error(`after restore: ${doc.status}, trashedAt ${doc.trashedAt ?? "null"}`);
        return "trashed, listed in the trash, restored as a draft";
      });

      await step(
        names[10],
        !live
          ? "the probe post did not publish"
          : caps.replay
            ? null
            : "the site has no store, so it keeps no tombstones",
        async () => {
          const doc = await read();
          version =
            doc.status === "published"
              ? doc.version
              : (
                  await ok(
                    await json("POST", `/content/${id}/publish`, {
                      expectedVersion: doc.version,
                      changeId: probe(),
                    }),
                    WriteResult,
                    "publish again",
                  )
                ).version;
          const gone = (await read()).path ?? path;
          expectStatus(
            await json(
              "DELETE",
              `/content/${id}?expectedVersion=${encodeURIComponent(version)}&changeId=${probe()}`,
            ),
            200,
            "delete",
          );
          expectStatus(await publicPage(gone), 410, `deleted page ${gone}`);
          return `${gone} answers 410`;
        },
      );
    } finally {
      await check(names[11], async () => {
        const left = await json("GET", `/content/${encodeURIComponent(id)}`);
        if (left.status === 404) return `${id} is gone`;
        const doc = await ok(left, ContentDoc, "read before cleaning up");
        expectStatus(
          await json(
            "DELETE",
            `/content/${id}?expectedVersion=${encodeURIComponent(doc.version)}&changeId=${probe()}`,
          ),
          200,
          "cleanup delete",
        );
        return `deleted ${id}`;
      });
    }
  }
}

src/frontmatter.ts.source:
// A post's source is YAML frontmatter and a Markdown body. The block reader and writer (splitSource, joinSource,
// readKey, readList, setBlock, setRawKey) is Prelum's alone (`@drdustinedwards/site-helpers/frontmatter`): a write
// replaces only the block it names, and every other block, comment and unknown key comes back byte for byte. A site
// imports those from Prelum. This module is only the site API's own fields on top. Exported as
// `@dustinedwards/site-api/frontmatter`.

import {
  readKey,
  readList,
  setBlock,
  setRawKey,
  splitSource,
} from "@drdustinedwards/site-helpers/frontmatter";

/** The tags the frontmatter holds now, in order. */
export function tagsOf(front: string | null): string[] {
  return readList(front, "tags")
    .map((t) => t.trim())
    .filter(Boolean);
}

/**
 * The frontmatter with its tags set to exactly this list, and nothing else touched. An empty list is
 * written as `tags: []`, not removed. A list in block form comes back in flow form.
 */
export function setTags(front: string, tags: string[]): string {
  return setRawKey(front, "tags", `[${tags.map(tagItem).join(", ")}]`);
}

/** YAML 1.1 reads these plain words as booleans or null, not as the tag. */
const YAML_WORDS = /^(y|n|yes|no|true|false|on|off|null|~)$/i;

/** A tag as a flow-list item: bare when YAML reads it back as the same string, double-quoted otherwise. */
function tagItem(tag: string): string {
  const plain = /^[A-Za-z][\w .+/-]*$/.test(tag) && !/\s$/.test(tag) && !YAML_WORDS.test(tag);
  return plain ? tag : JSON.stringify(tag);
}

/**
 * The search fields (v0.17.0): the same name on every site, kept in the frontmatter so each change is versioned
 * with the post. A site lists the ones it renders in its capabilities' `searchFields`, and Carrel shows a box for each.
 * An empty one falls back to the site's own default (the title, the opening text, the cover, the page's own address).
 */
export const SEARCH_FIELDS = [
  "searchTitle",
  "description",
  "image",
  "imageAlt",
  "canonical",
  "noindex",
] as const;
export type SearchField = (typeof SEARCH_FIELDS)[number];
export type SearchValues = {
  searchTitle: string;
  description: string;
  image: string;
  imageAlt: string;
  canonical: string;
  noindex: boolean;
};

export function searchFieldsOf(front: string | null): SearchValues {
  return {
    searchTitle: readKey(front, "searchTitle"),
    description: readKey(front, "description"),
    image: readKey(front, "image"),
    imageAlt: readKey(front, "imageAlt"),
    canonical: readKey(front, "canonical"),
    noindex: readKey(front, "noindex") === "true",
  };
}

/** The frontmatter with these search fields set, as JSON literals so a jsonSource site reads them too. A blank text or a false noindex removes the key. */
export function setSearchFields(front: string, values: Partial<SearchValues>): string {
  let out = front;
  for (const field of SEARCH_FIELDS) {
    const value = values[field];
    if (value === undefined) continue;
    const text = typeof value === "boolean" ? (value ? "true" : "") : value.trim();
    out = setBlock(
      out,
      field,
      text === "" ? [] : [`${field}: ${typeof value === "boolean" ? text : JSON.stringify(text)}`],
    );
  }
  return out;
}

/**
 * The post fields (v0.17.0), beside the search fields and kept the same way: `excerpt` (the summary a list shows),
 * `authors` (display names in credit order, the first the primary author), `series` (its name) and `seriesPart` (a
 * positive whole number). v0.22.0: `featureImage` (the picture a post leads with: a URL, a site path or a media key) and
 * `featureImageAlt` (its alt text). A site lists the ones it renders in its capabilities' `postFields`.
 */
export const POST_FIELDS = [
  "excerpt",
  "authors",
  "series",
  "seriesPart",
  "featureImage",
  "featureImageAlt",
] as const;
export type PostField = (typeof POST_FIELDS)[number];
export type PostValues = {
  excerpt: string;
  authors: string[];
  series: string;
  seriesPart: number | null;
  featureImage: string;
  featureImageAlt: string;
  /**
   * v0.22.0: true when the post marks its feature image decorative (`featureImageDecorative: true`), so an empty alt is
   * right and does not block a publish. Not a post field of its own: it goes with `featureImage`.
   */
  featureImageDecorative: boolean;
};

export function postFieldsOf(front: string | null): PostValues {
  const part = Number(readKey(front, "seriesPart"));
  return {
    excerpt: readKey(front, "excerpt"),
    authors: authorsOf(front),
    series: readKey(front, "series"),
    seriesPart: Number.isInteger(part) && part > 0 ? part : null,
    featureImage: readKey(front, "featureImage"),
    featureImageAlt: readKey(front, "featureImageAlt"),
    featureImageDecorative: readKey(front, "featureImageDecorative") === "true",
  };
}

/** A JSON array first, since a name may hold a comma ("Smith, Jr."); a hand-written YAML list otherwise. */
function authorsOf(front: string | null): string[] {
  const raw = readKey(front, "authors");
  let names: unknown = null;
  if (raw.startsWith("[")) {
    try {
      names = JSON.parse(raw);
    } catch {
      // Not JSON: a YAML flow list, read below.
    }
  }
  const list =
    Array.isArray(names) && names.every((n) => typeof n === "string")
      ? (names as string[])
      : readList(front, "authors");
  return list.map((n) => n.trim()).filter(Boolean);
}

/**
 * The frontmatter with these post fields set, as JSON literals like the search fields. A blank text, no authors, a null
 * part or a false `featureImageDecorative` removes the key.
 */
export function setPostFields(front: string, values: Partial<PostValues>): string {
  let out = front;
  for (const field of [...POST_FIELDS, "featureImageDecorative"] as const) {
    const value = values[field];
    if (value === undefined) continue;
    let literal: string | null;
    if (typeof value === "boolean") {
      literal = value ? "true" : null;
    } else if (Array.isArray(value)) {
      const names = value.map((n) => n.trim()).filter(Boolean);
      literal = names.length > 0 ? JSON.stringify(names) : null;
    } else if (typeof value === "number" || value === null) {
      literal = value !== null && Number.isInteger(value) && value > 0 ? String(value) : null;
    } else {
      literal = value.trim() === "" ? null : JSON.stringify(value.trim());
    }
    out = setBlock(out, field, literal === null ? [] : [`${field}: ${literal}`]);
  }
  return out;
}

/**
 * The picture fields whose alt text is missing (v0.22.0, D8): the share image (`image` without `imageAlt`) where the site
 * lists `image`, and the feature image (`featureImage` without `featureImageAlt`) where it lists `featureImage`. Each blocks a publish, as alt text in the body does. A picture the post marks decorative (`imageDecorative:
 * true` or `featureImageDecorative: true`) takes an empty alt and is not listed; nothing else does. Carrel's gate and the
 * package's publish both read this.
 */
export function missingAltFields(
  front: string | null,
  declared: { searchFields?: readonly string[]; postFields?: readonly string[] },
): Array<"imageAlt" | "featureImageAlt"> {
  const faults: Array<"imageAlt" | "featureImageAlt"> = [];
  if (
    (declared.searchFields ?? []).includes("image") &&
    readKey(front, "image") &&
    !readKey(front, "imageAlt") &&
    readKey(front, "imageDecorative") !== "true"
  ) {
    faults.push("imageAlt");
  }
  const post = postFieldsOf(front);
  if (
    (declared.postFields ?? []).includes("featureImage") &&
    post.featureImage &&
    !post.featureImageAlt &&
    !post.featureImageDecorative
  ) {
    faults.push("featureImageAlt");
  }
  return faults;
}

// The JSON source format: the front matter a site writes for Carrel when it stores its fields in columns,
// one `key: <JSON literal>` line per field, so a round trip needs no YAML. A text field may also be written
// unquoted by hand. `jsonSource` is the one reader and writer, given the site's own field list.

/** A frontmatter key line, as jsonSource reads one. */
const KEY = /^([A-Za-z_][\w-]*):(.*)$/;

export type JsonFieldKind = "text" | "list" | "flag";
type JsonValue<K extends JsonFieldKind> = K extends "text"
  ? string | null
  : K extends "list"
    ? string[]
    : boolean;
export type JsonValues<F extends Record<string, JsonFieldKind>> = {
  [K in keyof F]?: JsonValue<F[K]>;
};

export class JsonSourceError extends Error {
  constructor(readonly problems: string[]) {
    super(`The front matter cannot be read:\n${problems.map((p) => `- ${p}`).join("\n")}`);
    this.name = "JsonSourceError";
  }
}

/**
 * A reader and writer for one site's fields. `write` lists the fields that are not undefined, in the
 * field list's order, and `blankLine` puts an empty line before the body. `read` returns each key the
 * source has (a key it leaves out is undefined) and the body, and throws JsonSourceError naming every
 * problem: an unknown, repeated or malformed key, a value of the wrong kind, or a `required` field that
 * is missing or blank. With no front matter, the whole source is the body, unless a field is required.
 */
export function jsonSource<F extends Record<string, JsonFieldKind>>(
  fields: F,
  options: { required?: Array<keyof F & string>; blankLine?: boolean } = {},
) {
  const keys = Object.keys(fields) as Array<keyof F & string>;
  const required = options.required ?? [];
  return {
    write(values: JsonValues<F>, body: string): string {
      const lines = keys
        .filter((k) => values[k] !== undefined)
        .map((k) => `${k}: ${JSON.stringify(values[k])}`);
      return `---\n${lines.join("\n")}\n---\n${options.blankLine ? "\n" : ""}${body}`;
    },
    read(source: string): { values: JsonValues<F>; body: string } {
      const { front, body } = splitSource(source);
      if (front === null) {
        if (required.length > 0)
          throw new JsonSourceError([
            "The source must start with a front matter block between two --- lines.",
          ]);
        return { values: {}, body: source };
      }
      const problems: string[] = [];
      const values: Record<string, unknown> = {};
      for (const line of front.split(/\r?\n/)) {
        if (line.trim() === "") continue;
        const m = KEY.exec(line);
        const key = m?.[1];
        if (!m || !key)
          problems.push(`This front matter line is not "key: value": ${line.slice(0, 80)}`);
        else if (!Object.hasOwn(fields, key))
          problems.push(`${key} is not a field. The fields are ${keys.join(", ")}.`);
        else if (key in values) problems.push(`${key} appears twice.`);
        else values[key] = jsonValue(key, fields[key]!, m[2]!.trim(), problems);
      }
      for (const key of required) {
        const v = values[key];
        if (v === undefined || v === null || (typeof v === "string" && v.trim() === ""))
          problems.push(`${key} is required.`);
      }
      if (problems.length > 0) throw new JsonSourceError(problems);
      return { values: values as JsonValues<F>, body };
    },
  };
}

function jsonValue(key: string, kind: JsonFieldKind, raw: string, problems: string[]): unknown {
  if (kind === "text" && !raw.startsWith('"')) return raw === "" || raw === "null" ? null : raw;
  let value: unknown;
  try {
    value =
      raw === "" || (kind === "list" && raw === "null")
        ? kind === "list"
          ? []
          : false
        : JSON.parse(raw);
  } catch {
    problems.push(`${key}: the value is not valid JSON.`);
    return undefined;
  }
  if (kind === "text" && typeof value === "string") return value;
  if (kind === "list" && Array.isArray(value) && value.every((t) => typeof t === "string"))
    return value.map((t) => t.trim()).filter(Boolean);
  if (kind === "flag" && typeof value === "boolean") return value;
  problems.push(
    `${key} must be ${kind === "text" ? "a string" : kind === "list" ? 'a list of strings, such as ["a", "b"]' : "true or false"}.`,
  );
  return undefined;
}

src/hooks.ts.source:
// Publish hooks (v0.10.0): what a site runs when a public page changes, whether a Carrel request changed it or a
// schedule did. A hook never decides anything: the write has already happened, so a hook that fails is logged and the
// write stands.

import type { ContentStatus } from "./contract.js";

/**
 * publish: the item went live (a first publish, a publish again, or a scheduled item at its time). update: a live
 * item's page changed (a save, a tag change, or its scheduled update at its time). unpublish: it left the site.
 * delete: it was deleted. v0.17.0: trash and restore (to and from the content trash), rename (a move to a new id, its
 * old path redirecting), schedule and unschedule (a schedule made or canceled, nothing changed yet).
 */
export type PublishAction =
  | "publish"
  | "update"
  | "unpublish"
  | "delete"
  | "trash"
  | "restore"
  | "rename"
  | "schedule"
  | "unschedule";

export interface PublishEvent {
  action: PublishAction;
  id: string;
  /**
   * The item's public path, such as /blog/some-post. v0.22.0: null for a schedule or an unschedule of an item never
   * published, which has no page yet; a hook that needs a live page skips such an event itself.
   */
  path: string | null;
  /** The site's origin and the path: the page that changed. null when `path` is. */
  url: string | null;
  /** request: a Carrel write (or the site's own admin through localClient). schedule: `runSchedules`. */
  trigger: "request" | "schedule";
  changeId: string | null;
  /** The request that made the change; absent for a schedule, and for a hook's retry. */
  request?: Request;
  /** v0.17.0: the item's status before the write and after it (after a delete, absent). */
  previousStatus?: ContentStatus;
  status?: ContentStatus;
  /** v0.17.0, on a rename of an item that was ever published: its old path, which now redirects, and that page's address. */
  previousPath?: string;
  previousUrl?: string;
}

export interface PublishHook {
  /** Names the hook in the log, and in the store's retries. */
  name: string;
  /**
   * v0.17.0: the actions the hook hears. Absent: the ones that change a public page, as before (PAGE_ACTIONS): a publish,
   * a live item's update, an unpublish, and a delete, trash or rename of a live item.
   */
  on?: readonly PublishAction[];
  /** May return a promise. Throwing, or resolving to false, is a failure: logged, never answered, and the write stands. */
  run(event: PublishEvent): unknown;
}

/** What a hook with no `on` hears, each only when it changed a public page. */
export const PAGE_ACTIONS: readonly PublishAction[] = [
  "publish",
  "update",
  "unpublish",
  "delete",
  "trash",
  "rename",
];

/** Whether a hook hears the event: one it names, or with no `on`, a page action that changed a public page. */
export function hears(hook: PublishHook, event: PublishEvent): boolean {
  if (hook.on) return hook.on.includes(event.action);
  // No page, no page change (v0.22.0): only a hook that names schedule or unschedule hears one without a path.
  if (event.path === null) return false;
  if (!PAGE_ACTIONS.includes(event.action)) return false;
  const live =
    event.action === "publish" || event.action === "update" ? event.status : event.previousStatus;
  // An event that does not say (a site's own runHooks call before v0.17.0) is taken as a page change, as it was then.
  return live === undefined || live === "published";
}

/**
 * Runs every hook that hears the event at once, and logs each one that fails. Never throws. `failed` (v0.17.0) is told
 * each failure, so the package keeps it for a retry where the site has a store.
 */
export async function runHooks(
  hooks: readonly PublishHook[],
  event: PublishEvent,
  log: (entry: Record<string, unknown>) => void,
  failed?: (hook: PublishHook, error: string) => Promise<void>,
  ran?: (hook: PublishHook, ok: boolean) => Promise<void>,
): Promise<void> {
  const { request: _r, ...logged } = event;
  await Promise.all(
    hooks
      .filter((hook) => hears(hook, event))
      .map(async (hook) => {
        let error: string | null;
        try {
          error = (await hook.run(event)) === false ? "the hook reported a failure" : null;
        } catch (thrown) {
          error = thrown instanceof Error ? thrown.message : String(thrown);
        }
        await ran?.(hook, error === null).catch((e) =>
          log({ siteApi: "hook-run-not-kept", hook: hook.name, error: String(e) }),
        );
        if (error === null) return;
        log({ siteApi: "hook-failed", hook: hook.name, ...logged, error });
        await failed?.(hook, error).catch((e) =>
          log({ siteApi: "hook-retry-failed", hook: hook.name, error: String(e) }),
        );
      }),
  );
}

/** The shape of Prelum's `submitIndexNow` (`@drdustinedwards/site-helpers/indexnow`), which the site passes in. */
export type SubmitIndexNow = (input: {
  origin: string;
  key: string;
  urls: string[];
  from?: string;
}) => Promise<boolean>;

/**
 * The IndexNow hook: tells search engines the changed page, through Prelum's `submitIndexNow`. The site passes the
 * function in, so this package carries no copy of it and no dependency on Prelum. A request on another origin (a
 * preview, localhost) sends nothing and is not a failure; a schedule has no request, so it always sends. Prelum resolves
 * false when the engines refuse or cannot be reached, which the hook runner logs.
 */
export function indexNowHook(options: {
  submit: SubmitIndexNow;
  key: string;
  origin: string;
}): PublishHook {
  return {
    name: "indexnow",
    run: (event) => {
      // No page yet (v0.22.0: a schedule of a draft, heard only by a hook that names it): nothing to tell, and not a failure.
      if (!event.url) return true;
      // A preview is not a failure: it has nothing to tell.
      if (event.request && new URL(event.request.url).origin !== options.origin) return true;
      return options.submit({
        origin: options.origin,
        key: options.key,
        // A rename's old address now redirects: the engines hear both.
        urls: event.previousUrl ? [event.url, event.previousUrl] : [event.url],
        ...(event.request ? { from: event.request.url } : {}),
      });
    },
  };
}

src/log.ts.source:
// The site API's log line, once for every site. A refused request is named in the OWASP logging vocabulary through
// site-runtime's scrubbing logger (a missing or wrong key is `authz_fail`, a rate-limited one
// `excess_rate_limit_exceeded`, the reason stays a field); every other line is `site_api_<name>`. It is the default
// `log` of createSiteApi, so a site passes none.
import { OWASP_EVENTS, logEvent } from "@dustinedwards/site-runtime/log";

export function siteApiLog(entry: Record<string, unknown>): void {
  if (entry.siteApi === "refused") {
    const limited = entry.reason === "rate-limited";
    const denied = entry.reason === "wrong-key" || entry.reason === "no-key";
    const event = limited
      ? OWASP_EVENTS.rateLimitExceeded
      : denied
        ? OWASP_EVENTS.authorizationFailure
        : "site_api_refused";
    logEvent(event, entry, { level: "warn" });
    return;
  }
  logEvent(`site_api_${String(entry.siteApi ?? "log")}`, entry);
}

src/media-kit.ts.source:
// The media kit (v0.14.0): the pieces every site's media adapter wrote for itself, once. A file's version spelled from its
// index row's rev, a versioned write's outcome as the contract's answer or error, a fresh ArrayBuffer for R2 and the Images
// binding, the AI suggester behind `suggest`, and the plain page a preview renders into.

import { MODEL_IDS, structured } from "@dustinedwards/site-runtime/anthropic";
import { toBase64 } from "@dustinedwards/site-runtime/encoding";
import { escapeHtml } from "@dustinedwards/site-runtime/html";
import { editImage, type ImagesLike } from "@dustinedwards/site-runtime/image";
import { checkProse } from "@dustinedwards/site-runtime/prose";

import { NotFoundError, RefusedError, VersionConflictError } from "./adapter.js";

// ---------- Versions

/** A version this package's sites answer: `r` and the row's rev, a whole number without a leading zero. */
export const MEDIA_VERSION_PATTERN = /^r(0|[1-9]\d{0,15})$/;

/**
 * A file's version from its index row's `rev`, which every write moves in the statement that checks it, so two writes in
 * one second still differ.
 */
export function mediaVersion(rev: number): string {
  return `r${rev}`;
}

/** The rev a version names, or -1 (which no row holds) for anything the site never answered. */
export function mediaRev(version: string): number {
  return MEDIA_VERSION_PATTERN.test(version) ? Number(version.slice(1)) : -1;
}

/**
 * What one versioned write to a file's row did: the new rev (`changed: false` when the row was already as asked), no such
 * file, a stale version with the rev the row holds, or the site's own refusal in words for the person.
 */
export type MediaWrite =
  | { ok: true; rev: number; changed?: boolean }
  | { ok: false; reason: "missing" }
  | { ok: false; reason: "stale"; rev: number | null }
  | { ok: false; reason: "refused"; message: string };

/** A write's outcome as the contract's answer, or the error the handler turns into 404, 409 or 422. */
export function answerWrite(write: MediaWrite): { version: string } {
  if (write.ok) return { version: mediaVersion(write.rev) };
  switch (write.reason) {
    case "missing":
      throw new NotFoundError("No such media.");
    case "stale":
      throw new VersionConflictError(
        write.rev === null ? null : mediaVersion(write.rev),
        "The file changed since it was loaded.",
      );
    case "refused":
      throw new RefusedError(write.message);
  }
}

/** A fresh ArrayBuffer of a view's bytes, not `bytes.buffer`, which may be a larger allocation shared with other views. */
export function toArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  const buffer = new ArrayBuffer(bytes.byteLength);
  new Uint8Array(buffer).set(bytes);
  return buffer;
}

// ---------- AI suggestions

/** The vision model: Claude's fast role (site-runtime's MODEL_IDS.fast, Haiku 5.5), called straight at Anthropic. */
export const SUGGEST_MODEL = MODEL_IDS.fast;

/** The longest edge the model is shown: enough to name what is in a picture, and a small request. */
const VIEW_EDGE = 768;

/** The feature on each `anthropic_call` log line, beside the site's `app`, so the suggester's cost splits from the site's other calls. */
export const SUGGEST_FEATURE = "media-suggest";

/** How long a suggestion may take before the call is abandoned; a person is waiting on it. */
const SUGGEST_TIMEOUT_MS = 30_000;

/** The answer's shape, asked of the model through structured outputs (`output_config.format`). */
const SUGGESTION_SCHEMA = {
  type: "object",
  properties: { alt: { type: "string" }, tags: { type: "array", items: { type: "string" } } },
  required: ["alt", "tags"],
  additionalProperties: false,
};

/** The bindings and variables the suggester reads. */
export interface SuggestEnv {
  /** The site's Anthropic key. Without it the suggester throws, and the site should leave `suggest` off its adapter. */
  ANTHROPIC_API_KEY?: string;
  /** The Images binding, for the smaller copy the model is shown. */
  IMAGES: ImagesLike;
}

/** The tokens one suggestion spent, as Anthropic reports them (site-runtime's `Usage`, plus the model). */
export interface SuggestUsage {
  model: string;
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
}

export interface MediaSuggesterOptions<E extends SuggestEnv> {
  /** The site's name on each `anthropic_call` log line ("example"). */
  app: string;
  /** Where the picture is, finishing "...one picture ": "on a personal website", "in a travel blog". */
  describe: string;
  /** More sentences for the prompt, the site's own rules ("Do not use em dashes."). */
  rules?: string[];
  /** Runs before the model is called; throw to stop it (a daily cost cap). */
  beforeCall?: (env: E, id: string | undefined) => Promise<void> | void;
  /** Runs after the model answers, with what it spent, to meter it. A failure here is the site's to catch; it fails the call. */
  afterCall?: (env: E, usage: SuggestUsage, id: string | undefined) => Promise<void> | void;
}

/** What the model suggests for one picture: its tags and alt text as it wrote them (the package cleans both), and the model. */
export interface MediaSuggestion {
  tags: string[];
  alt: string | null;
  model: string;
  /** What the call spent, as Anthropic reported it (v0.34.0). */
  usage?: { input: number; output: number; cacheRead: number; cacheWrite: number };
}

/**
 * The house rule for alt text: what the picture shows, plainly, and nothing more, so a reader who cannot see it learns what
 * a sighted reader sees. No interpretation, no praise, no "image of".
 */
function promptFor(describe: string, rules: string[]): string {
  return [
    `You write alt text and library tags for one picture ${describe}.`,
    "alt: one plain sentence, at most 25 words, describing what the picture shows: the subject, what it is doing,",
    "and any text that is legible in it. Say only what can be seen. Do not begin with 'Image of', 'Picture of' or",
    "'Photo of'. Do not interpret, praise or guess at feelings, names or places that are not written in the picture.",
    ...rules,
    "tags: three to eight short lower case nouns for what is in the picture, words joined by hyphens, no duplicates.",
  ].join(" ");
}

/**
 * The model's answer as tags and alt: the parsed object structured outputs return. Anything that is not that object
 * reads as no suggestion.
 */
export function readSuggestion(answer: unknown): { tags: string[]; alt: string | null } {
  const record = (typeof answer === "object" && answer !== null ? answer : {}) as {
    alt?: unknown;
    tags?: unknown;
  };
  const alt = typeof record.alt === "string" && record.alt.trim() ? record.alt.trim() : null;
  const tags = Array.isArray(record.tags)
    ? record.tags.filter((t): t is string => typeof t === "string")
    : [];
  return { tags, alt };
}

/**
 * The AI tag and alt-text suggester every site wrote behind its adapter's `suggest`: a 768px JPEG of the picture (through
 * site-runtime's editImage) shown to Claude Haiku 5.5, called straight at Anthropic with the site's ANTHROPIC_API_KEY
 * (never through AI Gateway). Nothing here writes: a suggestion reaches the file only when a person accepts it. Send only
 * the site's own uploads, never a visitor's data. The returned function takes the env, the picture (a stream or an R2
 * object) and, for the hooks, its id.
 */
export function mediaSuggester<E extends SuggestEnv>(options: MediaSuggesterOptions<E>) {
  const prompt = promptFor(options.describe, options.rules ?? []);
  return async function suggest(
    env: E,
    picture: ReadableStream | { body: ReadableStream },
    id?: string,
  ): Promise<MediaSuggestion> {
    if (!env.ANTHROPIC_API_KEY)
      throw new Error("This site has no ANTHROPIC_API_KEY, so it cannot suggest tags or alt text.");
    await options.beforeCall?.(env, id);
    const stream = "getReader" in picture ? picture : picture.body;
    const view = await editImage(env.IMAGES, stream, {
      maxEdge: VIEW_EDGE,
      format: "image/jpeg",
      quality: 80,
    });
    const data = toBase64(await view.arrayBuffer());
    const result = await structured<{ alt?: unknown; tags?: unknown }>(
      env,
      options.app,
      {
        model: SUGGEST_MODEL,
        max_tokens: 300,
        messages: [
          {
            role: "user",
            content: [
              { type: "image", source: { type: "base64", media_type: "image/jpeg", data } },
              { type: "text", text: prompt },
            ],
          },
        ],
      },
      SUGGESTION_SCHEMA,
      { feature: SUGGEST_FEATURE, timeoutMs: SUGGEST_TIMEOUT_MS },
    );
    // A failed call still spent what it spent where Anthropic reported it, so it is metered before it throws.
    if (options.afterCall)
      await options.afterCall(env, { model: SUGGEST_MODEL, ...result.usage }, id);
    if (!result.ok) throw new Error(result.error);
    const { tags, alt } = readSuggestion(result.value);
    // Alt text with a high or critical prose finding (a refusal, a cutoff note, a blank, citation markup) is not offered.
    const flagged =
      alt !== null &&
      checkProse(alt, { model: SUGGEST_MODEL }).some(
        (issue) => issue.severity === "high" || issue.severity === "critical",
      );
    const { input, output, cacheRead, cacheWrite } = result.usage;
    return {
      tags,
      alt: flagged ? null : alt,
      model: SUGGEST_MODEL,
      usage: { input, output, cacheRead, cacheWrite },
    };
  };
}

// ---------- Preview

export interface PreviewDocumentInput {
  /** The page's title, written escaped. */
  title: string;
  /** The page's body HTML, from the site's own renderer and sanitizer, written as it is. */
  body: string;
  /** The page's language, "en" by default. */
  lang?: string;
  /** Stylesheet addresses, absolute or resolved against `origin`: the preview is shown on Carrel's origin, not the site's. */
  stylesheets?: string[];
  /** The site's origin, for relative stylesheet addresses. */
  origin?: string;
  /** More attributes on `<html>` (a theme, a family), each value escaped. */
  attributes?: Record<string, string>;
  /** CSS for the preview alone, such as showing what the site's script would reveal. */
  style?: string;
}

/**
 * The plain page a preview renders into: the site's body under its title, `noindex` so a preview found by a crawler is
 * never listed, every value but the body escaped. A full themed route needs a saved row; an unsaved source does not have
 * one, so sites preview the body in this page.
 */
export function previewDocument(input: PreviewDocumentInput): string {
  const attributes = Object.entries(input.attributes ?? {})
    .map(([name, value]) => ` ${name.replace(/[^\w:-]/g, "")}="${escapeHtml(value)}"`)
    .join("");
  const css = (input.stylesheets ?? [])
    .map(
      (href) =>
        `<link rel="stylesheet" href="${escapeHtml(input.origin ? new URL(href, input.origin).href : href)}">`,
    )
    .join("");
  const style = input.style
    ? `<style>${input.style.replace(/<\/style/gi, "<\\/style")}</style>`
    : "";
  return (
    `<!doctype html><html lang="${escapeHtml(input.lang ?? "en")}"${attributes}><head><meta charset="utf-8">` +
    `<meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex">` +
    `<title>${escapeHtml(input.title)}</title>${css}${style}</head><body>${input.body}</body></html>`
  );
}

src/media-library.ts.source:
// The media library (v0.24.0): the whole media group over a site's index rows and its R2 bucket, written once. Each site
// wrote this for itself (bsw, julieedwards.info, txasm, Foxhound, Germomics, Foxing, dustinedwards.info) and the copies
// drifted; a site now passes `mediaLibrary` its store, bucket and rules and keeps no adapter of its own.
//
// VERSIONS. A file's version is its row's `rev` (mediaVersion). Every write to its metadata or bytes moves it once, in the
// statement that checks it (the store's writeAtRev), so a stale write is a 409, never a lost update. A write that changes
// the object checks the version before any costly work, claims it (the rev moves first), then changes the object, then the
// row's byte columns (`follow`, which does not move the rev again).
//
// BYTES. A replace, turn, mirror, shrink or revert first keeps the bytes it overwrites as a copy (`history`) and records
// it on the file's revisions, so each one can be taken back. One put writes the new bytes with the object's metadata and
// the focal point that goes with them, conditional on the etag read, so nothing races it unseen.
//
// DELETES. The site's reference check runs first and refuses a file in use; the store's `remove` takes the row and its
// revisions in one batch (and may refuse atomically, against the site's own tables); then the object goes. Copies kept in
// the served bucket go with it; copies kept in a separate backups bucket stay, as backups.

import { slugify } from "@drdustinedwards/site-helpers/slug";
import { FOCUS_METADATA, editImage } from "@dustinedwards/site-runtime/image";

import {
  MediaInUseError,
  NotFoundError,
  RefusedError,
  VersionConflictError,
  type MediaAdapter,
  type MediaUploaded,
} from "./adapter.js";
import {
  LARGE_MEDIA_BYTES,
  type MediaDetail,
  type MediaEmbeddedField,
  type MediaItem,
  type MediaLens,
  type MediaList,
  type MediaListQuery,
  type MediaResize,
  type MediaRevision,
  type MediaTransformOp,
  type MediaUploadLimits,
  type MediaUse,
} from "./contract.js";
import { sha256Hex } from "@dustinedwards/site-runtime/encoding";
import { kindOf, orientationOf, transformFocus, turnsSize } from "./media.js";
import { mediaRev, mediaVersion, toArrayBuffer } from "./media-kit.js";
import { placeholderAndColor, prepareUpload, type UploadImages } from "./media-upload.js";

// ---------- What a site gives the library

/** One file's index row, in the contract's terms. A site's store maps its own columns to and from it. */
export interface MediaRecord {
  /** The storage key, which is the file's id (MediaId). */
  key: string;
  /** The version: moved by every write, only through `writeAtRev`. */
  rev: number;
  filename: string | null;
  contentType: string;
  bytes: number;
  width: number | null;
  height: number | null;
  /** The SHA-256 of the current bytes, lower case hex; null only for a row stored before the site hashed. */
  sha256: string | null;
  alt: string;
  caption: string;
  /** In the contract's spelling; the package has sorted and deduplicated a write. */
  tags: string[];
  /** "XxY" (site-runtime's focusOf), or null. */
  focus: string | null;
  credit: string;
  license: string;
  sourceUrl: string | null;
  /** YYYY-MM-DD, or null. */
  licenseExpires: string | null;
  takenAt: string | null;
  placeholder: string | null;
  color: string | null;
  /** ISO 8601. */
  uploadedAt: string;
  /** ISO 8601, or null outside the trash. */
  trashedAt: string | null;
  /** Kept only where the store says so (`MediaLibraryStore.keeps`). */
  decorative?: boolean;
  copyright?: string;
  licenseUrl?: string | null;
  acquireLicenseUrl?: string | null;
}

/** The columns a write may set. */
export type MediaRecordFields = Partial<Omit<MediaRecord, "key" | "rev">>;

export type MediaRevisionReason = MediaRevision["reason"];

/** One set of bytes a file has had. The newest is the current bytes; each earlier one names its kept copy. */
export interface MediaRevisionRecord {
  id: number;
  /** ISO 8601. */
  at: string;
  bytes: number;
  width: number | null;
  height: number | null;
  reason: MediaRevisionReason;
  sha256: string | null;
  /** Where the copy of these bytes is, in the library's history bucket; null for the current bytes. */
  copyKey: string | null;
}

/** A versioned write's outcome: the row as written, no such file, or a stale version with the rev the row holds. */
export type MediaRecordWrite =
  | { ok: true; record: MediaRecord }
  | { ok: false; reason: "missing" }
  | { ok: false; reason: "stale"; rev: number };

/** The site's index of its files. `d1MediaStore` is one for the network's standard tables (MEDIA_LIBRARY_SQL). */
export interface MediaLibraryStore {
  /** Optional MediaItem fields the store keeps; any other is dropped on a write and never answered. */
  keeps?: { decorative?: boolean; rights?: boolean };
  /** One file, trashed or not; null when the key is not a library file. */
  record(key: string): Promise<MediaRecord | null>;
  /** Several files at once (at most 90 keys a call), in any order; keys that are not library files are left out. */
  records(keys: string[]): Promise<MediaRecord[]>;
  /** Every library file, trashed included. Lists filter and sort in the Worker: a site's library is small. */
  all(): Promise<MediaRecord[]>;
  /**
   * The file holding these bytes, trashed or not: one whose current bytes have this hash, the first uploaded; else one
   * that was uploaded or imported with it (an `upload` or `import` revision) before a shrink changed them, the earliest.
   */
  byHash(sha256: string): Promise<MediaRecord | null>;
  /** Adds a file at rev 0. Throws when the key is taken. */
  insert(record: Omit<MediaRecord, "rev">): Promise<void>;
  /** Writes `fields` and moves the rev by one, only while the row is at `expectedRev`. */
  writeAtRev(
    key: string,
    fields: MediaRecordFields,
    expectedRev: number,
  ): Promise<MediaRecordWrite>;
  /** Columns that follow a byte change the caller has already claimed: written as they are, the rev left alone. */
  follow(key: string, fields: MediaRecordFields): Promise<MediaRecord>;
  /** Records a set of bytes the file has had, and answers its id. */
  addRevision(key: string, revision: Omit<MediaRevisionRecord, "id">): Promise<number>;
  /** The file's revisions, newest first, at most `limit` (100 when absent). */
  revisions(key: string, limit?: number): Promise<MediaRevisionRecord[]>;
  /** Names the kept copy of a revision's bytes. */
  keepCopy(revisionId: number, copyKey: string): Promise<void>;
  /**
   * Removes the file's row and its revisions in one batch, only while the row is at `rev` (the version the reference check
   * saw). `stale` when it moved; `in-use` when the site's own tables still name the file and the store refused
   * atomically; `missing` when there was no row.
   */
  remove(key: string, rev: number): Promise<"removed" | "stale" | "in-use" | "missing">;
  /** Where the next poll of the change log starts: the newest entry's number, or 0 before the first. */
  changeCursor(): Promise<number>;
  /** Each file changed after `from` (up to `head`) once, at its latest change, oldest first; `limit + 1` at most. */
  changedSince(
    from: number,
    head: number,
    limit: number,
  ): Promise<Array<{ key: string; seq: number }>>;
}

/** The parts of an R2 object the library reads: no index signature, so Workers' own R2Object fits it. */
export interface MediaObject {
  etag: string;
  httpMetadata?: {
    contentType?: string;
    cacheControl?: string;
    contentDisposition?: string;
    contentEncoding?: string;
    contentLanguage?: string;
  };
  customMetadata?: Record<string, string>;
}

/** The parts of an R2 bucket binding the library uses, so a site passes its binding straight in. */
export interface MediaBucket {
  head(key: string): Promise<MediaObject | null>;
  get(
    key: string,
  ): Promise<(MediaObject & { body: ReadableStream; arrayBuffer(): Promise<ArrayBuffer> }) | null>;
  put(
    key: string,
    value: ArrayBuffer | Uint8Array | ReadableStream,
    options?: {
      httpMetadata?: MediaObject["httpMetadata"];
      customMetadata?: Record<string, string>;
      onlyIf?: { etagMatches: string };
    },
  ): Promise<MediaObject | null>;
  delete(keys: string | string[]): Promise<void>;
  list(options: {
    prefix: string;
    cursor?: string;
  }): Promise<{ objects: Array<{ key: string }>; truncated: boolean; cursor?: string }>;
}

/** The new file a key is made for. */
export interface MediaKeyInput {
  /** The stored name (prepareUpload's), with the stored type's extension. */
  filename: string;
  contentType: string;
  /** The upload's duplicates key (`uploadSha256`), lower case hex. */
  sha256: string;
  /** The SHA-256 of the bytes stored, which differs from `sha256` only for a converted or shrunk picture. */
  storedSha256: string;
  width: number | null;
  height: number | null;
  /** ISO 8601. */
  at: string;
}

/** One write the library made, for the site's audit or event log. */
export interface MediaLibraryEvent {
  op:
    | "upload"
    | "delete"
    | "alt"
    | "tags"
    | "trash"
    | "restore"
    | "focus"
    | "caption"
    | "credit"
    | "replace"
    | "transform"
    | "revert"
    | "resize";
  id: string;
  changeId: string;
  /** The file a turn stored as a new file. */
  newId?: string;
}

/**
 * The picture types every site takes (v0.27.0). No SVG, which would be script on the site's own origin. HEIC and HEIF (an
 * iPhone's photos) are taken too and stored as JPEG.
 */
export const PICTURE_TYPES = [
  "image/jpeg",
  "image/png",
  "image/webp",
  "image/avif",
  "image/gif",
  "image/heic",
  "image/heif",
] as const;

/** The upload limits every site starts from (v0.27.0): pictures only, 20 MiB each; a site passes its own `maxBytes` to change the size. */
export function pictureLimits(maxBytes = 20 * 1024 * 1024): MediaUploadLimits {
  return { maxBytes, types: [...PICTURE_TYPES] };
}

/**
 * What an upload shrinks to unless it says `resize=no` (v0.27.0): a phone photo (4032 pixels) keeps its size, a larger
 * camera file is shrunk and its original is kept in the file's history.
 */
export const PICTURE_RESIZE: MediaResize = { maxEdge: 2560, quality: 85 };

export interface MediaLibraryOptions {
  store: MediaLibraryStore;
  /** The bucket the site serves its files from, under their keys. */
  bucket: MediaBucket;
  /** The Images binding: measuring, HEIC to JPEG, shrinks, turns, placeholders. */
  images: UploadImages;
  limits: MediaUploadLimits;
  /** Where the site serves a file. */
  url(key: string): string;
  /** Where the original downloads from; `url` when absent. */
  downloadUrl?(key: string): string;
  /**
   * The key for a new file, `attempt` 1 first, 2 and on when the one before is taken (by a row or an object). Absent:
   * `datedKey("uploads/")`. Throw RefusedError when no other key will do.
   */
  key?(file: MediaKeyInput, attempt: number): string;
  /** What uploads shrink to (capabilities.mediaResize). Absent: nothing is shrunk, and there is no oversized lens or resize pass. */
  resize?: MediaResize;
  /**
   * False for a site whose addresses carry a picture's size, so a stored picture is never shrunk in place (no resize pass,
   * capabilities.mediaResizePass). On by default where `resize` is set.
   */
  shrink?: boolean;
  /** True when pages hold a picture's width and height, so a replace or revert keeps them and a quarter turn is a new file. */
  replaceKeepsSize?: boolean;
  /**
   * The site's reference check: for each key asked (every library file when `keys` is absent), the places that use it.
   * The library asks at most 90 keys a call, so a check that binds each key stays under D1's 100. Keys with no use may
   * be left out. Throw when the check cannot run: a delete is then refused, never made. Absent: the
   * site counts no uses, and a delete removes the file.
   */
  usage?(keys?: string[]): Promise<Map<string, MediaUse[]>>;
  /**
   * False for a file that is part of the site itself (its own static assets): listed with `deletable: false`, and every
   * write and delete of it refused. Every file is deletable by default.
   */
  deletable?(record: MediaRecord): boolean;
  /**
   * Where earlier bytes are kept: `bucket` (the served bucket by default) under `prefix` (by default "history/"), at
   * <prefix><key>/<sha256>. Copies in the served bucket go when their file is deleted, and the site's media route must
   * never serve the prefix; copies in another bucket (a private backups bucket) are kept, with the file's last bytes beside them.
   */
  history?: { bucket?: MediaBucket; prefix?: string };
  /** HTTP metadata every object of the library carries beside its type, such as a cache-control. */
  httpMetadata?(record: Pick<MediaRecord, "key" | "contentType">): Record<string, string>;
  /** Custom metadata the object carries beside its focal point, written at upload and after each change of its bytes. */
  customMetadata?(record: MediaRecord): Record<string, string>;
  /** Runs after a file's bytes changed under the same key, such as a re-render of the pages that hold its size. */
  afterBytes?(key: string): Promise<void>;
  /** Runs after each write, for the site's audit or event log. A throw here fails the call. */
  onWrite?(event: MediaLibraryEvent): Promise<void> | void;
  /** The site's suggester (mediaSuggester's `suggest`), behind `suggest` and `suggestFile`. */
  suggest?(
    picture: ReadableStream,
    id?: string,
  ): Promise<{ tags: string[]; alt: string | null; model: string }>;
  /**
   * The fetch imports go through (capabilities.mediaImport). The package checks each address and redirect first. v0.27.0:
   * the Worker's own `fetch` when absent, so imports are on; `null` turns them off.
   */
  importFetch?: typeof fetch | null;
  /** The clock, for tests. */
  now?(): Date;
}

// ---------- Keys

const EXTENSIONS: Record<string, string> = {
  "image/jpeg": "jpg",
  "image/png": "png",
  "image/webp": "webp",
  "image/avif": "avif",
  "image/gif": "gif",
  "image/svg+xml": "svg",
  "application/pdf": "pdf",
  "text/csv": "csv",
  "text/plain": "txt",
  "audio/mpeg": "mp3",
  "audio/mp4": "m4a",
  "video/mp4": "mp4",
};

/** The extension a stored type is named with: the known one, else the file's own, else "bin". */
export function extensionFor(contentType: string, filename: string): string {
  const own = /\.([A-Za-z0-9]{1,8})$/.exec(filename)?.[1]?.toLowerCase();
  return EXTENSIONS[contentType] ?? own ?? "bin";
}

/**
 * The network's key for a new file: <prefix><yyyy>/<mm>/<name>-<hash>.<ext>, the name a slug of the stored name (at most
 * 60 characters, "file" when none is left) and the hash the first 8 of the upload's, with -2, -3 and on for a taken key.
 */
export function datedKey(prefix: string): (file: MediaKeyInput, attempt: number) => string {
  return (file, attempt) => {
    const name = slugify(file.filename.replace(/\.[^./]*$/, ""), { max: 60 }) || "file";
    return `${prefix}${file.at.slice(0, 4)}/${file.at.slice(5, 7)}/${name}-${file.sha256.slice(0, 8)}${attempt === 1 ? "" : `-${attempt}`}.${extensionFor(file.contentType, file.filename)}`;
  };
}

// ---------- The library

const LIBRARY_LENSES = [
  "no-alt",
  "large",
  "duplicates",
  "license-expired",
] as const satisfies readonly MediaLens[];

/** What the Images binding re-encodes in its own type. Not a GIF: it may be animated, and an edit keeps one frame. */
type Encoded = "image/jpeg" | "image/png" | "image/webp" | "image/avif";
const REENCODED = new Set<string>(["image/jpeg", "image/png", "image/webp", "image/avif"]);

/** The quality a turn or a mirror encodes at: high, since each one re-encodes a lossy picture. */
const TRANSFORM_QUALITY = 92;

/** Each transform as editImage's options. A quarter turn is clockwise, as the contract's rotate-90 is. */
const TRANSFORMS: Record<MediaTransformOp, { rotate?: 90 | 180 | 270; flip?: "h" | "v" }> = {
  "rotate-90": { rotate: 90 },
  "rotate-180": { rotate: 180 },
  "rotate-270": { rotate: 270 },
  "flip-h": { flip: "h" },
  "flip-v": { flip: "v" },
};

const OFFSET = /^(0|[1-9]\d{0,8})$/;
const SEQ = /^(0|[1-9]\d{0,15})$/;
const RACED =
  "The file changed on the site while this was being written, so its bytes were kept as they were. Reload it and try again.";

/** Every revision a delete or a revert looks through; the history panel shows the newest 100. */
const ALL_REVISIONS = 10_000;

const positive = (n: number | null): number | null => (n !== null && n > 0 ? n : null);

/** The whole media group over the site's store and bucket. */
export function mediaLibrary(options: MediaLibraryOptions): MediaAdapter {
  const { store, bucket, images, resize } = options;
  const keyOf = options.key
    ? (file: MediaKeyInput, attempt: number) => options.key!(file, attempt)
    : datedKey("uploads/");
  const historyBucket = options.history?.bucket ?? bucket;
  const historyPrefix = options.history?.prefix ?? "history/";
  const historyServed = historyBucket === bucket;
  const shrinks = Boolean(resize) && options.shrink !== false;
  const keepsDecorative = store.keeps?.decorative === true;
  const keepsRights = store.keeps?.rights === true;
  const now = () => (options.now ? options.now() : new Date());
  const deletable = (record: MediaRecord) => options.deletable?.(record) ?? true;

  const lenses: MediaLens[] = [
    ...(options.usage ? (["unattached"] as const) : []),
    ...LIBRARY_LENSES,
    ...(resize ? (["oversized"] as const) : []),
  ];

  /** The site's uses, or the refusal when its check cannot run. */
  async function usesOf(keys?: string[]): Promise<Map<string, MediaUse[]>> {
    if (!options.usage) return new Map();
    try {
      if (!keys) return await options.usage();
      const uses = new Map<string, MediaUse[]>();
      for (let n = 0; n < keys.length; n += 90)
        for (const [key, used] of await options.usage(keys.slice(n, n + 90))) uses.set(key, used);
      return uses;
    } catch (error) {
      throw new RefusedError(
        `The site could not check where its files are used, so nothing was done (${error instanceof Error ? error.message : String(error)}).`,
      );
    }
  }

  /** One file in the contract's terms. */
  function itemOf(record: MediaRecord, uses?: Map<string, MediaUse[]>): MediaItem {
    return {
      id: record.key,
      url: options.url(record.key),
      downloadUrl: options.downloadUrl?.(record.key) ?? options.url(record.key),
      filename: record.filename === null ? null : record.filename.slice(0, 300),
      contentType: record.contentType,
      bytes: record.bytes,
      width: positive(record.width),
      height: positive(record.height),
      alt: record.alt,
      uploadedAt: record.uploadedAt,
      deletable: deletable(record),
      version: mediaVersion(record.rev),
      tags: record.tags,
      trashedAt: record.trashedAt,
      focus: record.focus,
      caption: record.caption,
      placeholder: record.placeholder,
      color: record.color,
      credit: record.credit,
      license: record.license,
      sourceUrl: record.sourceUrl,
      licenseExpires: record.licenseExpires,
      takenAt: record.takenAt,
      ...(keepsDecorative && record.decorative !== undefined
        ? { decorative: record.decorative }
        : {}),
      ...(keepsRights
        ? {
            copyright: record.copyright ?? "",
            licenseUrl: record.licenseUrl ?? null,
            acquireLicenseUrl: record.acquireLicenseUrl ?? null,
          }
        : {}),
      ...(uses ? { usedCount: uses.get(record.key)?.length ?? 0 } : {}),
    };
  }

  /** An item with its use count, from one check of that file alone. */
  async function itemWithUse(record: MediaRecord): Promise<MediaItem> {
    return itemOf(record, options.usage ? await usesOf([record.key]) : undefined);
  }

  /** A file a write may change: one that exists and that the site lets this API change. */
  async function recordOf(id: string): Promise<MediaRecord> {
    const record = await store.record(id);
    if (!record) throw new NotFoundError("No such media.");
    if (!deletable(record))
      throw new RefusedError(
        "This file is part of the site itself, so it is not changed or deleted here.",
      );
    return record;
  }

  /** Refuses a stale version before any costly work; the claim checks it again. */
  function atVersion(record: MediaRecord, expectedVersion: string): void {
    if (record.rev !== mediaRev(expectedVersion))
      throw new VersionConflictError(
        mediaVersion(record.rev),
        "The file changed since it was loaded.",
      );
  }

  function settle(written: MediaRecordWrite): MediaRecord {
    if (written.ok) return written.record;
    if (written.reason === "missing") throw new NotFoundError("No such media.");
    throw new VersionConflictError(
      mediaVersion(written.rev),
      "The file changed since it was loaded.",
    );
  }

  /** Only the optional fields the store keeps. */
  function kept(fields: MediaRecordFields): MediaRecordFields {
    const { decorative, copyright, licenseUrl, acquireLicenseUrl, ...rest } = fields;
    return {
      ...rest,
      ...(keepsDecorative && decorative !== undefined ? { decorative } : {}),
      ...(keepsRights && copyright !== undefined ? { copyright } : {}),
      ...(keepsRights && licenseUrl !== undefined ? { licenseUrl } : {}),
      ...(keepsRights && acquireLicenseUrl !== undefined ? { acquireLicenseUrl } : {}),
    };
  }

  /** A metadata write at the version the editor loaded. */
  async function write(
    op: MediaLibraryEvent["op"],
    id: string,
    input: { expectedVersion: string; changeId: string },
    fields: MediaRecordFields,
  ): Promise<{ version: string }> {
    await recordOf(id);
    const record = settle(
      await store.writeAtRev(id, kept(fields), mediaRev(input.expectedVersion)),
    );
    await options.onWrite?.({ op, id, changeId: input.changeId });
    return { version: mediaVersion(record.rev) };
  }

  /** Trash and restore: a file already in the asked state, at the version it holds, answers that version unchanged. */
  async function moveTrash(
    op: "trash" | "restore",
    id: string,
    input: { expectedVersion: string; changeId: string },
  ): Promise<{ version: string }> {
    const record = await recordOf(id);
    atVersion(record, input.expectedVersion);
    if ((record.trashedAt !== null) === (op === "trash"))
      return { version: mediaVersion(record.rev) };
    return write(op, id, input, { trashedAt: op === "trash" ? now().toISOString() : null });
  }

  /** Claims the version for a write that changes the object: the rev moves first, so a stale writer changes nothing. */
  async function claim(id: string, expectedVersion: string): Promise<MediaRecord> {
    return settle(await store.writeAtRev(id, {}, mediaRev(expectedVersion)));
  }

  /** The object's custom metadata for a record: the site's fields, and the focal point when there is one. */
  function objectMetadata(
    record: MediaRecord,
    held: Record<string, string> = {},
  ): Record<string, string> {
    const { [FOCUS_METADATA]: _old, ...rest } = held;
    return {
      ...rest,
      ...options.customMetadata?.(record),
      ...(record.focus ? { [FOCUS_METADATA]: record.focus } : {}),
    };
  }

  /** Bytes as the library stores them; a replace or a shrink is not an upload, so it has no alt and no duplicates key. */
  const prepare = (
    bytes: Uint8Array,
    contentType: string,
    filename: string,
    changeId: string,
    shrink: boolean,
  ) =>
    prepareUpload(
      images,
      { bytes, contentType, filename, alt: "", changeId, resize: shrink },
      resize ? { resize } : {},
    );

  /** Refuses a picture the Images binding could not measure: its bytes are broken, and no page could size it. */
  function measured<T extends { contentType: string; width: number | null }>(prepared: T): T {
    if (
      prepared.width === null &&
      kindOf(prepared.contentType) === "image" &&
      prepared.contentType !== "image/svg+xml"
    ) {
      throw new RefusedError(
        "Cloudflare Images could not read this picture, so it was not stored. Save it again from an image editor and upload that.",
      );
    }
    return prepared;
  }

  /**
   * Claims a key no row or object holds by inserting the file's row under it: the row's primary key is the lock, so two
   * uploads of the same file at once never share a key. Answers the key.
   */
  async function claimKey(
    file: MediaKeyInput,
    record: Omit<MediaRecord, "rev" | "key">,
  ): Promise<string> {
    for (let attempt = 1; attempt <= 50; attempt++) {
      const key = keyOf(file, attempt);
      if ((await store.record(key)) || (await bucket.head(key))) continue;
      try {
        await store.insert({ ...record, key });
        return key;
      } catch (error) {
        // Another upload took the key between the check and the insert: try the next.
        if (await store.record(key)) continue;
        throw error;
      }
    }
    throw new RefusedError("No free name was found for this file. Rename it and upload it again.");
  }

  /** Keeps a set of bytes as a copy, and answers where. Content-addressed, so keeping the same bytes twice is one copy. */
  async function keepCopy(
    key: string,
    sha256: string,
    body: ReadableStream | Uint8Array | ArrayBuffer,
    contentType: string,
  ): Promise<string> {
    const copyKey = `${historyPrefix}${key}/${sha256}`;
    await historyBucket.put(copyKey, body, { httpMetadata: { contentType } });
    return copyKey;
  }

  /**
   * Stores a new file: its row first, which claims the key, then the object (the row removed again if the object cannot
   * be written), then its first revisions. Answers the row.
   */
  async function storeFile(file: {
    bytes: Uint8Array;
    contentType: string;
    filename: string;
    uploadSha256: string;
    sha256: string;
    width: number | null;
    height: number | null;
    fields: MediaRecordFields;
    reason: MediaRevisionReason;
    original?: { bytes: Uint8Array; width: number; height: number };
  }): Promise<MediaRecord> {
    const at = now().toISOString();
    const record: Omit<MediaRecord, "rev" | "key"> = {
      filename: file.filename.slice(0, 300),
      contentType: file.contentType,
      bytes: file.bytes.byteLength,
      width: file.width,
      height: file.height,
      sha256: file.sha256,
      alt: "",
      caption: "",
      tags: [],
      focus: null,
      credit: "",
      license: "",
      sourceUrl: null,
      licenseExpires: null,
      takenAt: null,
      placeholder: null,
      color: null,
      uploadedAt: at,
      trashedAt: null,
      ...kept(file.fields),
    };
    const key = await claimKey(
      {
        filename: file.filename,
        contentType: file.contentType,
        sha256: file.uploadSha256,
        storedSha256: file.sha256,
        width: file.width,
        height: file.height,
        at,
      },
      record,
    );
    try {
      await bucket.put(key, file.bytes, {
        httpMetadata: {
          ...options.httpMetadata?.({ ...record, key }),
          contentType: file.contentType,
        },
        customMetadata: objectMetadata({ ...record, key, rev: 0 }),
      });
    } catch (error) {
      const claimed = await store.record(key);
      if (claimed) await store.remove(key, claimed.rev);
      throw error;
    }
    if (file.original) {
      // The original kept as the revision the shrink replaced.
      const originalSha = await sha256Hex(file.original.bytes);
      const copyKey = await keepCopy(key, originalSha, file.original.bytes, file.contentType);
      await store.addRevision(key, {
        at,
        bytes: file.original.bytes.byteLength,
        width: file.original.width,
        height: file.original.height,
        reason: file.reason,
        sha256: originalSha,
        copyKey,
      });
      await store.addRevision(key, {
        at,
        bytes: file.bytes.byteLength,
        width: file.width,
        height: file.height,
        reason: "resize",
        sha256: file.sha256,
        copyKey: null,
      });
    } else {
      await store.addRevision(key, {
        at,
        bytes: file.bytes.byteLength,
        width: file.width,
        height: file.height,
        reason: file.reason,
        sha256: file.sha256,
        copyKey: null,
      });
    }
    const stored = await store.record(key);
    if (!stored) throw new Error(`${key} was stored, but its row cannot be read`);
    return stored;
  }

  /**
   * Puts new bytes under a file's key as its newest revision, the old ones kept first: the one way a stored file's bytes
   * change. The caller has already claimed the version. `fields` are the columns that move with the bytes.
   */
  async function swapBytes(
    record: MediaRecord,
    next: {
      bytes: Uint8Array;
      width: number | null;
      height: number | null;
      reason: MediaRevisionReason;
    },
    fields: MediaRecordFields,
  ): Promise<MediaRecord> {
    const current = await bucket.get(record.key);
    if (!current) throw new NotFoundError("No such media.");
    const held = new Uint8Array(await current.arrayBuffer());
    // Hashed here, never taken from the row: a copy's name must be its own bytes, or it overwrites another's.
    const heldSha = await sha256Hex(held);
    const copyKey = await keepCopy(record.key, heldSha, held, record.contentType);
    // The newest revision names the copy only when it is these bytes and names none yet: a copy recorded under an older
    // scheme is kept as it is, and a newest row that is other bytes gets a row of its own for these.
    const [latest] = await store.revisions(record.key, 1);
    const isHeld =
      latest !== undefined && (latest.sha256 ? latest.sha256 === heldSha : !latest.copyKey);
    if (isHeld && !latest.copyKey) await store.keepCopy(latest.id, copyKey);
    if (!isHeld) {
      await store.addRevision(record.key, {
        at: latest ? now().toISOString() : record.uploadedAt,
        bytes: held.byteLength,
        width: record.width,
        height: record.height,
        reason: latest ? "replace" : record.sourceUrl ? "import" : "upload",
        sha256: heldSha,
        copyKey,
      });
    }
    const sha256 = await sha256Hex(next.bytes);
    const after: MediaRecord = {
      ...record,
      ...kept(fields),
      bytes: next.bytes.byteLength,
      width: next.width,
      height: next.height,
      sha256,
    };
    const written = await bucket.put(record.key, next.bytes, {
      httpMetadata: { ...current.httpMetadata, contentType: record.contentType },
      customMetadata: objectMetadata(after, current.customMetadata),
      onlyIf: { etagMatches: current.etag },
    });
    if (!written) throw new RefusedError(RACED);
    // The row first, so it describes the bytes served even if the revision cannot be written.
    const followed = await store.follow(record.key, {
      ...kept(fields),
      bytes: next.bytes.byteLength,
      width: next.width,
      height: next.height,
      sha256,
    });
    await store.addRevision(record.key, {
      at: now().toISOString(),
      bytes: next.bytes.byteLength,
      width: next.width,
      height: next.height,
      reason: next.reason,
      sha256,
      copyKey: null,
    });
    await options.afterBytes?.(record.key);
    return followed;
  }

  /** Placeholder and color for new bytes, where the binding can measure them. */
  const looks = (bytes: Uint8Array, width: number | null) =>
    width
      ? placeholderAndColor(images, bytes)
      : Promise.resolve({ placeholder: null, color: null });

  /** Every key the bucket holds under a prefix. */
  async function listed(prefix: string): Promise<string[]> {
    const keys: string[] = [];
    let cursor: string | undefined;
    do {
      const page = await historyBucket.list({ prefix, ...(cursor ? { cursor } : {}) });
      keys.push(...page.objects.map((o) => o.key));
      cursor = page.truncated ? page.cursor : undefined;
    } while (cursor);
    return keys;
  }

  const adapter: MediaAdapter = {
    limits: options.limits,
    lenses,
    filters: true,
    readsEmbedded: true,
    ...(options.replaceKeepsSize ? { replaceKeepsSize: true } : {}),
    ...(options.usage ? { usage: true } : {}),
    ...(resize ? { resize } : {}),
    ...(options.importFetch !== null
      ? { importFetch: options.importFetch ?? ((input, init) => fetch(input, init)) }
      : {}),

    async list(query: MediaListQuery): Promise<MediaList> {
      const start =
        query.cursor === undefined
          ? 0
          : OFFSET.test(query.cursor)
            ? Number(query.cursor)
            : Number.NaN;
      if (Number.isNaN(start))
        throw new RefusedError("That page cursor is not this site's; reload the library.");
      // The cursor first: a change that lands while the page is read is in the next poll, not lost between them.
      const cursor = String(await store.changeCursor());
      const records = await store.all();
      const uses = options.usage ? await usesOf() : undefined;
      const hashes = new Map<string, number>();
      for (const r of records) if (r.sha256) hashes.set(r.sha256, (hashes.get(r.sha256) ?? 0) + 1);
      const today = now().toISOString().slice(0, 10);
      const lens: Record<MediaLens, (r: MediaRecord) => boolean> = {
        unattached: (r) => (uses?.get(r.key)?.length ?? 0) === 0,
        "no-alt": (r) => r.alt.trim() === "" && r.decorative !== true,
        large: (r) => r.bytes > LARGE_MEDIA_BYTES,
        duplicates: (r) => r.sha256 !== null && (hashes.get(r.sha256) ?? 0) > 1,
        "license-expired": (r) => r.licenseExpires !== null && r.licenseExpires < today,
        oversized: (r) =>
          resize !== undefined && Math.max(r.width ?? 0, r.height ?? 0) > resize.maxEdge,
      };
      const needle = query.q?.trim().toLowerCase();
      const matching = records.filter(
        (r) =>
          (query.trashed === "only" ? r.trashedAt !== null : r.trashedAt === null) &&
          (!query.tag || r.tags.includes(query.tag)) &&
          (!needle ||
            [r.key, r.filename ?? "", r.alt, r.caption, r.credit, ...r.tags].some((t) =>
              t.toLowerCase().includes(needle),
            )) &&
          (!query.lens || lens[query.lens](r)) &&
          (!query.orientation ||
            orientationOf(positive(r.width), positive(r.height)) === query.orientation) &&
          (!query.kind || kindOf(r.contentType) === query.kind),
      );
      // The contract's defaults: added, size and used run largest first, name A to Z. Ties: newest first, then by key.
      const sort = query.sort ?? "added";
      const dir = query.dir ?? (sort === "name" ? "asc" : "desc");
      const keyOf_ = (r: MediaRecord): string | number =>
        sort === "size"
          ? r.bytes
          : sort === "used"
            ? (uses?.get(r.key)?.length ?? 0)
            : sort === "name"
              ? (r.filename ?? r.key).toLowerCase()
              : r.uploadedAt;
      const sorted = matching.sort((a, b) => {
        const [x, y] = [keyOf_(a), keyOf_(b)];
        const by = typeof x === "number" ? x - (y as number) : x.localeCompare(y as string);
        return (
          (dir === "asc" ? 1 : -1) * by ||
          b.uploadedAt.localeCompare(a.uploadedAt) ||
          a.key.localeCompare(b.key)
        );
      });
      const page = sorted.slice(start, start + query.limit);
      return {
        items: page.map((r) => itemOf(r, uses)),
        nextCursor: start + query.limit < sorted.length ? String(start + query.limit) : null,
        total: sorted.length,
        sorted: { sort, dir },
        changeCursor: cursor,
      };
    },

    async get(id): Promise<MediaDetail | null> {
      const record = await store.record(id);
      if (!record) return null;
      const uses = await usesOf([id]);
      const twins = record.sha256
        ? (await store.all())
            .filter((r) => r.sha256 === record.sha256 && r.key !== id)
            .sort((a, b) => b.uploadedAt.localeCompare(a.uploadedAt) || a.key.localeCompare(b.key))
            .slice(0, 50)
            .map((r) => ({ id: r.key, filename: r.filename }))
        : [];
      return {
        ...itemOf(record, options.usage ? uses : undefined),
        usedBy: uses.get(id) ?? [],
        twins,
      };
    },

    async upload(input): Promise<MediaUploaded> {
      // The limits again: the route checked them, and a site's own upload path calling this did not.
      const prepared = measured(
        await prepareUpload(images, input, {
          limits: options.limits,
          ...(resize ? { resize } : {}),
        }),
      );
      const found = prepared.embedded;
      const embeddable: MediaEmbeddedField[] = [
        "credit",
        "license",
        "caption",
        "takenAt",
        ...(keepsRights ? (["copyright", "licenseUrl", "acquireLicenseUrl"] as const) : []),
      ];
      const embedded = embeddable.filter((field) => found[field]);
      const record = await storeFile({
        bytes: prepared.bytes,
        contentType: prepared.contentType,
        filename: prepared.filename,
        uploadSha256: prepared.uploadSha256,
        sha256: prepared.sha256,
        width: prepared.width,
        height: prepared.height,
        fields: {
          alt: input.alt,
          ...(input.decorative ? { decorative: true } : {}),
          caption: found.caption ?? "",
          credit: found.credit ?? "",
          license: found.license ?? "",
          takenAt: found.takenAt ?? null,
          copyright: found.copyright ?? "",
          licenseUrl: found.licenseUrl ?? null,
          acquireLicenseUrl: found.acquireLicenseUrl ?? null,
          sourceUrl: input.sourceUrl ?? null,
          placeholder: prepared.placeholder,
          color: prepared.color,
        },
        reason: input.sourceUrl ? "import" : "upload",
        ...(prepared.resizedFrom && prepared.original
          ? {
              original: {
                bytes: prepared.original,
                width: prepared.resizedFrom.width,
                height: prepared.resizedFrom.height,
              },
            }
          : {}),
      });
      await options.onWrite?.({ op: "upload", id: record.key, changeId: input.changeId });
      return {
        ...(await itemWithUse(record)),
        ...(embedded.length > 0 ? { embedded } : {}),
        ...(prepared.resizedFrom ? { resizedFrom: prepared.resizedFrom } : {}),
      };
    },

    // The reference check, then the rows (refused atomically where the store guards them), then the objects, so a failure
    // leaves only bytes nothing lists.
    async delete(id, input) {
      const record = await recordOf(id);
      const uses = await usesOf([id]);
      const using = uses.get(id) ?? [];
      if (using.length > 0) throw new MediaInUseError(using);
      const copies = historyServed
        ? (await store.revisions(id, ALL_REVISIONS)).flatMap((r) => (r.copyKey ? [r.copyKey] : []))
        : [];
      if (!historyServed) {
        // A backups bucket keeps the last bytes too, so a file deleted for good can still be put back by hand.
        const last = await bucket.get(id);
        if (last) {
          const bytes = new Uint8Array(await last.arrayBuffer());
          await keepCopy(id, await sha256Hex(bytes), bytes, record.contentType);
        }
      }
      const removed = await store.remove(id, record.rev);
      if (removed === "missing") throw new NotFoundError("No such media.");
      if (removed === "stale")
        throw new RefusedError(
          "The file changed while it was being deleted, so it was kept. Reload it, then delete it again.",
        );
      if (removed === "in-use") {
        const now_ = (await usesOf([id])).get(id) ?? [];
        if (now_.length > 0) throw new MediaInUseError(now_);
        throw new RefusedError(
          "The file came into use while it was being deleted, so it was kept. Check where it is used, then try again.",
        );
      }
      const extra = historyServed ? await listed(`${historyPrefix}${id}/`) : [];
      // The file first, then its copies, at most 1000 keys a call (R2's limit).
      await bucket.delete(id);
      const gone = [...new Set([...copies, ...extra])];
      for (let n = 0; n < gone.length; n += 1000) await bucket.delete(gone.slice(n, n + 1000));
      await options.onWrite?.({ op: "delete", id, changeId: input.changeId });
    },

    setAlt: (id, input) =>
      write("alt", id, input, {
        alt: input.alt,
        ...(input.decorative !== undefined ? { decorative: input.decorative } : {}),
      }),
    setTags: (id, input) => write("tags", id, input, { tags: input.tags }),
    trash: (id, input) => moveTrash("trash", id, input),
    restore: (id, input) => moveTrash("restore", id, input),
    setCaption: (id, input) => write("caption", id, input, { caption: input.caption }),

    // The object's customMetadata `focus` is what site-runtime ./image crops around. Claimed first, then the object, then
    // the row.
    async setFocus(id, input) {
      const record = await recordOf(id);
      atVersion(record, input.expectedVersion);
      const object = await bucket.get(id);
      if (!object) throw new NotFoundError("No such media.");
      const claimed = await claim(id, input.expectedVersion);
      const after = { ...claimed, focus: input.focus };
      const written = await bucket.put(id, await object.arrayBuffer(), {
        ...(object.httpMetadata ? { httpMetadata: object.httpMetadata } : {}),
        customMetadata: objectMetadata(after, object.customMetadata),
        onlyIf: { etagMatches: object.etag },
      });
      if (!written) throw new RefusedError(RACED);
      await store.follow(id, { focus: input.focus });
      await options.onWrite?.({ op: "focus", id, changeId: input.changeId });
      return { version: mediaVersion(claimed.rev) };
    },

    setCredit: (id, input) =>
      write("credit", id, input, {
        credit: input.credit,
        license: input.license,
        sourceUrl: input.sourceUrl,
        licenseExpires: input.licenseExpires,
        ...(input.copyright !== undefined ? { copyright: input.copyright } : {}),
        ...(input.licenseUrl !== undefined ? { licenseUrl: input.licenseUrl } : {}),
        ...(input.acquireLicenseUrl !== undefined
          ? { acquireLicenseUrl: input.acquireLicenseUrl }
          : {}),
      }),

    // The image route keys each cached size on the object's etag (site-runtime ./image), so no stored size of the old
    // bytes is served after a replace.
    async replace(id, input) {
      const record = await recordOf(id);
      atVersion(record, input.expectedVersion);
      const prepared = measured(
        await prepare(input.bytes, input.contentType, input.filename, input.changeId, false),
      );
      if (
        options.replaceKeepsSize &&
        (prepared.width !== positive(record.width) || prepared.height !== positive(record.height))
      ) {
        throw new RefusedError(
          `Pages on this site hold this picture's size (${record.width ?? "?"} by ${record.height ?? "?"}), and the new one is ${prepared.width ?? "?"} by ${prepared.height ?? "?"}. Upload it as a new file instead.`,
        );
      }
      const claimed = await claim(id, input.expectedVersion);
      const after = await swapBytes(
        claimed,
        {
          bytes: prepared.bytes,
          width: prepared.width,
          height: prepared.height,
          reason: "replace",
        },
        {
          focus: null,
          filename: input.filename.slice(0, 300),
          placeholder: prepared.placeholder,
          color: prepared.color,
        },
      );
      await options.onWrite?.({ op: "replace", id, changeId: input.changeId });
      return { item: await itemWithUse(after), sizesNeedPurge: false };
    },

    async findByHash(sha256) {
      const record = await store.byHash(sha256);
      return record ? itemWithUse(record) : null;
    },

    // In place, unless the package asks for a new file (a quarter turn of a picture that is not square, on a site whose
    // pages hold its size): then the turned picture is stored as a new file with the old one's words, and the old is kept.
    async transform(id, input) {
      const record = await recordOf(id);
      atVersion(record, input.expectedVersion);
      if (!REENCODED.has(record.contentType))
        throw new RefusedError(
          `A ${record.contentType} file is not turned here: a GIF may be animated, and an edit would keep one frame.`,
        );
      const object = await bucket.get(id);
      if (!object) throw new NotFoundError("No such media.");
      const edited = await editImage(images, object.body, {
        ...TRANSFORMS[input.op],
        quality: TRANSFORM_QUALITY,
        format: record.contentType as Encoded,
      });
      const bytes = new Uint8Array(await edited.arrayBuffer());
      const [width, height] = turnsSize(input.op)
        ? [record.height, record.width]
        : [record.width, record.height];
      const focus = transformFocus(record.focus, input.op);
      const { placeholder, color } = await looks(bytes, width);
      if (input.asNewFile) {
        const sha256 = await sha256Hex(bytes);
        const created = await storeFile({
          bytes,
          contentType: record.contentType,
          filename: record.filename ?? id.split("/").pop()!,
          uploadSha256: sha256,
          sha256,
          width,
          height,
          fields: {
            alt: record.alt,
            ...(record.decorative !== undefined ? { decorative: record.decorative } : {}),
            caption: record.caption,
            tags: record.tags,
            focus,
            credit: record.credit,
            license: record.license,
            sourceUrl: record.sourceUrl,
            licenseExpires: record.licenseExpires,
            takenAt: record.takenAt,
            ...(record.copyright !== undefined ? { copyright: record.copyright } : {}),
            ...(record.licenseUrl !== undefined ? { licenseUrl: record.licenseUrl } : {}),
            ...(record.acquireLicenseUrl !== undefined
              ? { acquireLicenseUrl: record.acquireLicenseUrl }
              : {}),
            placeholder,
            color,
          },
          reason: "transform",
        });
        await options.onWrite?.({
          op: "transform",
          id,
          changeId: input.changeId,
          newId: created.key,
        });
        return { item: await itemWithUse(created), sizesNeedPurge: false };
      }
      const claimed = await claim(id, input.expectedVersion);
      const after = await swapBytes(
        claimed,
        { bytes, width, height, reason: "transform" },
        { focus, placeholder, color },
      );
      await options.onWrite?.({ op: "transform", id, changeId: input.changeId });
      return { item: await itemWithUse(after), sizesNeedPurge: false };
    },

    // A file never changed has one revision, its bytes as uploaded, whether or not the site recorded it.
    async history(id) {
      const record = await store.record(id);
      if (!record) return null;
      const revisions = await store.revisions(id);
      const listed_ =
        revisions.length > 0
          ? revisions
          : [
              {
                id: 0,
                at: record.uploadedAt,
                bytes: record.bytes,
                width: record.width,
                height: record.height,
                reason: record.sourceUrl ? ("import" as const) : ("upload" as const),
                sha256: record.sha256,
                copyKey: null,
              },
            ];
      return listed_.map((r, n) => ({
        rev: String(r.id),
        at: r.at,
        bytes: r.bytes,
        width: positive(r.width),
        height: positive(r.height),
        reason: r.reason,
        current: n === 0,
      }));
    },

    // The package has checked that `to` is an earlier revision; its bytes come back from the copy kept, as a new
    // revision, so a revert is itself undone by another.
    async revert(id, input) {
      const record = await recordOf(id);
      atVersion(record, input.expectedVersion);
      const target = (await store.revisions(id, ALL_REVISIONS)).find(
        (r) => String(r.id) === input.to,
      );
      const copy = target?.copyKey ? await historyBucket.get(target.copyKey) : null;
      if (!target || !copy)
        throw new NotFoundError("This file has no such earlier version, or its copy is gone.");
      const bytes = new Uint8Array(await copy.arrayBuffer());
      const width = positive(target.width);
      const claimed = await claim(id, input.expectedVersion);
      const after = await swapBytes(
        claimed,
        { bytes, width, height: positive(target.height), reason: "revert" },
        { focus: null, ...(await looks(bytes, width)) },
      );
      await options.onWrite?.({ op: "revert", id, changeId: input.changeId });
      return { item: await itemWithUse(after), sizesNeedPurge: false };
    },

    // From the change log the store keeps: every insert, update and delete of a row.
    async changes({ since, limit }) {
      const head = await store.changeCursor();
      if (!SEQ.test(since) || Number(since) > head)
        throw new RefusedError("That change cursor is not this site's; reload the library.");
      const changed = await store.changedSince(Number(since), head, limit);
      const more = changed.length > limit;
      const taken = changed.slice(0, limit);
      // In groups of 90: D1 binds at most 100 values to a statement, and a poll may name up to 200 files.
      const keys = taken.map((c) => c.key);
      const found: MediaRecord[] = [];
      for (let n = 0; n < keys.length; n += 90)
        found.push(...(await store.records(keys.slice(n, n + 90))));
      const records = new Map(found.map((r) => [r.key, r]));
      const uses =
        options.usage && records.size > 0 ? await usesOf([...records.keys()]) : undefined;
      return {
        items: taken.flatMap((c) => {
          const record = records.get(c.key);
          return record ? [itemOf(record, options.usage ? (uses ?? new Map()) : undefined)] : [];
        }),
        removed: taken.filter((c) => !records.has(c.key)).map((c) => c.key),
        cursor: String(more ? taken[taken.length - 1]!.seq : head),
        more,
      };
    },

    ...(options.suggest
      ? {
          // Never applied: Carrel shows them, and a person accepts each as an alt or tags write.
          async suggest(id: string) {
            const record = await store.record(id);
            if (!record) return null;
            if (kindOf(record.contentType) !== "image")
              throw new RefusedError("Only a picture gets suggestions.");
            const object = await bucket.get(id);
            if (!object) return null;
            try {
              return await options.suggest!(object.body, id);
            } catch (error) {
              throw new RefusedError(
                `No suggestion was made: ${error instanceof Error ? error.message : String(error)}`,
              );
            }
          },
          async suggestFile({ bytes }: { bytes: Uint8Array; contentType: string }) {
            return options.suggest!(new Response(toArrayBuffer(bytes)).body!);
          },
        }
      : {}),
  };

  if (shrinks && resize) {
    // In place, the old bytes kept in the history; a picture already within the size answers as it is, and so does a GIF
    // (prepareUpload shrinks none: it may be animated). The focal point stays: a shrink keeps the picture's proportions.
    adapter.shrink = async (id, input) => {
      const record = await recordOf(id);
      atVersion(record, input.expectedVersion);
      if (
        Math.max(record.width ?? 0, record.height ?? 0) <= resize.maxEdge ||
        !REENCODED.has(record.contentType)
      )
        return { resized: false, item: await itemWithUse(record) };
      const object = await bucket.get(id);
      if (!object) throw new NotFoundError("No such media.");
      const prepared = await prepare(
        new Uint8Array(await object.arrayBuffer()),
        record.contentType,
        record.filename ?? id,
        input.changeId,
        true,
      );
      if (!prepared.resizedFrom) return { resized: false, item: await itemWithUse(record) };
      const claimed = await claim(id, input.expectedVersion);
      const after = await swapBytes(
        claimed,
        { bytes: prepared.bytes, width: prepared.width, height: prepared.height, reason: "resize" },
        { placeholder: prepared.placeholder, color: prepared.color },
      );
      await options.onWrite?.({ op: "resize", id, changeId: input.changeId });
      return { resized: true, item: await itemWithUse(after) };
    };
  }

  return adapter;
}

