// The meta route, the content routes and the preview: what every site serves.

import { createTwoFilesPatch } from "diff";
import {
  capabilitiesOf,
  contentFiltersOf,
  hasContentTrash,
  NotFoundError,
  RefusedError,
  VersionConflictError,
  type SiteAdapter,
} from "../adapter.js";
import {
  BacklinkList,
  ContentDeleteQuery,
  ContentDeleteResult,
  ContentDoc,
  ContentId,
  ContentList,
  ContentTagsInput,
  ContentTrashInput,
  Diff,
  DiffQuery,
  ListQuery,
  Meta,
  PACKAGE_VERSION,
  PreviewInput,
  PublishInput,
  RenameInput,
  RenameResult,
  RevisionList,
  RevisionSource,
  SaveDraftInput,
  ScheduleCancelQuery,
  ScheduleInput,
  ScheduledUpdate,
  UnpublishInput,
  Version,
  WriteResult,
  schemaHash,
  filtersAsked,
} from "../contract.js";
import { splitSource } from "@drdustinedwards/site-helpers/frontmatter";
import { missingAltFields } from "../frontmatter.js";
import {
  BadRequest,
  BASE_HEADERS,
  ContractBreach,
  ID,
  checked,
  fail,
  json,
  pathParam,
  readBody,
  readQuery,
  type Route,
} from "./http.js";

/** A DELETE's `actorName` (v0.22.0) as the `actor` every other write hands the adapter. */
function withActor<T extends { actorName?: string | undefined }>(
  query: T,
): Omit<T, "actorName"> & { actor?: { name: string } } {
  const { actorName, ...rest } = query;
  return { ...rest, ...(actorName ? { actor: { name: actorName } } : {}) };
}

export function contentRoutes(
  adapter: SiteAdapter,
  options: { store: boolean; hooks?: readonly string[] },
): Route[] {
  const id = (m: RegExpMatchArray) => pathParam(m[1], ContentId, "content id");

  // v0.22.0 (A2, D8): a feature image with no alt text blocks the text going out, as the share image's does in Carrel's
  // gate: a publish, a schedule, or a save to a live item. Only where the site lists featureImage; a decorative one passes.
  const postFields = adapter.content.postFields ?? [];
  async function altGate(contentId: string, source: string | undefined) {
    if (!postFields.includes("featureImage")) return;
    const outgoing = source ?? (await adapter.content.get(contentId))?.source;
    if (outgoing === undefined) return;
    if (missingAltFields(splitSource(outgoing).front, { postFields }).includes("featureImageAlt")) {
      throw new RefusedError(
        "The feature image has no alt text. Describe what it shows, or mark it decorative (featureImageDecorative: true), before the post goes out.",
      );
    }
  }

  const write = async (
    m: RegExpMatchArray,
    request: Request,
    run: (contentId: string, request: Request) => Promise<unknown>,
  ) => json(200, checked(WriteResult, await run(id(m), request), "write result"));

  return [
    {
      method: "GET",
      pattern: /^\/meta$/,
      run: async () =>
        json(
          200,
          checked(
            Meta,
            {
              api: "carrel-site-api",
              packageVersion: PACKAGE_VERSION,
              schemaHash: await schemaHash(),
              site: adapter.site,
              capabilities: capabilitiesOf(adapter, options),
            },
            "meta",
          ),
        ),
    },
    {
      method: "GET",
      query: true,
      pattern: /^\/content$/,
      run: async (_m, url) => {
        const query = readQuery(url, ListQuery);
        const offered = contentFiltersOf(adapter);
        const asked = filtersAsked(query);
        const missing = asked.find((f) => !offered.includes(f));
        if (missing)
          return fail(
            "not-implemented",
            `This site does not filter its content list by ${missing}.`,
          );
        const list = checked(ContentList, await adapter.content.list(query), "content list");
        return json(200, asked.length ? { ...list, filtered: asked } : list);
      },
    },
    {
      method: "GET",
      pattern: new RegExp(`^/content/${ID}$`),
      run: async (m) => {
        const doc = await adapter.content.get(id(m));
        if (!doc) throw new NotFoundError();
        return json(200, checked(ContentDoc, doc, "content"));
      },
    },
    {
      method: "PUT",
      pattern: new RegExp(`^/content/${ID}/draft$`),
      run: (m, _u, r) =>
        write(m, r, async (i, req) => {
          const input = await readBody(req, SaveDraftInput);
          if (
            postFields.includes("featureImage") &&
            (await adapter.content.get(i))?.status === "published"
          )
            await altGate(i, input.source);
          return adapter.content.saveDraft(i, input);
        }),
    },
    {
      method: "POST",
      pattern: new RegExp(`^/content/${ID}/publish$`),
      run: (m, _u, r) =>
        write(m, r, async (i, req) => {
          const input = await readBody(req, PublishInput);
          if (input.publishedAt !== undefined) {
            if (!adapter.content.publishedAtSettable)
              throw new BadRequest(
                "not-implemented",
                "This site does not set the date a post is published under.",
              );
            // A minute's grace for the caller's clock; a later date is a schedule, which says when the post goes live.
            if (Date.parse(input.publishedAt) > Date.now() + 60_000)
              throw new BadRequest(
                "invalid",
                "publishedAt is in the future. To publish later, schedule it.",
              );
          }
          await altGate(i, input.source);
          return adapter.content.publish(i, input);
        }),
    },
    {
      method: "POST",
      pattern: new RegExp(`^/content/${ID}/schedule$`),
      run: (m, _u, r) =>
        write(m, r, async (i, req) => {
          const input = await readBody(req, ScheduleInput);
          const current = await adapter.content.get(i);
          await altGate(i, input.source ?? current?.source);
          // v0.10.0: a live item keeps being served, and the schedule is an update that replaces it at the time.
          if (current?.status !== "published") return adapter.content.schedule(i, input);
          if (current.version !== input.expectedVersion)
            throw new VersionConflictError(current.version);
          if (!adapter.schedules) {
            throw new RefusedError(
              "This site cannot schedule an update to a live post: scheduling it would take the post off the site until then. Publish the change now, or unpublish first.",
            );
          }
          const { publishAt, expectedVersion, changeId, actor } = input;
          return adapter.schedules.update(i, {
            source: input.source ?? current.source,
            publishAt,
            expectedVersion,
            changeId,
            ...(actor ? { actor } : {}),
          });
        }),
    },
    {
      method: "GET",
      pattern: new RegExp(`^/content/${ID}/schedule$`),
      run: async (m) => {
        const contentId = id(m);
        if (!adapter.schedules)
          return fail("not-implemented", "This site does not schedule updates to live posts.");
        const update = await adapter.schedules.get(contentId);
        if (!update) throw new NotFoundError("Nothing is scheduled for this item.");
        return json(200, checked(ScheduledUpdate, update, "scheduled update"));
      },
    },
    {
      method: "DELETE",
      query: true,
      pattern: new RegExp(`^/content/${ID}/schedule$`),
      run: async (m, url) => {
        const contentId = id(m);
        if (!adapter.schedules)
          return fail("not-implemented", "This site does not schedule updates to live posts.");
        return json(
          200,
          checked(
            WriteResult,
            await adapter.schedules.cancel(
              contentId,
              withActor(readQuery(url, ScheduleCancelQuery)),
            ),
            "schedule cancel",
          ),
        );
      },
    },
    {
      method: "POST",
      pattern: new RegExp(`^/content/${ID}/unpublish$`),
      run: (m, _u, r) =>
        write(m, r, async (i, req) =>
          adapter.content.unpublish(i, await readBody(req, UnpublishInput)),
        ),
    },
    {
      method: "GET",
      pattern: new RegExp(`^/content/${ID}/revisions$`),
      run: async (m) => {
        const items = await adapter.content.revisions(id(m));
        if (!items) throw new NotFoundError();
        return json(200, checked(RevisionList, { items }, "revisions"));
      },
    },
    {
      method: "GET",
      pattern: new RegExp(`^/content/${ID}/revisions/${ID}$`),
      run: async (m) => {
        const contentId = id(m);
        const version = pathParam(m[2], Version, "version");
        const source = await adapter.content.revisionSource(contentId, version);
        if (source === null) throw new NotFoundError("No such version.");
        return json(
          200,
          checked(RevisionSource, { id: contentId, version, source }, "revision source"),
        );
      },
    },
    {
      method: "DELETE",
      query: true,
      pattern: new RegExp(`^/content/${ID}$`),
      run: async (m, url) => {
        const contentId = id(m);
        // A site with no delete answers 501 whatever the query says.
        if (!adapter.content.delete)
          return fail("not-implemented", "This site does not delete content through the API.");
        const query = readQuery(url, ContentDeleteQuery);
        await adapter.content.delete(contentId, withActor(query));
        return json(
          200,
          checked(
            ContentDeleteResult,
            { id: contentId, deleted: true, changeId: query.changeId },
            "content delete",
          ),
        );
      },
    },
    {
      method: "PUT",
      pattern: new RegExp(`^/content/${ID}/tags$`),
      run: async (m, _u, request) => {
        const contentId = id(m);
        if (!adapter.content.setTags)
          return fail("not-implemented", "This site does not keep tags on posts through the API.");
        const input = await readBody(request, ContentTagsInput);
        // One spelling per tag: the first one given wins, so "News" and "news" are one tag.
        const seen = new Set<string>();
        const tags = input.tags.filter(
          (t) => !seen.has(t.toLowerCase()) && seen.add(t.toLowerCase()),
        );
        return json(
          200,
          checked(
            WriteResult,
            await adapter.content.setTags(contentId, { ...input, tags }),
            "content tags",
          ),
        );
      },
    },
    {
      method: "POST",
      pattern: new RegExp(`^/content/${ID}/rename$`),
      run: async (m, _u, request) => {
        const contentId = id(m);
        if (!adapter.content.rename)
          return fail("not-implemented", "This site does not rename content through the API.");
        const input = await readBody(request, RenameInput);
        if (input.newId === contentId)
          throw new BadRequest("invalid", "newId is the item's own id.");
        return json(
          200,
          checked(RenameResult, await adapter.content.rename(contentId, input), "content rename"),
        );
      },
    },
    {
      method: "GET",
      pattern: new RegExp(`^/content/${ID}/backlinks$`),
      run: async (m) => {
        const contentId = id(m);
        if (!adapter.content.backlinks)
          return fail("not-implemented", "This site does not list the posts that link to one.");
        if (!(await adapter.content.get(contentId))) throw new NotFoundError();
        return json(
          200,
          checked(BacklinkList, { items: await adapter.content.backlinks(contentId) }, "backlinks"),
        );
      },
    },
    ...(["trash", "restore"] as const).map((op) => ({
      method: "POST",
      pattern: new RegExp(`^/content/${ID}/${op}$`),
      run: async (m: RegExpMatchArray, _u: URL, request: Request) => {
        const contentId = id(m);
        if (!hasContentTrash(adapter))
          return fail("not-implemented", "This site has no content trash.");
        const input = await readBody(request, ContentTrashInput);
        return json(
          200,
          checked(WriteResult, await adapter.content[op]!(contentId, input), `content ${op}`),
        );
      },
    })),
    {
      method: "GET",
      query: true,
      pattern: new RegExp(`^/content/${ID}/diff$`),
      run: async (m, url) => {
        const contentId = id(m);
        const query = readQuery(url, DiffQuery);
        const current = await adapter.content.get(contentId);
        if (!current) throw new NotFoundError();
        const to = query.to ?? current.version;
        const [before, after] = await Promise.all([
          adapter.content.revisionSource(contentId, query.from),
          to === current.version ? current.source : adapter.content.revisionSource(contentId, to),
        ]);
        if (before === null || after === null) throw new NotFoundError("No such version.");
        const patch = createTwoFilesPatch(
          `${contentId}@${query.from}`,
          `${contentId}@${to}`,
          before,
          after,
        );
        return json(200, checked(Diff, { id: contentId, from: query.from, to, patch }, "diff"));
      },
    },
    {
      method: "POST",
      pattern: /^\/preview$/,
      run: async (_m, _u, request) => {
        const html = await adapter.preview.render(await readBody(request, PreviewInput));
        if (typeof html !== "string") throw new ContractBreach("preview: not a string");
        return new Response(html, {
          status: 200,
          // v0.17.0: a preview is never a page to index, whatever the site's own render says.
          headers: {
            ...BASE_HEADERS,
            "content-type": "text/html; charset=utf-8",
            "x-robots-tag": "noindex, nofollow",
          },
        });
      },
    },
  ];
}

src/server/http.ts.source:
// What every route shares: the JSON answers, the body and query readers, the check on what an adapter
// answers, and the contract's name and words for a failure.

import type { z } from "zod";
import { MediaInUseError, NotFoundError, RefusedError, VersionConflictError } from "../adapter.js";
import type { ErrorBody, ErrorCode, MediaUse } from "../contract.js";
import { readCapped } from "@dustinedwards/site-runtime/body";

/** Four million bytes: two million characters of source can take that much as UTF-8 JSON. */
export const MAX_BODY_BYTES = 4_000_000;

const STATUS: Record<ErrorCode, number> = {
  unauthorized: 401,
  "rate-limited": 429,
  "not-configured": 503,
  unavailable: 503,
  "not-found": 404,
  "method-not-allowed": 405,
  invalid: 400,
  "too-large": 413,
  "version-conflict": 409,
  "in-progress": 409,
  "unknown-field": 400,
  refused: 422,
  "not-implemented": 501,
  internal: 500,
};

/** Each code's fixed title (v0.17.0), the `title` of its problem details; the README's Errors table says what each means. */
const TITLE: Record<ErrorCode, string> = {
  unauthorized: "Unauthorized",
  "rate-limited": "Too many requests",
  "not-configured": "Not configured",
  unavailable: "Unavailable",
  "not-found": "Not found",
  "method-not-allowed": "Method not allowed",
  invalid: "Invalid request",
  "too-large": "Too large",
  "version-conflict": "Version conflict",
  "in-progress": "In progress",
  "unknown-field": "Unknown field",
  refused: "Refused",
  "not-implemented": "Not implemented",
  internal: "Internal error",
};

/** Where each code is explained: the README's Errors table, one anchor per code. */
const ERROR_TYPE_BASE = "https://github.com/DrDustinEdwards/site-api/blob/main/README.md#error-";

export const BASE_HEADERS = {
  "cache-control": "no-store",
  "x-content-type-options": "nosniff",
};

export function json(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...BASE_HEADERS, "content-type": "application/json; charset=utf-8" },
  });
}

/**
 * An error answer as RFC 9457 problem details (v0.17.0). `error` and `message` stay as every earlier reader expects;
 * `type`, `title`, `status` and `detail` are the standard's names for the same answer.
 */
export function fail(code: ErrorCode, message: string, extra: Partial<ErrorBody> = {}): Response {
  const status = STATUS[code];
  const body = {
    error: code,
    message,
    type: `${ERROR_TYPE_BASE}${code}`,
    title: TITLE[code],
    status,
    detail: message,
    ...extra,
  };
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...BASE_HEADERS, "content-type": "application/problem+json; charset=utf-8" },
  });
}

export class BadRequest extends Error {
  constructor(
    readonly code: ErrorCode,
    message: string,
    readonly field?: string,
  ) {
    super(message);
  }
}

/**
 * The keys a schema names (v0.22.0): an object's own, or every option's for a union of objects. null when the schema is
 * not an object, so nothing is refused for it.
 */
function knownKeys(schema: z.ZodType): Set<string> | null {
  const def = (
    schema as unknown as {
      def?: {
        type?: string;
        shape?: Record<string, unknown>;
        options?: z.ZodType[];
        innerType?: z.ZodType;
        in?: z.ZodType;
      };
    }
  ).def;
  if (!def) return null;
  if (def.type === "object" && def.shape) return new Set(Object.keys(def.shape));
  if (def.type === "union" && def.options) {
    const keys = new Set<string>();
    for (const option of def.options) {
      const own = knownKeys(option);
      if (!own) return null;
      for (const k of own) keys.add(k);
    }
    return keys;
  }
  const inner = def.innerType ?? def.in;
  return inner ? knownKeys(inner) : null;
}

/**
 * v0.22.0: a body or query key the contract does not name is refused, never dropped, so a caller that misspells a field
 * or sends one the site's version does not know hears so (400 unknown-field, naming it) instead of a 200 that ignored it.
 */
function refuseUnknown(schema: z.ZodType, value: unknown, where: "body" | "query"): void {
  if (!value || typeof value !== "object" || Array.isArray(value)) return;
  const known = knownKeys(schema);
  if (!known) return;
  const unknown = Object.keys(value).find((k) => !known.has(k));
  if (unknown !== undefined)
    throw new BadRequest(
      "unknown-field",
      `The ${where} has a field the contract does not name: ${unknown}.`,
      unknown,
    );
}

/** A route that takes no query refuses any key in one (v0.22.0). */
export function refuseAnyQuery(url: URL): void {
  const first = [...url.searchParams.keys()][0];
  if (first !== undefined)
    throw new BadRequest(
      "unknown-field",
      `This route takes no query, so ${first} is not a field it names.`,
      first,
    );
}

export async function readBody<T extends z.ZodType>(
  request: Request,
  schema: T,
): Promise<z.infer<T>> {
  const declared = Number(request.headers.get("content-length") ?? "0");
  if (declared > MAX_BODY_BYTES) throw new BadRequest("too-large", "The body is too large.");
  // Counted as it arrives (site-runtime's one reader), so an understated or missing Content-Length cannot make the
  // Worker hold more than the limit; request.text() read the whole body first.
  const text = await readCapped(request, MAX_BODY_BYTES);
  if (text === null) throw new BadRequest("too-large", "The body is too large.");
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    throw new BadRequest("invalid", "The body is not JSON.");
  }
  refuseUnknown(schema, raw, "body");
  const parsed = schema.safeParse(raw);
  if (!parsed.success) throw new BadRequest("invalid", describe(parsed.error));
  return parsed.data;
}

export function readQuery<T extends z.ZodType>(url: URL, schema: T): z.infer<T> {
  const raw = Object.fromEntries(url.searchParams);
  refuseUnknown(schema, raw, "query");
  const parsed = schema.safeParse(raw);
  if (!parsed.success) throw new BadRequest("invalid", describe(parsed.error));
  return parsed.data;
}

function describe(error: z.ZodError): string {
  return error.issues
    .slice(0, 5)
    .map((issue) => `${issue.path.join(".") || "body"}: ${issue.message}`)
    .join("; ");
}

/** An adapter that answers outside the contract is a site bug, reported as one and never passed on. */
export class ContractBreach extends Error {}

export function checked<T extends z.ZodType>(schema: T, value: unknown, what: string): z.infer<T> {
  const parsed = schema.safeParse(value);
  if (!parsed.success) throw new ContractBreach(`${what}: ${describe(parsed.error)}`);
  return parsed.data;
}

/**
 * One route. `query` (v0.22.0) is true for a route that reads its query through readQuery, which refuses an unknown key
 * itself; on any other route, the handler refuses a query with any key before the route runs.
 */
export type Route = {
  method: string;
  pattern: RegExp;
  query?: boolean;
  run: (m: RegExpMatchArray, url: URL, request: Request) => Promise<Response>;
};

export const ID = "([^/]+)";

/** A path segment decoded and checked against its shape; what is refused names the thing it should have been. */
export function pathParam(raw: string | undefined, shape: z.ZodType, what: string): string {
  let value: string;
  try {
    value = decodeURIComponent(raw!);
  } catch {
    throw new BadRequest("invalid", `The ${what} is not valid.`);
  }
  if (!shape.safeParse(value).success) throw new BadRequest("invalid", `The ${what} is not valid.`);
  return value;
}

export type Log = (entry: Record<string, unknown>) => void;

export interface Failure {
  code: ErrorCode;
  message: string;
  currentVersion?: string | null;
  usedBy?: MediaUse[];
  field?: string;
}

/** The contract's name and words for a failure, for the single routes and for one file of a bulk. */
export function describeFailure(error: unknown, log: Log): Failure {
  if (error instanceof BadRequest)
    return {
      code: error.code,
      message: error.message,
      ...(error.field !== undefined ? { field: error.field } : {}),
    };
  if (error instanceof VersionConflictError)
    return {
      code: "version-conflict",
      message: error.message,
      currentVersion: error.currentVersion,
    };
  if (error instanceof NotFoundError) return { code: "not-found", message: error.message };
  if (error instanceof MediaInUseError)
    return { code: "refused", message: error.message, usedBy: error.usedBy };
  if (error instanceof RefusedError) return { code: "refused", message: error.message };
  if (error instanceof ContractBreach) {
    log({ siteApi: "contract-breach", detail: error.message });
    return { code: "internal", message: "The site answered outside the contract." };
  }
  log({ siteApi: "adapter-failed", error: error instanceof Error ? error.message : String(error) });
  return { code: "internal", message: "The site failed to answer." };
}

