// The media routes (v0.2.0, writes v0.4.0, focal point, caption and replace v0.10.0, the media library's ideas
// v0.13.0), mounted only when the site's adapter has media.

import { focusOf } from "@dustinedwards/site-runtime/image";
import type { MediaSuggestion } from "../media-kit.js";

import {
  MediaInUseError,
  NotFoundError,
  RefusedError,
  VersionConflictError,
  type MediaAdapter,
} from "../adapter.js";
import {
  MAX_TRASH_EMPTY,
  MediaAltInput,
  MediaBulkInput,
  MediaBulkResult,
  MediaCaptionInput,
  MediaCreditInput,
  MediaDeleteQuery,
  MediaDeleteResult,
  MediaDetail,
  MediaFileSuggestQuery,
  MediaFileSuggestions,
  MediaFocusInput,
  MediaHistory,
  MediaId,
  MediaImportInput,
  MediaList,
  MediaListQuery,
  MediaReplaceQuery,
  MediaReplaceResult,
  MediaResizePassInput,
  MediaResizePassResult,
  MediaRevertInput,
  MediaSuggestions,
  MediaTag,
  MediaTagsInput,
  MediaTransformInput,
  MediaTransformResult,
  MediaTrashEmptyInput,
  MediaTrashEmptyResult,
  MediaTrashInput,
  MediaUploadQuery,
  MediaUploadResult,
  MediaWriteResult,
  type MediaBulkOutcome,
  type MediaDetail as MediaDetailType,
  type MediaResizeOutcome,
  type MediaUse,
} from "../contract.js";
import {
  altRefusal,
  checkUpload,
  essence,
  fetchImport,
  kindOf,
  readUpload,
  turnsSize,
} from "../media.js";
import { addressRefusal, OutboundRefusal } from "../outbound.js";
import { duplicateKey, stripMetadata } from "../media-upload.js";
import type { SiteApiStore } from "../store.js";
import {
  BadRequest,
  ContractBreach,
  ID,
  checked,
  describeFailure,
  fail,
  json,
  pathParam,
  readBody,
  readQuery,
  type Log,
  type Route,
} from "./http.js";

/** How many trashed files one page of the empty-trash gather asks the site for. */
const TRASH_PAGE = 200;

export function mediaRoutes(
  media: MediaAdapter,
  log: Log,
  siteStore?: Pick<SiteApiStore, "uploadedMedia" | "putUploadedMedia">,
): Route[] {
  const mediaId = (m: RegExpMatchArray) => pathParam(m[1], MediaId, "media id");

  return [
    {
      method: "GET",
      query: true,
      pattern: /^\/media$/,
      run: async (_m, url) => {
        const query = readQuery(url, MediaListQuery);
        if (query.changedSince !== undefined)
          return changesSince(query.changedSince, query.limit, url);
        if (query.lens && !(media.lenses ?? []).includes(query.lens))
          return fail("not-implemented", `This site does not offer the ${query.lens} lens.`);
        if (query.sort === "used" && !media.usage)
          return fail("not-implemented", "This site does not count where its files are used.");
        if ((query.orientation || query.kind) && !media.filters)
          return fail("not-implemented", "This site does not filter files by orientation or kind.");
        const list = checked(MediaList, await media.list(query), "media list");
        // The first page is where a screen learns the point to poll from.
        if (media.changes && list.changeCursor === undefined)
          throw new ContractBreach(
            "media list: a site that answers changes gives changeCursor on every list",
          );
        return json(200, list);
      },
    },
    {
      method: "POST",
      query: true,
      pattern: /^\/media$/,
      run: async (_m, url, request) => {
        const query = readQuery(url, MediaUploadQuery);
        const contentType = essence(request.headers.get("content-type"));
        // The type first, so a file the site does not accept is never read at all; then the alt, before a byte is read.
        const wrongType = checkUpload(contentType, null, media.limits);
        if (wrongType) throw new BadRequest(wrongType.code, wrongType.message);
        const decorative = query.decorative === "yes";
        checkAlt(query.alt, decorative, query.filename, false);
        return store(await uploaded(request, contentType), contentType, {
          ...query,
          alt: decorative ? "" : (query.alt ?? "").trim(),
          decorative,
        });
      },
    },
    // v0.19.0: the model's alt text and tags for a file not yet stored, for the upload form to offer. Nothing is stored.
    {
      method: "POST",
      pattern: /^\/media\/suggestions$/,
      query: true,
      run: async (_m, url, request) => {
        if (!media.suggestFile)
          return fail("not-implemented", "This site does not suggest alt text before an upload.");
        const { url: address } = readQuery(url, MediaFileSuggestQuery);
        if (address && !media.importFetch)
          return fail("not-implemented", "This site does not import files from the web.");
        const file = address
          ? await imported(address)
          : { contentType: essence(request.headers.get("content-type")), bytes: null };
        const wrongType = checkUpload(file.contentType, null, media.limits);
        if (wrongType) throw new BadRequest(wrongType.code, wrongType.message);
        if (kindOf(file.contentType) !== "image")
          throw new BadRequest("invalid", "Only a picture has alt text to suggest.");
        const bytes = file.bytes ?? (await uploaded(request, file.contentType));
        const found = await media.suggestFile({ bytes, contentType: file.contentType });
        return json(
          200,
          checked(MediaFileSuggestions, suggestionOf(found), "media file suggestions"),
        );
      },
    },
    // v0.13.0: the site's own copy of a file on the web, checked as an upload is.
    {
      method: "POST",
      pattern: /^\/media\/import$/,
      run: async (_m, _u, request) => {
        if (!media.importFetch)
          return fail("not-implemented", "This site does not import files from the web.");
        const input = await readBody(request, MediaImportInput);
        const decorative = input.decorative === true;
        checkAlt(input.alt, decorative, input.filename ?? nameOf(input.url), false);
        const { bytes, contentType, address } = await imported(input.url);
        return store(
          bytes,
          contentType,
          {
            ...input,
            filename: input.filename ?? nameOf(address),
            alt: decorative ? "" : (input.alt ?? "").trim(),
            decorative,
          },
          input.url,
        );
      },
    },
    {
      method: "GET",
      pattern: new RegExp(`^/media/${ID}$`),
      run: async (m) => {
        const item = await media.get(mediaId(m));
        if (!item) throw new NotFoundError("No such media.");
        return json(200, checked(MediaDetail, item, "media"));
      },
    },
    {
      method: "DELETE",
      query: true,
      pattern: new RegExp(`^/media/${ID}$`),
      run: async (m, url) => {
        const id = mediaId(m);
        const { changeId } = readQuery(url, MediaDeleteQuery);
        await media.delete(id, { changeId });
        return json(
          200,
          checked(MediaDeleteResult, { id, deleted: true, changeId }, "media delete"),
        );
      },
    },
    // v0.4.0 writes. A site whose adapter lacks the method answers 501 whatever the body says.
    {
      method: "PUT",
      pattern: new RegExp(`^/media/${ID}/alt$`),
      run: async (m, _u, request) => {
        const id = mediaId(m);
        if (!media.setAlt)
          return fail("not-implemented", "This site does not edit alt text through the API.");
        const input = await readBody(request, MediaAltInput);
        const decorative = input.decorative === true;
        // An alt that may be the file's own name is checked against it; a decorative choice needs no read.
        checkAlt(
          input.alt,
          decorative,
          decorative ? null : ((await media.get(id))?.filename ?? null),
        );
        const result = await media.setAlt(id, { ...input, alt: input.alt.trim(), decorative });
        return json(
          200,
          checked(
            MediaWriteResult,
            { id, version: result.version, changeId: input.changeId },
            "media alt",
          ),
        );
      },
    },
    {
      method: "PUT",
      pattern: new RegExp(`^/media/${ID}/tags$`),
      run: async (m, _u, request) => {
        const id = mediaId(m);
        if (!media.setTags) return fail("not-implemented", "This site does not keep media tags.");
        const input = await readBody(request, MediaTagsInput);
        const result = await media.setTags(id, { ...input, tags: [...new Set(input.tags)].sort() });
        return json(
          200,
          checked(
            MediaWriteResult,
            { id, version: result.version, changeId: input.changeId },
            "media tags",
          ),
        );
      },
    },
    // v0.10.0, each 501 where the adapter lacks it.
    {
      method: "PUT",
      pattern: new RegExp(`^/media/${ID}/focus$`),
      run: async (m, _u, request) => {
        const id = mediaId(m);
        if (!media.setFocus)
          return fail("not-implemented", "This site does not keep a focal point on files.");
        const input = await readBody(request, MediaFocusInput);
        // In the one spelling site-runtime's ./image writes into a crop's URL, so the stored point and the URL agree.
        const focus = input.focus === null ? null : focusOf(input.focus);
        const result = await media.setFocus(id, { ...input, focus });
        return json(
          200,
          checked(
            MediaWriteResult,
            { id, version: result.version, changeId: input.changeId },
            "media focus",
          ),
        );
      },
    },
    {
      method: "PUT",
      pattern: new RegExp(`^/media/${ID}/caption$`),
      run: async (m, _u, request) => {
        const id = mediaId(m);
        if (!media.setCaption)
          return fail("not-implemented", "This site does not keep captions on files.");
        const input = await readBody(request, MediaCaptionInput);
        const result = await media.setCaption(id, input);
        return json(
          200,
          checked(
            MediaWriteResult,
            { id, version: result.version, changeId: input.changeId },
            "media caption",
          ),
        );
      },
    },
    {
      method: "PUT",
      query: true,
      pattern: new RegExp(`^/media/${ID}/file$`),
      run: async (m, url, request) => {
        const id = mediaId(m);
        if (!media.replace) return fail("not-implemented", "This site does not replace files.");
        const query = readQuery(url, MediaReplaceQuery);
        const contentType = essence(request.headers.get("content-type"));
        // As an upload: a type the site does not accept is refused unread.
        const wrongType = checkUpload(contentType, null, media.limits);
        if (wrongType) throw new BadRequest(wrongType.code, wrongType.message);
        const current = await held(id, query.expectedVersion, "replaced");
        // The address names the type (photo.png), so a file of another type would be served under a name that lies.
        if (essence(current.contentType) !== contentType) {
          throw new BadRequest(
            "invalid",
            `This file is ${current.contentType}, and the replacement is ${contentType}. A replacement keeps the address, so it must be the same type; upload it as a new file instead.`,
          );
        }
        const read = await readUpload(request, media.limits);
        if (!read.ok) throw new BadRequest(read.refusal.code, read.refusal.message);
        const wrongBytes = checkUpload(contentType, read.bytes, media.limits);
        if (wrongBytes) throw new BadRequest(wrongBytes.code, wrongBytes.message);
        const { item, sizesNeedPurge } = await media.replace(id, {
          // A replacement's private metadata goes before the site sees it, as an upload's does in prepareUpload (v0.19.0).
          bytes: stripMetadata(read.bytes, contentType),
          contentType,
          filename: query.filename,
          expectedVersion: query.expectedVersion,
          changeId: query.changeId,
        });
        // Every page that uses the file links this id and address; a site that moved either broke them.
        if (item.id !== id || item.url !== current.url)
          throw new ContractBreach(
            `replace moved ${id} to ${item.id} at ${item.url}; a replace keeps the id and the address`,
          );
        return json(
          200,
          checked(
            MediaReplaceResult,
            { ...item, changeId: query.changeId, sizesNeedPurge },
            "media replace",
          ),
        );
      },
    },
    // v0.13.0, each 501 where the adapter lacks it.
    {
      method: "PUT",
      pattern: new RegExp(`^/media/${ID}/credit$`),
      run: async (m, _u, request) => {
        const id = mediaId(m);
        if (!media.setCredit)
          return fail("not-implemented", "This site does not keep credit and license on files.");
        const input = await readBody(request, MediaCreditInput);
        const result = await media.setCredit(id, {
          ...input,
          credit: input.credit.trim(),
          license: input.license.trim(),
          ...(input.copyright !== undefined ? { copyright: input.copyright.trim() } : {}),
        });
        return json(
          200,
          checked(
            MediaWriteResult,
            { id, version: result.version, changeId: input.changeId },
            "media credit",
          ),
        );
      },
    },
    {
      method: "POST",
      pattern: new RegExp(`^/media/${ID}/transform$`),
      run: async (m, _u, request) => {
        const id = mediaId(m);
        if (!media.transform)
          return fail("not-implemented", "This site does not turn or mirror pictures.");
        const input = await readBody(request, MediaTransformInput);
        const current = await held(id, input.expectedVersion, "turned");
        if (kindOf(current.contentType) !== "image")
          throw new RefusedError("Only a picture turns or mirrors.");
        // A quarter turn swaps the width and height. Where the site's addresses carry the size, that is a new file, and the
        // pages that use the old one keep it; a square picture keeps its size and turns in place.
        const square = current.width !== null && current.width === current.height;
        const asNewFile = Boolean(media.replaceKeepsSize) && turnsSize(input.op) && !square;
        const { item, sizesNeedPurge } = await media.transform(id, { ...input, asNewFile });
        if (asNewFile ? item.id === id : item.id !== id || item.url !== current.url) {
          throw new ContractBreach(
            `transform of ${id} answered ${item.id} at ${item.url}; ${asNewFile ? "a new file has a new id" : "in place keeps the id and the address"}`,
          );
        }
        return json(
          200,
          checked(
            MediaTransformResult,
            { ...item, changeId: input.changeId, sizesNeedPurge, asNewFile },
            "media transform",
          ),
        );
      },
    },
    {
      method: "GET",
      pattern: new RegExp(`^/media/${ID}/history$`),
      run: async (m) => {
        const id = mediaId(m);
        if (!media.history || !media.revert)
          return fail("not-implemented", "This site does not keep a file's earlier versions.");
        const revisions = await media.history(id);
        if (!revisions) throw new NotFoundError("No such media.");
        return json(200, checked(MediaHistory, { id, revisions }, "media history"));
      },
    },
    {
      method: "POST",
      pattern: new RegExp(`^/media/${ID}/revert$`),
      run: async (m, _u, request) => {
        const id = mediaId(m);
        if (!media.history || !media.revert)
          return fail("not-implemented", "This site does not keep a file's earlier versions.");
        const input = await readBody(request, MediaRevertInput);
        const current = await held(id, input.expectedVersion, "reverted");
        const target = (await media.history(id))?.find((r) => r.rev === input.to);
        if (!target) throw new NotFoundError("This file has no such earlier version.");
        if (target.current) throw new RefusedError("Those are already the file's bytes.");
        if (
          media.replaceKeepsSize &&
          (target.width !== current.width || target.height !== current.height)
        ) {
          throw new RefusedError(
            "That version is another size, and this site's addresses carry the size. Download it and upload it as a new file instead.",
          );
        }
        const { item, sizesNeedPurge } = await media.revert(id, input);
        if (item.id !== id || item.url !== current.url)
          throw new ContractBreach(
            `revert moved ${id} to ${item.id} at ${item.url}; a revert keeps the id and the address`,
          );
        return json(
          200,
          checked(
            MediaTransformResult,
            { ...item, changeId: input.changeId, sizesNeedPurge, asNewFile: false },
            "media revert",
          ),
        );
      },
    },
    {
      method: "GET",
      pattern: new RegExp(`^/media/${ID}/suggestions$`),
      run: async (m) => {
        const id = mediaId(m);
        if (!media.suggest)
          return fail("not-implemented", "This site does not suggest tags or alt text.");
        const found = await media.suggest(id);
        if (!found) throw new NotFoundError("No such media.");
        return json(
          200,
          checked(MediaSuggestions, { id, ...suggestionOf(found) }, "media suggestions"),
        );
      },
    },
    {
      method: "POST",
      pattern: /^\/media\/resize-pass$/,
      run: async (_m, _u, request) => {
        if (!media.resize || !media.shrink)
          return fail("not-implemented", "This site does not shrink stored pictures.");
        const input = await readBody(request, MediaResizePassInput);
        const results: MediaResizeOutcome[] = [];
        // One at a time, like bulk: image work is slow, and one file's refusal is that file's outcome alone.
        for (const { id, expectedVersion, changeId } of input.items) {
          try {
            // v0.22.0: where a replace keeps the size, pages hold each picture's width and height, so a shrink may only make
            // the picture smaller in the same proportions (the boxes those pages drew still fit it). A site whose addresses
            // carry the size leaves `shrink` out altogether.
            const before = media.replaceKeepsSize
              ? await held(id, expectedVersion, "shrunk")
              : null;
            const { resized, item } = await media.shrink(id, { expectedVersion, changeId });
            if (item.id !== id) throw new ContractBreach(`shrink moved ${id} to ${item.id}`);
            if (before && resized && !keepsProportions(before, item)) {
              throw new ContractBreach(
                `shrink of ${id} went from ${before.width}x${before.height} to ${item.width}x${item.height}; on a site whose replace keeps the size a shrink only makes a picture smaller, in the same proportions`,
              );
            }
            results.push({
              ok: true,
              id,
              changeId,
              resized,
              ...(item.version ? { version: item.version } : {}),
              width: item.width,
              height: item.height,
              bytes: item.bytes,
            });
          } catch (error) {
            results.push({ ...failedOutcome(error, log), id, changeId });
          }
        }
        return json(200, checked(MediaResizePassResult, { results }, "media resize pass"));
      },
    },
    {
      method: "POST",
      pattern: new RegExp(`^/media/${ID}/trash$`),
      run: async (m, _u, request) => {
        const id = mediaId(m);
        if (!media.trash || !media.restore)
          return fail("not-implemented", "This site has no media trash.");
        const input = await readBody(request, MediaTrashInput);
        const result = await media.trash(id, input);
        return json(
          200,
          checked(
            MediaWriteResult,
            { id, version: result.version, changeId: input.changeId },
            "media trash",
          ),
        );
      },
    },
    {
      method: "POST",
      pattern: new RegExp(`^/media/${ID}/restore$`),
      run: async (m, _u, request) => {
        const id = mediaId(m);
        if (!media.trash || !media.restore)
          return fail("not-implemented", "This site has no media trash.");
        const input = await readBody(request, MediaTrashInput);
        const result = await media.restore(id, input);
        return json(
          200,
          checked(
            MediaWriteResult,
            { id, version: result.version, changeId: input.changeId },
            "media restore",
          ),
        );
      },
    },
    {
      method: "POST",
      pattern: /^\/media\/trash\/empty$/,
      run: async (_m, _u, request) => {
        if (!media.trash || !media.restore)
          return fail("not-implemented", "This site has no media trash.");
        const input = await readBody(request, MediaTrashEmptyInput);
        // Gather first, then delete: a cursor into a list that is shrinking would skip files.
        const ids: string[] = [];
        let cursor: string | undefined;
        do {
          const page = await media.list({
            trashed: "only",
            limit: TRASH_PAGE,
            ...(cursor ? { cursor } : {}),
          });
          for (const item of page.items) if (item.trashedAt) ids.push(item.id);
          cursor = page.nextCursor ?? undefined;
        } while (cursor && ids.length <= MAX_TRASH_EMPTY);
        let more = ids.length > MAX_TRASH_EMPTY;
        const deleted: string[] = [];
        const refused: Array<{ id: string; message: string; usedBy?: MediaUse[] }> = [];
        for (const [n, id] of ids.slice(0, MAX_TRASH_EMPTY).entries()) {
          try {
            await media.delete(id, { changeId: `${input.changeId}-${n + 1}` });
            deleted.push(id);
          } catch (error) {
            const failure = describeFailure(error, log);
            if (failure.code !== "refused" && failure.code !== "not-found") {
              // Nothing gone yet: fail as before. Otherwise stop here and say what is already gone, so a retry
              // knows where it stands.
              if (deleted.length === 0) throw error;
              refused.push({ id, message: failure.message });
              more = true;
              break;
            }
            refused.push({
              id,
              message: failure.message,
              ...(failure.usedBy ? { usedBy: failure.usedBy } : {}),
            });
          }
        }
        return json(
          200,
          checked(
            MediaTrashEmptyResult,
            { changeId: input.changeId, deleted, refused, more },
            "media trash empty",
          ),
        );
      },
    },
    {
      method: "POST",
      pattern: /^\/media\/bulk$/,
      run: async (_m, _u, request) => {
        const input = await readBody(request, MediaBulkInput);
        const lacking = bulkLacking(media, input.op);
        if (lacking) return fail("not-implemented", lacking);
        if (
          (input.op === "add-tags" || input.op === "remove-tags") &&
          (!input.tags || input.tags.length === 0)
        ) {
          throw new BadRequest("invalid", "tags: name at least one tag.");
        }
        const results: MediaBulkOutcome[] = [];
        // One at a time, in order: a site's index and cache purge are not built for a burst, and one
        // file's refusal (a stale version, a file in use) is that file's outcome and nothing more.
        for (const item of input.items) {
          results.push(await bulkOne(media, input.op, input.tags ?? [], item, log));
        }
        return json(200, checked(MediaBulkResult, { op: input.op, results }, "media bulk"));
      },
    },
  ];

  /** An upload's body, read up to the site's limit and checked against its declared type. */
  async function uploaded(
    request: Parameters<typeof readUpload>[0],
    contentType: string,
  ): Promise<Uint8Array> {
    const read = await readUpload(request, media.limits);
    if (!read.ok) throw new BadRequest(read.refusal.code, read.refusal.message);
    const wrongBytes = checkUpload(contentType, read.bytes, media.limits);
    if (wrongBytes) throw new BadRequest(wrongBytes.code, wrongBytes.message);
    return read.bytes;
  }

  /** A file on the web, fetched through the site's importFetch and checked as an upload is. */
  async function imported(
    url: string,
  ): Promise<{ bytes: Uint8Array; contentType: string; address: string }> {
    // The address alone first (no fetch, no DNS), so an http or a private address is a 400 before anything is asked.
    const refusal = addressRefusal(url);
    if (refusal) throw new BadRequest("invalid", refusal);
    let response: Response;
    let address: string;
    try {
      ({ response, address } = await fetchImport(media.importFetch!, url));
    } catch (error) {
      if (error instanceof OutboundRefusal) throw new RefusedError(error.message);
      throw error;
    }
    const contentType = essence(response.headers.get("content-type"));
    const wrongType = checkUpload(contentType, null, media.limits);
    if (wrongType) {
      await response.body?.cancel().catch(() => {});
      throw new BadRequest(wrongType.code, wrongType.message);
    }
    return { bytes: await uploaded(response, contentType), contentType, address };
  }

  /** The file at the version the caller saw, and one the site lets this API change: the checks before a write to its bytes. */
  async function held(id: string, expectedVersion: string, done: string): Promise<MediaDetailType> {
    const current = await media.get(id);
    if (!current) throw new NotFoundError("No such media.");
    if (current.version !== expectedVersion)
      throw new VersionConflictError(
        current.version ?? null,
        "The file changed since it was loaded.",
      );
    if (!current.deletable)
      throw new RefusedError(
        `This file is one of the site's own, so it is never ${done} through this API.`,
      );
    return current;
  }

  /**
   * Stores checked bytes (an upload or an import): the file already holding them where the site finds duplicates, so the
   * site never stores the same bytes twice, else the site's new file. The key is duplicateKey's (v0.21.0): the bytes as
   * sent without their private metadata, which is what a site stores unless it converts or shrinks the picture. For a
   * file it converted or shrank, the store remembers which file each key became, since the site's own hashes are of other
   * bytes.
   */
  async function store(
    bytes: Uint8Array,
    contentType: string,
    fields: {
      filename: string;
      alt: string;
      decorative: boolean;
      changeId: string;
      resize?: "no" | undefined;
    },
    sourceUrl?: string,
  ): Promise<Response> {
    const sha256 = await duplicateKey(bytes, contentType);
    if (media.findByHash) {
      const twin = (await media.findByHash(sha256)) ?? (await sentBefore(sha256));
      if (twin)
        return json(
          200,
          checked(MediaUploadResult, { ...twin, duplicateOf: twin.id }, "media duplicate"),
        );
    }
    const uploaded = await media.upload({
      bytes,
      contentType,
      filename: fields.filename,
      alt: fields.alt,
      ...(fields.decorative ? { decorative: true } : {}),
      changeId: fields.changeId,
      sha256,
      resize: media.resize !== undefined && fields.resize !== "no",
      ...(sourceUrl ? { sourceUrl } : {}),
    });
    // An import is served from the site's own storage: an address back at the source would be a hotlink.
    if (sourceUrl && (uploaded.url === sourceUrl || uploaded.downloadUrl === sourceUrl))
      throw new ContractBreach(`import of ${sourceUrl} is served from its source`);
    const answer = checked(MediaUploadResult, uploaded, "uploaded media");
    // The file is stored either way: a store that fails (a site that has not applied SITE_API_STORE_SQL_V0_21) loses only
    // this key, as the package's other bookkeeping does, and says so in the log.
    if (media.findByHash && siteStore) {
      await siteStore
        .putUploadedMedia(sha256, answer.id, new Date().toISOString())
        .catch((error: unknown) =>
          log({ siteApi: "media-uploads-store-failed", error: String(error) }),
        );
    }
    return json(201, answer);
  }

  /** The file an earlier upload with this key became, where the site still holds it (trashed or not); else null. */
  async function sentBefore(sha256: string) {
    const id = siteStore
      ? await siteStore
          .uploadedMedia(sha256)
          .catch(
            (error: unknown) => (
              log({ siteApi: "media-uploads-store-failed", error: String(error) }),
              null
            ),
          )
      : null;
    const found = id ? await media.get(id) : null;
    if (!found) return null;
    const { usedBy: _usedBy, twins: _twins, ...item } = found;
    return item;
  }

  /** The files changed since a cursor: a poll takes no other filter, so it never misses a file another filter would hide. */
  async function changesSince(since: string, limit: number, url: URL): Promise<Response> {
    if (!media.changes)
      return fail("not-implemented", "This site does not say what changed since.");
    const other = [...url.searchParams.keys()].filter((k) => k !== "changedSince" && k !== "limit");
    if (other.length > 0)
      throw new BadRequest(
        "invalid",
        `changedSince takes only limit, not ${[...new Set(other)].join(", ")}.`,
      );
    const found = await media.changes({ since, limit });
    if (found.items.length + found.removed.length > limit)
      throw new ContractBreach(
        `media changes: ${found.items.length + found.removed.length} answered for a limit of ${limit}`,
      );
    return json(
      200,
      checked(
        MediaList,
        {
          items: found.items,
          nextCursor: null,
          changeCursor: found.cursor,
          removed: found.removed,
          moreChanges: found.more,
        },
        "media changes",
      ),
    );
  }
}

/** Refuses, as 400 before anything is read or stored, an alt the contract does not take (altRefusal); an upload or import may carry none (v0.30.0). */
function checkAlt(
  alt: string | undefined,
  decorative: boolean,
  filename: string | null,
  required = true,
): void {
  const refusal = altRefusal(alt, decorative, filename, required);
  if (refusal) throw new BadRequest("invalid", `alt: ${refusal}`);
}

/** A model's words, in the contract's spelling: what cannot be a tag is dropped, never passed on, and a blank alt is none. */
function suggestionOf(found: MediaSuggestion): {
  tags: string[];
  alt: string | null;
  model: string;
  usage?: MediaSuggestion["usage"];
} {
  const tags = [
    ...new Set(
      found.tags.map((t) =>
        t
          .trim()
          .toLowerCase()
          .replace(/[\s_]+/g, "-"),
      ),
    ),
  ]
    .filter((t) => MediaTag.safeParse(t).success)
    .slice(0, 12);
  return {
    tags,
    alt: found.alt?.trim() ? found.alt.trim().slice(0, 2000) : null,
    model: found.model,
    ...(found.usage ? { usage: found.usage } : {}),
  };
}

/** The name an import keeps when it names none: the address's last segment, made a plain file name. */
function nameOf(address: string): string {
  const last = new URL(address).pathname.split("/").filter(Boolean).pop() ?? "";
  let name: string;
  try {
    name = decodeURIComponent(last);
  } catch {
    name = last;
  }
  // A file name may not hold control characters or a path, on purpose.
  const plain = name
    // oxlint-disable-next-line no-control-regex
    .replace(/[/\\\u0000-\u001f]+/g, "-")
    .trim()
    .slice(0, 200);
  return plain || "import";
}

/** One file's failure as a per-file outcome's error, in the words describeFailure gives it. */
function failedOutcome(
  error: unknown,
  log: Log,
): Omit<Extract<MediaResizeOutcome, { ok: false }>, "id" | "changeId"> {
  const failure = describeFailure(error, log);
  const code =
    (["not-found", "version-conflict", "refused", "invalid"] as const).find(
      (c) => c === failure.code,
    ) ?? "internal";
  return {
    ok: false as const,
    error: code,
    message: failure.message,
    ...(failure.currentVersion !== undefined ? { currentVersion: failure.currentVersion } : {}),
  };
}

/** What a bulk op needs that the adapter lacks, as the 501 message, else null. */
function bulkLacking(m: MediaAdapter, op: MediaBulkInput["op"]): string | null {
  if ((op === "trash" || op === "restore") && !(m.trash && m.restore))
    return "This site has no media trash.";
  if ((op === "add-tags" || op === "remove-tags") && !m.setTags)
    return "This site does not keep media tags.";
  return null;
}

/** One file's bulk outcome. Every failure is caught here, so no file's failure stops the next. */
async function bulkOne(
  m: MediaAdapter,
  op: MediaBulkInput["op"],
  tags: string[],
  item: MediaBulkInput["items"][number],
  log: Log,
): Promise<MediaBulkOutcome> {
  const { id, changeId } = item;
  try {
    if (op === "delete") {
      await m.delete(id, { changeId });
      return { ok: true, id, changeId };
    }
    const expectedVersion = item.expectedVersion;
    if (!expectedVersion)
      throw new BadRequest(
        "invalid",
        `expectedVersion: ${op} needs the version the caller last saw.`,
      );
    if (op === "trash" || op === "restore") {
      const result = await (op === "trash"
        ? m.trash!(id, { expectedVersion, changeId })
        : m.restore!(id, { expectedVersion, changeId }));
      return {
        ok: true,
        id,
        changeId,
        version: checked(MediaWriteResult, { id, version: result.version, changeId }, `media ${op}`)
          .version,
      };
    }
    // Tags: the new set is worked out from what the site holds now, and refused if that is not the
    // version the caller saw. The adapter checks again on the write, which closes the gap.
    const current = await m.get(id);
    if (!current) throw new NotFoundError("No such media.");
    if (current.version !== expectedVersion)
      throw new VersionConflictError(current.version ?? null);
    const held = new Set(current.tags ?? []);
    for (const tag of tags) {
      if (op === "add-tags") held.add(tag);
      else held.delete(tag);
    }
    const next = [...held].sort();
    if (!MediaTagsInput.shape.tags.safeParse(next).success)
      throw new RefusedError("A file carries at most 12 tags.");
    const result = await m.setTags!(id, { tags: next, expectedVersion, changeId });
    return {
      ok: true,
      id,
      changeId,
      version: checked(MediaWriteResult, { id, version: result.version, changeId }, "media tags")
        .version,
    };
  } catch (error) {
    const usedBy = error instanceof MediaInUseError ? error.usedBy : undefined;
    return { ...failedOutcome(error, log), id, changeId, ...(usedBy ? { usedBy } : {}) };
  }
}

/** True when `after` is no larger than `before` on either edge and has its proportions, to the pixel a rounding moves. */
function keepsProportions(
  before: { width: number | null; height: number | null },
  after: { width: number | null; height: number | null },
): boolean {
  const [w0, h0, w1, h1] = [before.width, before.height, after.width, after.height];
  if (w0 === null || h0 === null || w1 === null || h1 === null) return false;
  return w1 <= w0 && h1 <= h0 && Math.abs(w1 * h0 - h1 * w0) <= Math.max(w0, h0);
}

src/server/preview-links.ts.source:
// Shareable preview links (v0.17.0), on a site that gives the package a store. Carrel makes one for an item under the
// key; anyone holding its address sees the item's current source rendered, with no key, until it expires or is revoked.
// The site keeps only the SHA-256 of each token, so its store cannot open a link.

import { base64url } from "@dustinedwards/site-runtime/encoding";
import { NotFoundError, type SiteAdapter } from "../adapter.js";
import {
  PREVIEW_LINK_DEFAULT_HOURS,
  PreviewLink,
  PreviewLinkInput,
  PreviewLinkList,
  PreviewLinkListQuery,
  PreviewLinkRevokeQuery,
  PreviewLinkRevokeResult,
} from "../contract.js";
import { sha256Hex } from "@dustinedwards/site-runtime/encoding";
import type { SiteApiStore } from "../store.js";
import {
  BadRequest,
  ContractBreach,
  checked,
  json,
  readBody,
  readQuery,
  type Route,
} from "./http.js";

/** Where a site serves its preview links, outside the API's prefix: `GET {origin}/preview/<token>`. */
export const PREVIEW_LINK_PATH = "/preview/";

const TOKEN = /^[A-Za-z0-9_-]{43}$/;
const LINK_ID = /^[0-9a-f]{12}$/;
const HOUR = 60 * 60 * 1000;

export function previewLinkRoutes(adapter: SiteAdapter, store: SiteApiStore): Route[] {
  return [
    {
      method: "POST",
      pattern: /^\/preview-links$/,
      run: async (_m, _u, request) => {
        const input = await readBody(request, PreviewLinkInput);
        if (!(await adapter.content.get(input.id))) throw new NotFoundError();
        const token = base64url(crypto.getRandomValues(new Uint8Array(32)));
        const now = new Date();
        // v0.22.0: expiresInHours, up to 30 days; the v0.17.0 `hours` still works.
        if (input.expiresInHours !== undefined && input.hours !== undefined)
          throw new BadRequest("invalid", "Send expiresInHours or hours, not both.");
        const hours = input.expiresInHours ?? input.hours ?? PREVIEW_LINK_DEFAULT_HOURS;
        const expiresAt = new Date(now.getTime() + hours * HOUR).toISOString();
        await store.putPreviewLink({
          tokenHash: await sha256Hex(token),
          contentId: input.id,
          createdAt: now.toISOString(),
          expiresAt,
          revokedAt: null,
          changeId: input.changeId,
        });
        const url = new URL(`${PREVIEW_LINK_PATH}${token}`, adapter.site.origin).href;
        return json(201, checked(PreviewLink, { token, url, expiresAt }, "preview link"));
      },
    },
    {
      method: "GET",
      query: true,
      pattern: /^\/preview-links$/,
      run: async (_m, url) => {
        const { id } = readQuery(url, PreviewLinkListQuery);
        const links = await store.activePreviewLinks(id, new Date().toISOString());
        const items = links.map((l) => ({
          id: l.tokenHash.slice(0, 12),
          createdAt: l.createdAt,
          expiresAt: l.expiresAt,
        }));
        return json(200, checked(PreviewLinkList, { items }, "preview links"));
      },
    },
    {
      method: "DELETE",
      query: true,
      pattern: /^\/preview-links\/([^/]+)$/,
      run: async (m, url) => {
        const linkId = m[1]!;
        if (!LINK_ID.test(linkId)) throw new BadRequest("invalid", "The link id is not valid.");
        const { changeId } = readQuery(url, PreviewLinkRevokeQuery);
        if (!(await store.revokePreviewLink(linkId, new Date().toISOString())))
          throw new NotFoundError("No such preview link.");
        return json(
          200,
          checked(
            PreviewLinkRevokeResult,
            { id: linkId, revoked: true, changeId },
            "preview link revoke",
          ),
        );
      },
    },
  ];
}

/**
 * What a preview page may load (OWASP ASVS 5 v3.4.3): the draft's HTML is whatever the author wrote, so no script runs
 * (a pipeline that let one through would run it on the site's origin, with a link anyone holds), no plugin, no base
 * or form redirect, and no frame around it. Styles, images, fonts, media and embeds come over https only. The site's own
 * policy, if it sends one, also applies: a response is held to both.
 */
const PREVIEW_CSP =
  "default-src 'none'; script-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'; style-src https: 'unsafe-inline'; img-src https: data:; font-src https:; media-src https:; frame-src https:";

const PRIVATE = {
  "content-security-policy": PREVIEW_CSP,
  "x-robots-tag": "noindex, nofollow",
  "cache-control": "private, no-store",
  "referrer-policy": "no-referrer",
  "x-content-type-options": "nosniff",
};

export function page(status: number, message: string): Response {
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex, nofollow"><title>${message}</title></head><body><p>${message}</p></body></html>`;
  return new Response(html, {
    status,
    headers: { ...PRIVATE, "content-type": "text/html; charset=utf-8" },
  });
}

/** The page behind one link: the item's current source through the site's own preview, or a small page saying why not. */
export async function servePreviewLink(
  adapter: SiteAdapter,
  store: SiteApiStore | undefined,
  pathname: string,
): Promise<Response> {
  const token = pathname.slice(PREVIEW_LINK_PATH.length);
  const link = store && TOKEN.test(token) ? await store.previewLink(await sha256Hex(token)) : null;
  // v0.22.0: a revoked link is as if it never was (404), so its address tells nothing; one that ran out says so (410).
  if (!link || link.revokedAt) return page(404, "No such preview link.");
  if (Date.parse(link.expiresAt) <= Date.now()) return page(410, "This preview link has expired.");
  const doc = await adapter.content.get(link.contentId);
  if (!doc) return page(404, "No such preview link.");
  // A trashed item is off the site, so its links stop with it.
  if (doc.trashedAt) return page(410, "This preview link has expired.");
  const html = await adapter.preview.render({ id: doc.id, source: doc.source });
  if (typeof html !== "string") throw new ContractBreach("preview: not a string");
  return new Response(html, {
    status: 200,
    headers: { ...PRIVATE, "content-type": "text/html; charset=utf-8" },
  });
}

src/server/replay.ts.source:
// Safe retries by change id (v0.17.0), on a site that gives the package a store. A write claims its change id before it
// runs; a retry of the same request is answered with the stored answer and never runs twice, and the same id on another
// request is refused. Without a store nothing here runs, and a write is handled as in v0.14.0.

import { ChangeId } from "../contract.js";
import { sha256Hex } from "@dustinedwards/site-runtime/encoding";
import { readUpload } from "../media.js";
import type { SiteApiStore } from "../store.js";
import { BASE_HEADERS, fail, type Log } from "./http.js";

/** The writes that claim their change id: every one under content, media and mentions. */
export const REPLAYED = /^\/(content|media|mentions)(\/|$)/;

/** A claim still running after this long was left by a request that died before it answered: a retry takes it over. */
const STALE_CLAIM_MS = 2 * 60 * 1000;

/** How long an answer is kept for retries; `runSchedules` prunes older ones. */
export const REPLAY_DAYS = 7;

/**
 * Reads the write's body once (at most `cap` bytes, the route's own limit) and claims its change id. Answers either the
 * response to send now (a replay, a refusal) or the request to run, rebuilt from the bytes read, with `finish` to keep
 * what it answered. A write that carries no change id runs unclaimed; its route refuses it.
 */
export async function claim(
  store: SiteApiStore,
  request: Request,
  path: string,
  cap: number,
  log: Log,
): Promise<
  { answer: Response } | { request: Request; finish?: (response: Response) => Promise<void> }
> {
  const read = await readUpload(request, { maxBytes: cap, types: [] });
  if (!read.ok && read.refusal.code === "too-large")
    return { answer: fail("too-large", "The body is too large.") };
  const bytes = read.ok ? read.bytes : new Uint8Array();
  const rebuilt = new Request(request.url, {
    method: request.method,
    headers: request.headers,
    ...(bytes.byteLength > 0 ? { body: bytes as Uint8Array<ArrayBuffer> } : {}),
  });

  const url = new URL(request.url);
  const changeId = url.searchParams.get("changeId") ?? changeIdIn(bytes);
  if (changeId === null || !ChangeId.safeParse(changeId).success) return { request: rebuilt };

  const route = `${request.method} ${path}`;
  // The query and the body together: an upload's bytes, a delete's query, a JSON write's body.
  const search = new TextEncoder().encode(`${url.search}\n`);
  const whole = new Uint8Array(search.byteLength + bytes.byteLength);
  whole.set(search);
  whole.set(bytes, search.byteLength);
  const requestHash = await sha256Hex(whole);
  const now = Date.now();
  let held;
  try {
    held = await store.claimWrite(changeId, {
      route,
      requestHash,
      at: new Date(now).toISOString(),
      staleBefore: new Date(now - STALE_CLAIM_MS).toISOString(),
    });
  } catch (error) {
    // A write whose claim could not be made could run twice, so it does not run at all.
    log({ siteApi: "replay-store-failed", error: String(error) });
    return { answer: fail("unavailable", "The site API is unavailable.") };
  }
  if (held) {
    if (held.route !== route || held.requestHash !== requestHash)
      return {
        answer: fail("refused", "This change id was already used for a different request."),
      };
    if (held.state === "running")
      return {
        answer: fail(
          "in-progress",
          "A write under this change id is still running. Send it again once it has answered.",
        ),
      };
    const ok = held.status! >= 200 && held.status! < 300;
    return {
      answer: new Response(held.response, {
        status: held.status!,
        headers: {
          ...BASE_HEADERS,
          "content-type": ok
            ? "application/json; charset=utf-8"
            : "application/problem+json; charset=utf-8",
          "idempotent-replayed": "true",
        },
      }),
    };
  }

  return {
    request: rebuilt,
    finish: async (response) => {
      // A success and a refusal the caller acts on are kept; anything else (a site failure, a 404 that a create may
      // turn into a success) frees the id, so a retry runs again.
      const kept = response.ok || response.status === 409 || response.status === 422;
      try {
        if (kept)
          await store.finishWrite(changeId, {
            status: response.status,
            response: await response.clone().text(),
          });
        else await store.releaseWrite(changeId);
      } catch (error) {
        log({ siteApi: "replay-store-failed", changeId, error: String(error) });
      }
    },
  };
}

function changeIdIn(bytes: Uint8Array): string | null {
  try {
    const body = JSON.parse(new TextDecoder().decode(bytes)) as { changeId?: unknown };
    return typeof body?.changeId === "string" ? body.changeId : null;
  } catch {
    return null;
  }
}

src/server.ts.source:
// The site side: one handler for everything under /api/carrel/v1.
//
// Order is the guard: prefix, then rate limit, then key, then route. A request outside the prefix
// is never served, whatever key it carries; a request without the key learns nothing about routes.

import { safeEqual } from "@dustinedwards/site-runtime/compare";

import { hasContentTrash, type DueSchedule, type SiteAdapter } from "./adapter.js";
import { PREFIX } from "./contract.js";
import { Timestamp } from "./contract/base.js";
import type { ContentStatus } from "./contract.js";
import {
  hears,
  runHooks,
  type PublishAction,
  type PublishEvent,
  type PublishHook,
} from "./hooks.js";
import { contentRoutes } from "./server/content.js";
import { HookRunList, HookRunsQuery } from "./contract.js";
import {
  describeFailure,
  fail,
  json,
  checked,
  MAX_BODY_BYTES,
  readQuery,
  refuseAnyQuery,
  type Route,
} from "./server/http.js";
import { insightRoutes } from "./server/insight.js";
import { mediaRoutes } from "./server/media.js";
import { mentionsRoutes } from "./server/mentions.js";
import {
  page,
  PREVIEW_LINK_PATH,
  previewLinkRoutes,
  servePreviewLink,
} from "./server/preview-links.js";
import { claim, REPLAY_DAYS, REPLAYED } from "./server/replay.js";
import { siteApiLog } from "./log.js";
import type { SiteApiStore } from "./store.js";

export type {
  D1SiteApiStore,
  HookRetry,
  PreviewLinkRow,
  SiteApiStore,
  StoredWrite,
} from "./store.js";
export { tombstoneResponse, gonePath, tombstoned } from "./store.js";
export { PREVIEW_LINK_PATH } from "./server/preview-links.js";

/** The shape of Cloudflare's `ratelimit` binding, so a site passes its binding straight in. */
export interface RateLimiter {
  limit(options: { key: string }): Promise<{ success: boolean }>;
}

/**
 * The secrets a site holds for the API (v0.14.0), for its Env: `CARREL_SITE_KEY`, set with `wrangler secret put
 * CARREL_SITE_KEY` and passed to `createSiteApi` as `key`.
 */
export interface SiteApiSecrets {
  CARREL_SITE_KEY: string;
}

export interface SiteApiConfig {
  adapter: SiteAdapter;
  /** The site's Carrel key, from its secrets. Shorter than 32 characters refuses every request. */
  key: string | undefined;
  limiter: RateLimiter;
  /** Where refusals and adapter failures are logged. Defaults to `siteApiLog`: site-runtime's scrubbed logger, a refused request named in the OWASP vocabulary. */
  log?: (entry: Record<string, unknown>) => void;
  /**
   * Run when a public page changes (v0.10.0): a publish, an unpublish, a delete of a live item, a save or tag change to
   * a live item, and each schedule `runSchedules` applies. The first is `indexNowHook`, over Prelum's `submitIndexNow`.
   * After a request they run under its `waitUntil` when `handle` is given one, so Carrel's answer never waits on them;
   * a hook that fails is logged, never answered, and the write stands. v0.17.0: a hook may name the actions it hears
   * (`on`), and with a `store` a failed one is kept and `runSchedules` runs it again (HOOK_BACKOFF_MINUTES).
   */
  hooks?: PublishHook[];
  /**
   * Where the package keeps what it needs between requests (v0.17.0): on D1, `d1SiteApiStore(env.DB)` from
   * `@dustinedwards/site-api/store`, with `SITE_API_STORE_SQL` as a migration. With it, every write is safe to retry
   * under its change id (capabilities.replay). Absent: everything works as in v0.14.0.
   */
  store?: SiteApiStore;
}

/** What one `runSchedules` pass did. */
export interface ScheduleRun {
  applied: Array<DueSchedule & { version: string }>;
  /** Due when listed, but canceled, rescheduled or unpublished before it ran: left as the site holds it. */
  skipped: number;
  /** Threw: logged, and listed again on the next pass. */
  failed: number;
  /** The pass hit its limit, so more may be due now. */
  more: boolean;
  /** v0.17.0: items deleted for good from the content trash, TRASH_DAYS after they went there. */
  emptied: number;
  /** v0.17.0: failed publish hooks run again, where the site has a store. */
  retried: number;
}

/** How long an item stays in the content trash (v0.17.0) before `runSchedules` deletes it for good. */
export const TRASH_DAYS = 30;

/** How many schedules one pass applies at most, so a backlog drains over several passes within a Worker's limits. */
export const SCHEDULE_BATCH_LIMIT = 50;

/** The part of a Worker's ExecutionContext the handler uses. */
export interface WaitUntil {
  waitUntil(promise: Promise<unknown>): void;
}

export interface SiteApi {
  /** True when the request's path is inside the prefix. Mount the handler only where this holds. */
  matches(request: Request): boolean;
  handle(request: Request, ctx?: WaitUntil): Promise<Response>;
  /**
   * Applies every schedule due at `now` (v0.10.0) and runs the hooks for each: call it from the site's cron
   * (`scheduled()`, under `ctx.waitUntil`). Safe to run as often as wanted: an applied schedule is gone, so a second
   * pass finds nothing. A site whose adapter has no `schedules` applies nothing.
   */
  runSchedules(options?: { now?: Date; limit?: number }): Promise<ScheduleRun>;
  /**
   * `runSchedules` for a cron's job: the same pass, and it throws when a schedule failed, so the job is reported as failed
   * and the schedule is listed again next pass. Returns the run when none failed.
   */
  runSchedulesOrThrow(options?: { now?: Date; limit?: number }): Promise<ScheduleRun>;
  /** v0.17.0: true for a GET (v0.22.0: or a HEAD) under PREVIEW_LINK_PATH, outside the prefix. Mount `servePreviewLink` where this holds. */
  matchesPreviewLink(request: Request): boolean;
  /**
   * Serves a shareable preview link with no key (v0.17.0): the item's current source through the site's preview, never
   * indexed, cached or sent on as a referrer. An expired link answers 410; a revoked one (v0.22.0) and any other 404, and a
   * site with no store answers every link 404. A HEAD gets the GET's status and headers, no body. Rate limited like the API.
   */
  servePreviewLink(request: Request): Promise<Response>;
}

export const MIN_KEY_LENGTH = 32;

const DAY = 24 * 60 * 60 * 1000;

/** True for a request the site API or a preview link answers (or refuses): the only ones that need it built. */
export function isSiteApiRequest(url: URL): boolean {
  return insidePrefix(url.pathname) || url.pathname.startsWith(PREVIEW_LINK_PATH);
}

export function insidePrefix(pathname: string): boolean {
  return pathname === PREFIX || pathname.startsWith(`${PREFIX}/`);
}

// The content writes the publish hooks hear, and the action each is, by method and route.
const PAGE_WRITE =
  /^\/content\/([^/]+)(?:\/(draft|publish|unpublish|tags|trash|restore|rename|schedule))?$/;
const ACTION: Record<string, PublishAction> = {
  "PUT draft": "update",
  "PUT tags": "update",
  "POST publish": "publish",
  "POST unpublish": "unpublish",
  "DELETE ": "delete",
  "POST trash": "trash",
  "POST restore": "restore",
  "POST rename": "rename",
  "POST schedule": "schedule",
  "DELETE schedule": "unschedule",
};

/** How long a failed hook waits before each retry (v0.17.0), in minutes; after the last it is given up and logged. */
export const HOOK_BACKOFF_MINUTES = [1, 5, 30, 120, 720] as const;

const MINUTE = 60 * 1000;

function bearer(request: Request): string | null {
  const header = request.headers.get("authorization");
  const match = header?.match(/^Bearer[ ]+(\S+)\s*$/i);
  return match ? match[1]! : null;
}

export function createSiteApi(config: SiteApiConfig): SiteApi {
  const { adapter, limiter } = config;
  const log = config.log ?? siteApiLog;
  const { media, mentions, insight } = adapter;
  const { store } = config;

  const hooks: PublishHook[] = config.hooks ?? [];
  // v0.22.0: the hooks a publish of a live page runs, by name, for capabilities.hooks and the conformance probe.
  const probe: PublishEvent = {
    action: "publish",
    id: "",
    path: "/",
    url: adapter.site.origin,
    trigger: "request",
    changeId: null,
    status: "published",
  };
  const publishHooks = hooks.filter((h) => hears(h, probe)).map((h) => h.name);

  const hookRuns: Route[] = store?.hookRuns
    ? [
        {
          method: "GET",
          query: true,
          pattern: /^\/hooks\/recent$/,
          run: async (_m, url) => {
            const { changeId } = readQuery(url, HookRunsQuery);
            return json(
              200,
              checked(HookRunList, { items: await store.hookRuns!(changeId) }, "hook runs"),
            );
          },
        },
      ]
    : [];

  const routes: Route[] = [
    ...contentRoutes(adapter, { store: Boolean(store), hooks: publishHooks }),
    ...hookRuns,
    ...(media ? mediaRoutes(media, log, store) : []),
    ...(mentions ? mentionsRoutes(mentions) : []),
    ...(store ? previewLinkRoutes(adapter, store) : []),
    ...(insight ? insightRoutes(insight) : []),
  ];

  // Groups a site has not implemented. Media, mentions and insight leave this list when the adapter has them, preview
  // links when the site has a store.
  const LATER = new RegExp(
    `^/(${[...(media ? [] : ["media"]), ...(mentions ? [] : ["mentions"]), ...(insight ? [] : ["insight"]), ...(store ? [] : ["preview-links"]), ...(hookRuns.length ? [] : ["hooks"]), "inbox", "publications"].join("|")})(/|$)`,
  );

  type Page = { path: string | null; status: ContentStatus | null };

  // The item's public path and status, read before a write and after it. A draft that was never published has no page.
  async function pageOf(id: string): Promise<Page> {
    const doc = await adapter.content.get(id).catch(() => null);
    return { path: doc?.path ?? null, status: doc?.status ?? null };
  }

  // The event for one content write, from the page before it and after it. A draft that was never published has no page,
  // so its writes tell no one, except a schedule or an unschedule (v0.22.0), which a hook naming them hears with no path.
  function pageEvent(
    id: string,
    action: PublishAction,
    before: Page,
    after: Page | null,
    written: { changeId?: string },
    request: Request,
  ): PublishEvent | null {
    const path = after?.path ?? before.path;
    if (!path && action !== "schedule" && action !== "unschedule") return null;
    const moved =
      action === "rename" && before.path && path && before.path !== path ? before.path : null;
    return {
      action,
      id,
      path,
      url: path ? new URL(path, adapter.site.origin).href : null,
      trigger: "request",
      changeId: written.changeId ?? null,
      request,
      ...(before.status ? { previousStatus: before.status } : {}),
      ...(after?.status ? { status: after.status } : {}),
      ...(moved
        ? { previousPath: moved, previousUrl: new URL(moved, adapter.site.origin).href }
        : {}),
    };
  }

  /**
   * v0.22.0 (F5): the tombstones. A delete or a trash of a live item leaves its path answering 410; a publish there, or a
   * rename onto it, takes the tombstone away. The trash emptying itself keeps it. A store that cannot keep one is logged,
   * and the write stands.
   */
  async function keepTombstones(
    action: PublishAction,
    before: Page,
    after: Page | null,
  ): Promise<void> {
    if (!store?.markGone || !store.clearGone) return;
    try {
      const at = new Date().toISOString();
      if (
        (action === "delete" || action === "trash") &&
        before.status === "published" &&
        before.path
      )
        await store.markGone(before.path, at);
      if (
        (action === "publish" || action === "rename") &&
        after?.status === "published" &&
        after.path
      )
        await store.clearGone(after.path);
    } catch (error) {
      log({ siteApi: "tombstone-failed", action, error: String(error) });
    }
  }

  // v0.17.0: a hook that fails is kept for the cron to try again, where the site has a store.
  // v0.22.0: each run is kept under its change id, where the store keeps hook runs, for `GET /hooks/recent`.
  const tell = (event: PublishEvent) =>
    runHooks(
      hooks,
      event,
      log,
      async (hook, error) => {
        if (!store) return;
        const { request: _r, ...kept } = event;
        const nextAt = new Date(Date.now() + HOOK_BACKOFF_MINUTES[0]! * MINUTE).toISOString();
        await store.putHookRetry({
          id: crypto.randomUUID(),
          hook: hook.name,
          event: JSON.stringify(kept),
          attempts: 1,
          nextAt,
          lastError: error,
        });
      },
      async (hook, ok) => {
        if (store?.putHookRun && event.changeId)
          await store.putHookRun({
            changeId: event.changeId,
            hook: hook.name,
            ok,
            at: new Date().toISOString(),
          });
      },
    );

  // Each kept failure is run again when due, on its own hook only, until it works or has been tried after every backoff.
  async function retryHooks(now: Date, limit: number): Promise<number> {
    if (!store) return 0;
    let retried = 0;
    try {
      for (const retry of await store.dueHookRetries(now.toISOString(), limit)) {
        retried++;
        const hook = hooks.find((h) => h.name === retry.hook);
        let error: string | null = hook ? null : "the site no longer has this hook";
        if (hook) {
          try {
            if ((await hook.run(JSON.parse(retry.event) as PublishEvent)) === false)
              error = "the hook reported a failure";
          } catch (thrown) {
            error = thrown instanceof Error ? thrown.message : String(thrown);
          }
        }
        const wait = HOOK_BACKOFF_MINUTES[retry.attempts];
        if (error === null || wait === undefined || !hook) {
          if (error !== null)
            log({ siteApi: "hook-gave-up", hook: retry.hook, attempts: retry.attempts, error });
          await store.dropHookRetry(retry.id);
        } else {
          await store.putHookRetry({
            ...retry,
            attempts: retry.attempts + 1,
            nextAt: new Date(now.getTime() + wait * MINUTE).toISOString(),
            lastError: error,
          });
        }
      }
    } catch (error) {
      log({ siteApi: "hook-retry-failed", error: String(error) });
    }
    return retried;
  }

  // The content trash's own end (v0.17.0): items trashed more than TRASH_DAYS ago go for good, through the adapter's
  // delete with the version listed, so one changed since is refused and left. Each on its own, like a schedule.
  async function emptyTrash(now: Date, limit: number): Promise<number> {
    const { content } = adapter;
    if (!hasContentTrash(adapter)) return 0;
    const before = now.getTime() - TRASH_DAYS * DAY;
    let emptied = 0;
    let cursor: string | undefined;
    try {
      do {
        const page = await content.list({
          trashed: true,
          limit: 200,
          ...(cursor ? { cursor } : {}),
        });
        for (const item of page.items) {
          if (emptied >= limit) return emptied;
          // Only a contract timestamp past 30 days deletes: Date.parse reads "1 Oct" as 2001, so it is never asked alone.
          if (!Timestamp.safeParse(item.trashedAt).success || Date.parse(item.trashedAt!) > before)
            continue;
          if (!item.version) {
            log({
              siteApi: "trash-empty-skipped",
              id: item.id,
              reason: "the list gives no version",
            });
            continue;
          }
          const changeId = `trash-expired-${item.id}`.replace(/[^A-Za-z0-9_-]/g, "-").slice(0, 128);
          try {
            await content.delete!(item.id, { expectedVersion: item.version, changeId });
            emptied++;
          } catch (error) {
            log({
              siteApi: "trash-empty-failed",
              id: item.id,
              error: error instanceof Error ? error.message : String(error),
            });
          }
        }
        cursor = page.nextCursor ?? undefined;
      } while (cursor);
    } catch (error) {
      log({ siteApi: "trash-empty-failed", error: String(error) });
    }
    return emptied;
  }

  async function runSchedules(options: { now?: Date; limit?: number } = {}): Promise<ScheduleRun> {
    const run: ScheduleRun = {
      applied: [],
      skipped: 0,
      failed: 0,
      more: false,
      emptied: 0,
      retried: 0,
    };
    const now = options.now ?? new Date();
    if (store) {
      const before = new Date(now.getTime() - REPLAY_DAYS * DAY).toISOString();
      await store
        .pruneWrites(before)
        .catch((error) => log({ siteApi: "replay-store-failed", error: String(error) }));
      await store
        .pruneHookRuns?.(before)
        .catch((error) => log({ siteApi: "hook-runs-prune-failed", error: String(error) }));
    }
    const limit = options.limit ?? SCHEDULE_BATCH_LIMIT;
    run.emptied = await emptyTrash(now, limit);
    run.retried = await retryHooks(now, limit);
    const { schedules } = adapter;
    if (!schedules) return run;
    let due: DueSchedule[];
    try {
      due = await schedules.due({ now, limit });
    } catch (error) {
      log({ siteApi: "schedule-failed", error: String(error) });
      return { ...run, failed: 1 };
    }
    // One at a time and each on its own: one failing never stops the rest, and is listed again next pass.
    for (const item of due) {
      try {
        const written = await schedules.apply(item.id, { ...item, now });
        if (!written) {
          run.skipped++;
          continue;
        }
        run.applied.push({ ...item, version: written.version });
        const page = await pageOf(item.id);
        if (item.kind === "publish")
          await keepTombstones("publish", { path: null, status: "scheduled" }, page);
        if (page.path && page.status === "published") {
          const url = new URL(page.path, adapter.site.origin).href;
          const previousStatus = item.kind === "publish" ? "scheduled" : "published";
          await tell({
            action: item.kind,
            id: item.id,
            path: page.path,
            url,
            trigger: "schedule",
            changeId: item.changeId,
            previousStatus,
            status: "published",
          });
        }
      } catch (error) {
        run.failed++;
        log({
          siteApi: "schedule-failed",
          id: item.id,
          kind: item.kind,
          error: error instanceof Error ? error.message : String(error),
        });
      }
    }
    run.more = due.length >= limit;
    return run;
  }

  async function handle(request: Request, ctx?: WaitUntil): Promise<Response> {
    const url = new URL(request.url);
    // The URL parser has already resolved dot segments, so /api/carrel/v1/../admin arrives as /admin.
    if (!insidePrefix(url.pathname)) return fail("not-found", "Not found.");

    try {
      const ip = request.headers.get("cf-connecting-ip") ?? "unknown";
      if (!(await limiter.limit({ key: ip })).success) {
        log({ siteApi: "refused", reason: "rate-limited" });
        return fail("rate-limited", "Too many requests.");
      }
    } catch (error) {
      log({ siteApi: "refused", reason: "limiter-failed", error: String(error) });
      return fail("unavailable", "The site API is unavailable.");
    }

    const expected = config.key?.trim() ?? "";
    if (expected.length < MIN_KEY_LENGTH) {
      log({ siteApi: "refused", reason: "not-configured" });
      return fail("not-configured", "The site API is not configured.");
    }
    const presented = bearer(request);
    if (!presented || !(await safeEqual(presented, expected))) {
      log({ siteApi: "refused", reason: presented ? "wrong-key" : "no-key" });
      return fail("unauthorized", "Unauthorized.");
    }

    const path = url.pathname.slice(PREFIX.length) || "/";
    if (LATER.test(path)) return fail("not-implemented", "This group arrives in a later stage.");

    const candidates = routes
      .map((route) => ({ route, match: path.match(route.pattern) }))
      .filter((c): c is { route: Route; match: RegExpMatchArray } => c.match !== null);
    if (candidates.length === 0) return fail("not-found", "No such route.");
    const hit = candidates.find((c) => c.route.method === request.method);
    if (!hit) return fail("method-not-allowed", "Method not allowed.");

    // v0.22.0: a route that takes no query refuses one, before anything runs.
    if (!hit.route.query) {
      try {
        refuseAnyQuery(url);
      } catch (error) {
        const failure = describeFailure(error, log);
        return fail(
          failure.code,
          failure.message,
          failure.field !== undefined ? { field: failure.field } : {},
        );
      }
    }

    const write =
      (hooks.length > 0 || store?.markGone) && request.method !== "GET"
        ? PAGE_WRITE.exec(path)
        : null;
    // A malformed escape in the id is the route's to refuse (400 invalid); decoding it here would throw out of the handler.
    let id = "";
    try {
      id = write ? decodeURIComponent(write[1]!) : "";
    } catch {
      id = "";
    }
    const action = write && id ? ACTION[`${request.method} ${write[2] ?? ""}`] : undefined;
    let finish: ((response: Response) => Promise<void>) | undefined;
    let response: Response;
    try {
      let run = request;
      if (store && request.method !== "GET" && REPLAYED.test(path)) {
        const claimed = await claim(
          store,
          request,
          path,
          Math.max(MAX_BODY_BYTES, media?.limits.maxBytes ?? 0),
          log,
        );
        // A replayed answer has run its hooks already, the first time.
        if ("answer" in claimed) return claimed.answer;
        ({ request: run, finish } = claimed);
      }
      const before = action ? await pageOf(id) : null;
      response = await hit.route.run(hit.match, url, run);
      if (action && before && response.ok) {
        // A rename answers the item under its new id.
        const written = (await response.clone().json()) as { id?: string; changeId?: string };
        const now = written.id ?? id;
        const after = action === "delete" ? null : await pageOf(now);
        // The tombstone is part of the write, so a 404 handler asked the moment it answers already says 410.
        await keepTombstones(action, before, after);
        const event = pageEvent(now, action, before, after, written, request);
        if (event && hooks.length > 0) {
          const told = tell(event).catch((error) =>
            log({ siteApi: "page-change-failed", error: String(error) }),
          );
          if (ctx) ctx.waitUntil(told);
          else await told;
        }
      }
    } catch (error) {
      const failure = describeFailure(error, log);
      response = fail(failure.code, failure.message, {
        ...(failure.currentVersion !== undefined ? { currentVersion: failure.currentVersion } : {}),
        ...(failure.usedBy ? { usedBy: failure.usedBy } : {}),
        ...(failure.field !== undefined ? { field: failure.field } : {}),
      });
    }
    await finish?.(response);
    return response;
  }

  async function servePreview(request: Request): Promise<Response> {
    try {
      const ip = request.headers.get("cf-connecting-ip") ?? "unknown";
      if (!(await limiter.limit({ key: ip })).success) return page(429, "Too many requests.");
      const answer = await servePreviewLink(adapter, store, new URL(request.url).pathname);
      return request.method === "HEAD"
        ? new Response(null, { status: answer.status, headers: answer.headers })
        : answer;
    } catch (error) {
      log({
        siteApi: "preview-link-failed",
        error: error instanceof Error ? error.message : String(error),
      });
      return page(503, "This preview is unavailable.");
    }
  }

  return {
    matches: (request) => insidePrefix(new URL(request.url).pathname),
    handle,
    runSchedules,
    async runSchedulesOrThrow(options) {
      const run = await runSchedules(options);
      if (run.failed > 0) throw new Error(`${run.failed} site API schedule(s) failed`);
      return run;
    },
    // v0.22.0: HEAD as well, so a link checker's HEAD meets the same noindex answer as a browser's GET.
    matchesPreviewLink: (request) =>
      (request.method === "GET" || request.method === "HEAD") &&
      new URL(request.url).pathname.startsWith(PREVIEW_LINK_PATH),
    servePreviewLink: servePreview,
  };
}

